from decimal import Decimal

from django.db.models import Q

from .models import Account, Transaction


def recompute_account_balance(account: Account) -> Decimal:
    """Recompute cached current_balance from the transaction ledger."""
    balance = account.opening_balance
    txs = Transaction.objects.filter(
        Q(from_account=account) | Q(to_account=account), deleted_at__isnull=True
    )
    for tx in txs:
        if tx.type == "income":
            target = tx.to_account or tx.from_account
            if target and target.id == account.id:
                balance += tx.amount
        elif tx.type == "expense":
            target = tx.from_account or tx.to_account
            if target and target.id == account.id:
                balance -= tx.amount
        else:  # transfer
            if tx.from_account and tx.from_account_id == account.id:
                balance -= tx.amount
            if tx.to_account and tx.to_account_id == account.id:
                balance += tx.amount
    account.current_balance = balance
    account.save(update_fields=["current_balance", "updated_at"])
    return balance


def refresh_accounts(tx: Transaction) -> None:
    ids = set()
    if tx.from_account_id:
        ids.add(tx.from_account_id)
    if tx.to_account_id:
        ids.add(tx.to_account_id)
    for acc in Account.objects.filter(id__in=ids):
        recompute_account_balance(acc)

from rest_framework import serializers

from .models import (
    Account,
    AccountGroup,
    Budget,
    Category,
    Debt,
    ExchangeRate,
    InstallmentPlan,
    RecurringRule,
    SavingsGoal,
    Tag,
    Transaction,
)


class UserOwnedModelSerializer(serializers.ModelSerializer):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        request = self.context.get("request")
        if request is not None:
            for name, field in self.fields.items():
                if isinstance(field, serializers.PrimaryKeyRelatedField):
                    try:
                        field.queryset = field.queryset.filter(user=request.user)
                    except Exception:
                        pass


class AccountGroupSerializer(UserOwnedModelSerializer):
    class Meta:
        model = AccountGroup
        fields = ["id", "name", "created_at", "updated_at"]
        read_only_fields = ["id", "created_at", "updated_at"]


class AccountSerializer(UserOwnedModelSerializer):
    class Meta:
        model = Account
        fields = [
            "id", "group", "name", "type", "currency", "opening_balance",
            "current_balance", "credit_limit", "statement_day", "due_day",
            "archived", "created_at", "updated_at",
        ]
        read_only_fields = ["id", "current_balance", "created_at", "updated_at"]


class CategorySerializer(UserOwnedModelSerializer):
    class Meta:
        model = Category
        fields = ["id", "name", "parent", "type", "icon", "color", "is_custom"]
        read_only_fields = ["id"]


class TagSerializer(serializers.ModelSerializer):
    class Meta:
        model = Tag
        fields = ["id", "name"]
        read_only_fields = ["id"]


class TransactionSerializer(UserOwnedModelSerializer):
    class Meta:
        model = Transaction
        fields = [
            "id", "type", "amount", "currency", "fx_rate", "from_account",
            "to_account", "category", "date", "notes", "is_bookmarked",
            "tags", "recurring", "installment", "created_at", "updated_at",
        ]
        read_only_fields = ["id", "created_at", "updated_at"]


class BudgetSerializer(UserOwnedModelSerializer):
    class Meta:
        model = Budget
        fields = ["id", "category", "amount", "period", "start_date", "alert_threshold"]
        read_only_fields = ["id"]


