export interface LocalAccount {
  id: string;
  name: string;
  type: string;
  currency: string;
  opening_balance: number;
  current_balance: number;
  credit_limit?: number | null;
  archived: boolean;
  version: number;
  deleted_at: string | null;
  sync_status: "synced" | "pending" | "failed";
  updated_at: string;
}

export interface LocalCategory {
  id: string;
  name: string;
  parent_id: string | null;
  type: "income" | "expense";
  icon?: string;
  color?: string;
  is_custom: boolean;
  version: number;
  deleted_at: string | null;
  sync_status: "synced" | "pending" | "failed";
  updated_at: string;
}

export interface LocalTransaction {
  id: string;
  type: "income" | "expense" | "transfer";
  amount: number;
  currency: string;
  fx_rate: number;
  from_account_id: string | null;
  to_account_id: string | null;
  category_id: string | null;
  date: string;
  notes: string;
  is_bookmarked: boolean;
  tag_ids: string[];
  version: number;
  deleted_at: string | null;
  sync_status: "synced" | "pending" | "failed";
  updated_at: string;
}

import Dexie, { type EntityTable } from "dexie";
import type { LocalAccount, LocalCategory, LocalTransaction } from "./types";

export class FinDB extends Dexie {
  accounts!: EntityTable<LocalAccount, "id">;
  categories!: EntityTable<LocalCategory, "id">;
  transactions!: EntityTable<LocalTransaction, "id">;

  constructor() {
    super("fintrack");
    this.version(1).stores({
      accounts: "id, type, sync_status, updated_at",
      categories: "id, type, parent_id, sync_status, updated_at",
      transactions: "id, type, from_account_id, to_account_id, category_id, date, sync_status, updated_at",
    });
  }
}

export const db = new FinDB();

import { db } from "./index";
import type { LocalAccount, LocalCategory, LocalTransaction } from "./types";

export function newId(): string {
  return crypto.randomUUID();
}

export async function listAccounts(): Promise<LocalAccount[]> {
  const all = await db.accounts.toArray();
  return all
    .filter((a) => !a.deleted_at)
    .sort((a, b) => a.name.localeCompare(b.name));
}

export async function listCategories(): Promise<LocalCategory[]> {
  const all = await db.categories.toArray();
  return all.filter((c) => !c.deleted_at);
}

export async function listTransactions(): Promise<LocalTransaction[]> {
  const all = await db.transactions.toArray();
  return all
    .filter((t) => !t.deleted_at)
    .sort((a, b) => b.date.localeCompare(a.date));
}

export async function createAccount(
  input: Omit<LocalAccount, "id" | "current_balance" | "version" | "deleted_at" | "sync_status" | "updated_at">,
): Promise<LocalAccount> {
  const account: LocalAccount = {
    ...input,
    id: newId(),
    current_balance: input.opening_balance,
    version: 1,
    deleted_at: null,
    sync_status: "pending",
    updated_at: new Date().toISOString(),
  };
  await db.accounts.add(account);
  return account;
}

export async function createCategory(
  input: Omit<LocalCategory, "id" | "version" | "deleted_at" | "sync_status" | "updated_at">,
): Promise<LocalCategory> {
  const category: LocalCategory = {
    ...input,
    id: newId(),
    version: 1,
    deleted_at: null,
    sync_status: "pending",
    updated_at: new Date().toISOString(),
  };
  await db.categories.add(category);
  return category;
}

export async function createTransaction(
  input: Omit<LocalTransaction, "id" | "version" | "deleted_at" | "sync_status" | "updated_at">,
): Promise<LocalTransaction> {
  const tx: LocalTransaction = {
    ...input,
    id: newId(),
    version: 1,
    deleted_at: null,
    sync_status: "pending",
    updated_at: new Date().toISOString(),
  };
  await db.transaction("rw", db.transactions, db.accounts, async () => {
    await db.transactions.add(tx);
    await recalcBalances();
  });
  return tx;
}

export async function recalcBalances(): Promise<void> {
  const accounts = await db.accounts.toArray();
  const txs = (await db.transactions.toArray()).filter((t) => !t.deleted_at);
  for (const acc of accounts) {
    let balance = acc.opening_balance;
    for (const t of txs) {
      if (t.type === "income" && (t.to_account_id === acc.id || t.from_account_id === acc.id)) {
        balance += t.amount;
      } else if (t.type === "expense" && (t.from_account_id === acc.id || t.to_account_id === acc.id)) {
        balance -= t.amount;
      } else if (t.type === "transfer") {
        if (t.from_account_id === acc.id) balance -= t.amount;
        if (t.to_account_id === acc.id) balance += t.amount;
      }
    }
    await db.accounts.update(acc.id, { current_balance: balance });
  }
}

import { createContext, useContext, useEffect, useState, type ReactNode } from "react";

interface AuthState {
  token: string | null;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
}

const AuthContext = createContext<AuthState | null>(null);

const TOKEN_KEY = "fintrack_token";

export function AuthProvider({ children }: { children: ReactNode }) {
  const [token, setToken] = useState<string | null>(() => localStorage.getItem(TOKEN_KEY));

  useEffect(() => {
    if (token) localStorage.setItem(TOKEN_KEY, token);
    else localStorage.removeItem(TOKEN_KEY);
  }, [token]);

  async function login(email: string, password: string) {
    const base = import.meta.env.VITE_API_URL ?? "http://localhost:8000/api/v1";
    const res = await fetch(`${base}/auth/login/`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });
    if (!res.ok) throw new Error("Login failed");
    const data = await res.json();
    setToken(data.access);
  }

  function logout() {
    setToken(null);
  }

  return <AuthContext.Provider value={{ token, login, logout }}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside AuthProvider");
  return ctx;
}

import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { createAccount, listAccounts } from "../../db/repositories";

const TYPES = ["cash", "bank", "ewallet", "savings", "investment", "credit", "debit", "loan", "deposit"];

export default function AccountsPage() {
  const qc = useQueryClient();
  const { data: accounts = [] } = useQuery({ queryKey: ["accounts"], queryFn: listAccounts });
  const [name, setName] = useState("");
  const [type, setType] = useState("cash");
  const [currency, setCurrency] = useState("USD");
  const [opening, setOpening] = useState("0");

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    await createAccount({
      name,
      type,
      currency: currency.toUpperCase(),
      opening_balance: Number(opening) || 0,
      credit_limit: undefined,
      archived: false,
    });
    setName("");
    setOpening("0");
    qc.invalidateQueries({ queryKey: ["accounts"] });
  }

  return (
    <section>
      <h2 className="text-xl font-semibold mb-4">Accounts</h2>
      <form onSubmit={onSubmit} className="flex flex-wrap gap-2 mb-6">
        <input className="border rounded px-3 py-2" placeholder="Account name" value={name} onChange={(e) => setName(e.target.value)} required />
        <select className="border rounded px-3 py-2" value={type} onChange={(e) => setType(e.target.value)}>
          {TYPES.map((t) => (<option key={t} value={t}>{t}</option>))}
        </select>
        <input className="border rounded px-3 py-2 w-20" value={currency} onChange={(e) => setCurrency(e.target.value)} aria-label="Currency" />
        <input className="border rounded px-3 py-2 w-28" type="number" step="0.01" value={opening} onChange={(e) => setOpening(e.target.value)} aria-label="Opening balance" />
        <button className="bg-blue-600 text-white rounded px-4 py-2" type="submit">Add</button>
      </form>
      <ul className="space-y-2">
        {accounts.map((a) => (
          <li key={a.id} className="border rounded p-3 flex justify-between">
            <span>{a.name} <span className="text-gray-500 text-sm">({a.type}, {a.sync_status})</span></span>
            <span className="font-mono">{a.current_balance.toFixed(2)} {a.currency}</span>
          </li>
        ))}
        {accounts.length === 0 && <p className="text-gray-500">No accounts yet.</p>}
      </ul>
    </section>
  );
}

