import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { createTransaction, listAccounts, listCategories, listTransactions } from "../../db/repositories";

export default function TransactionsPage() {
  const qc = useQueryClient();
  const { data: txs = [] } = useQuery({ queryKey: ["transactions"], queryFn: listTransactions });
  const { data: accounts = [] } = useQuery({ queryKey: ["accounts"], queryFn: listAccounts });
  const { data: categories = [] } = useQuery({ queryKey: ["categories"], queryFn: listCategories });

  const [type, setType] = useState<"income" | "expense" | "transfer">("expense");
  const [amount, setAmount] = useState("");
  const [fromId, setFromId] = useState("");
  const [toId, setToId] = useState("");
  const [categoryId, setCategoryId] = useState("");
  const [notes, setNotes] = useState("");

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    const value = Number(amount);
    if (!value || value <= 0) return;
    await createTransaction({
      type,
      amount: value,
      currency: "USD",
      fx_rate: 1,
      from_account_id: type === "income" ? null : fromId || null,
      to_account_id: type === "expense" ? null : toId || fromId || null,
      category_id: categoryId || null,
      date: new Date().toISOString(),
      notes,
      is_bookmarked: false,
      tag_ids: [],
    });
    setAmount("");
    setNotes("");
    qc.invalidateQueries({ queryKey: ["transactions"] });
    qc.invalidateQueries({ queryKey: ["accounts"] });
  }

  function accountName(id: string | null) {
    return accounts.find((a) => a.id === id)?.name ?? "—";
  }

  return (
    <section>
      <h2 className="text-xl font-semibold mb-4">Transactions</h2>
      <form onSubmit={onSubmit} className="flex flex-wrap gap-2 mb-6">
        <select className="border rounded px-3 py-2" value={type} onChange={(e) => setType(e.target.value as typeof type)}>
          <option value="expense">Expense</option>
          <option value="income">Income</option>
          <option value="transfer">Transfer</option>
        </select>
        <input className="border rounded px-3 py-2 w-28" type="number" step="0.01" placeholder="Amount" value={amount} onChange={(e) => setAmount(e.target.value)} required />
        {type !== "income" && (
          <select className="border rounded px-3 py-2" value={fromId} onChange={(e) => setFromId(e.target.value)} required>
            <option value="">From account</option>
            {accounts.map((a) => (<option key={a.id} value={a.id}>{a.name}</option>))}
          </select>
        )}
        {type !== "expense" && (
          <select className="border rounded px-3 py-2" value={toId} onChange={(e) => setToId(e.target.value)}>
            <option value="">To account</option>
            {accounts.map((a) => (<option key={a.id} value={a.id}>{a.name}</option>))}
          </select>
        )}
        <select className="border rounded px-3 py-2" value={categoryId} onChange={(e) => setCategoryId(e.target.value)}>
          <option value="">Category</option>
          {categories.map((c) => (<option key={c.id} value={c.id}>{c.name}</option>))}
        </select>
        <input className="border rounded px-3 py-2 flex-1" placeholder="Notes" value={notes} onChange={(e) => setNotes(e.target.value)} />
        <button className="bg-blue-600 text-white rounded px-4 py-2" type="submit">Add</button>
      </form>
      <ul className="space-y-2">
        {txs.map((t) => (
          <li key={t.id} className="border rounded p-3 flex justify-between">
            <span>{t.type} · {accountName(t.from_account_id)} → {accountName(t.to_account_id)} {t.notes && `· ${t.notes}`}</span>
            <span className="font-mono">{t.amount.toFixed(2)} · {t.sync_status}</span>
          </li>
        ))}
        {txs.length === 0 && <p className="text-gray-500">No transactions yet.</p>}
      </ul>
    </section>
  );
}

import { NavLink, Routes, Route } from "react-router-dom";
import { useState } from "react";
import AccountsPage from "./features/accounts/AccountsPage";
import CategoriesPage from "./features/categories/CategoriesPage";
import TransactionsPage from "./features/transactions/TransactionsPage";
import { useAuth } from "./auth/AuthContext";

function Login() {
  const { login } = useAuth();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    try {
      await login(email, password);
      setError("");
    } catch {
      setError("Login failed");
    }
  }
  return (
    <form onSubmit={onSubmit} className="flex gap-2 items-center">
      <input className="border rounded px-2 py-1" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} />
      <input className="border rounded px-2 py-1" type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} />
      <button className="bg-gray-800 text-white rounded px-3 py-1" type="submit">Log in</button>
      {error && <span className="text-red-600 text-sm">{error}</span>}
    </form>
  );
}

export default function App() {
  const { token, logout } = useAuth();
  return (
    <main className="min-h-screen bg-gray-50 text-gray-900">
      <header className="bg-white border-b p-4 flex justify-between items-center">
        <h1 className="text-xl font-bold">Personal Money Manager</h1>
        {token ? (
          <button className="text-sm underline" onClick={logout}>Log out</button>
        ) : (
          <Login />
        )}
      </header>
      <nav className="p-4 flex gap-4 border-b bg-white">
        <NavLink to="/" className={({ isActive }) => (isActive ? "font-semibold" : "")}>Accounts</NavLink>
        <NavLink to="/transactions" className={({ isActive }) => (isActive ? "font-semibold" : "")}>Transactions</NavLink>
        <NavLink to="/categories" className={({ isActive }) => (isActive ? "font-semibold" : "")}>Categories</NavLink>
      </nav>
      <div className="p-4 max-w-3xl mx-auto">
        <Routes>
          <Route path="/" element={<AccountsPage />} />
          <Route path="/transactions" element={<TransactionsPage />} />
          <Route path="/categories" element={<CategoriesPage />} />
        </Routes>
      </div>
    </main>
  );
}

