def _record_event(user, entity, entity_id, version, op, payload):
    return SyncEvent.objects.create(
        user=user, entity=entity, entity_id=entity_id, version=version, op=op, payload=payload
    )


def _apply(user, m):
    entity = ENTITY_ALIASES.get(m["entity"], m["entity"])
    model = ENTITY_MAP.get(entity)
    if model is None:
        return {"client_mutation_id": m["client_mutation_id"], "status": "rejected",
                "error": {"code": "unknown_entity", "message": m["entity"]}}

    existing = SyncMutation.objects.filter(user=user, client_mutation_id=m["client_mutation_id"]).first()
    if existing:
        return {"client_mutation_id": m["client_mutation_id"], "status": existing.status,
                "server_version": existing.server_version}

    try:
        with db_transaction.atomic():
            return _apply_inner(user, model, entity, m)
    except Exception as exc:
        return {"client_mutation_id": m["client_mutation_id"], "status": "rejected",
                "error": {"code": "error", "message": str(exc)}}


def _apply_inner(user, model, entity, m):
    obj = model.objects.filter(id=m["entity_id"], user=user).first()

    if m["op"] == "delete":
        if obj is None:
            res = {"client_mutation_id": m["client_mutation_id"], "status": "accepted", "server_version": m["base_version"]}
        elif obj.deleted_at is not None:
            res = {"client_mutation_id": m["client_mutation_id"], "status": "accepted", "server_version": obj.version}
        else:
            obj.deleted_at = timezone.now()
            obj.version += 1
            obj.save(update_fields=["deleted_at", "version", "updated_at"])
            _record_event(user, entity, obj.id, obj.version, "delete", None)
            if entity == "transaction":
                refresh_accounts(obj)
            res = {"client_mutation_id": m["client_mutation_id"], "status": "accepted", "server_version": obj.version}
        SyncMutation.objects.create(user=user, client_mutation_id=m["client_mutation_id"], entity=entity,
                                    entity_id=m["entity_id"], op=m["op"], status=res["status"],
                                    server_version=res.get("server_version"))
        return res

    payload = m.get("payload", {}) or {}
    # normalize local key names
    for src, dst in [("from_account_id", "from_account"), ("to_account_id", "to_account"), ("category_id", "category"), ("parent_id", "parent")]:
        if src in payload:
            payload[dst] = payload.pop(src)

    allowed = ALLOWED_FIELDS.get(entity, set()) & set(payload.keys())
    data = {k: payload[k] for k in allowed}

    if obj is None:
        if m["op"] == "update":
            res = {"client_mutation_id": m["client_mutation_id"], "status": "conflict",
                   "error": {"code": "missing", "message": "Entity not found"}}
        else:
            obj = model(id=m["entity_id"], user=user, **data)
            obj.full_clean(exclude=["user"])
            obj.save()
            _record_event(user, entity, obj.id, obj.version, "create", payload)
            if entity == "transaction":
                refresh_accounts(obj)
            res = {"client_mutation_id": m["client_mutation_id"], "status": "accepted", "server_version": obj.version}
    else:
        if obj.deleted_at is not None:
            res = {"client_mutation_id": m["client_mutation_id"], "status": "conflict",
                   "error": {"code": "deleted", "message": "Entity was deleted"}}
        elif m["op"] == "update" and m["base_version"] != obj.version:
            res = {"client_mutation_id": m["client_mutation_id"], "status": "conflict",
                   "server_version": obj.version,
                   "error": {"code": "version_mismatch", "message": f"server at v{obj.version}"}}
        else:
            for k, v in data.items():
                setattr(obj, k, v)
            obj.version += 1
            obj.save()
            _record_event(user, entity, obj.id, obj.version, "update", payload)
            if entity == "transaction":
                refresh_accounts(obj)
            res = {"client_mutation_id": m["client_mutation_id"], "status": "accepted", "server_version": obj.version}

    SyncMutation.objects.create(user=user, client_mutation_id=m["client_mutation_id"], entity=entity,
                                entity_id=m["entity_id"], op=m["op"], status=res["status"],
                                server_version=res.get("server_version"),
                                error=res.get("error"))
    return res


class PushView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        s = PushSerializer(data=request.data)
        s.is_valid(raise_exception=True)
        results = [_apply(request.user, m) for m in s.validated_data["mutations"]]
        return Response({"results": results})


class PullView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        s = PullSerializer(data=request.data)
        s.is_valid(raise_exception=True)
        events = SyncEvent.objects.filter(user=request.user, id__gt=s.validated_data["since_seq"]).order_by("id")[:500]
        results = [
            {
                "entity": e.entity,
                "entity_id": str(e.entity_id),
                "version": e.version,
                "op": e.op,
                "payload": e.payload,
                "seq": e.id,
            }
            for e in events
        ]
        last = results[-1]["seq"] if results else s.validated_data["since_seq"]
        SyncCheckpoint.objects.update_or_create(
            user=request.user, client_id=s.validated_data["client_id"], defaults={"last_seq": last}
        )
        return Response({"server_seq": last, "changes": results})

