export const API_BASE_URL =
  import.meta.env.VITE_API_URL ?? "http://localhost:8000/api/v1";

const ACCESS_KEY = "fintrack_access";
const REFRESH_KEY = "fintrack_refresh";

export class ApiError extends Error {
  status: number;

  constructor(status: number, message: string) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}

export function getAccessToken(): string | null {
  return localStorage.getItem(ACCESS_KEY);
}

export function getRefreshToken(): string | null {
  return localStorage.getItem(REFRESH_KEY);
}

export function storeTokens(access: string, refresh: string): void {
  localStorage.setItem(ACCESS_KEY, access);
  localStorage.setItem(REFRESH_KEY, refresh);
}

export function clearTokens(): void {
  localStorage.removeItem(ACCESS_KEY);
  localStorage.removeItem(REFRESH_KEY);
}

/** Trade the refresh token for a new access token. Returns false when expired. */
export async function refreshAccessToken(): Promise<boolean> {
  const refresh = getRefreshToken();
  if (!refresh) return false;
  try {
    const res = await fetch(`${API_BASE_URL}/auth/refresh/`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refresh }),
    });
    if (!res.ok) return false;
    const data = (await res.json()) as { access?: string; refresh?: string };
    if (!data.access) return false;
    localStorage.setItem(ACCESS_KEY, data.access);
    if (data.refresh) localStorage.setItem(REFRESH_KEY, data.refresh);
    return true;
  } catch {
    return false;
  }
}

export async function apiFetch<T>(
  path: string,
  init: RequestInit = {},
  allowRetry = true,
): Promise<T> {
  const headers = new Headers(init.headers);
  if (init.body && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }
  const token = getAccessToken();
  if (token) headers.set("Authorization", `Bearer ${token}`);

  const res = await fetch(`${API_BASE_URL}${path}`, { ...init, headers });

  if (res.status === 401 && allowRetry && (await refreshAccessToken())) {
    return apiFetch<T>(path, init, false);
  }
  if (!res.ok) {
    let detail = `Request failed (${res.status})`;
    try {
      const body = (await res.json()) as Record<string, unknown>;
      if (typeof body.detail === "string") detail = body.detail;
    } catch {
      /* keep the generic message */
    }
    throw new ApiError(res.status, detail);
  }
  if (res.status === 204) return undefined as T;
  return (await res.json()) as T;
}

import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from "react";
import { apiFetch, clearTokens, getAccessToken, storeTokens } from "../api/client";

interface AuthState {
  email: string | null;
  isAuthenticated: boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthState | null>(null);

const EMAIL_KEY = "fintrack_email";

export function AuthProvider({ children }: { children: ReactNode }) {
  const [email, setEmail] = useState<string | null>(() => localStorage.getItem(EMAIL_KEY));
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() =>
    Boolean(getAccessToken()),
  );

  const login = useCallback(async (nextEmail: string, password: string) => {
    const data = await apiFetch<{ access: string; refresh: string }>("/auth/login/", {
      method: "POST",
      body: JSON.stringify({ email: nextEmail, password }),
    });
    storeTokens(data.access, data.refresh);
    localStorage.setItem(EMAIL_KEY, nextEmail);
    setEmail(nextEmail);
    setIsAuthenticated(true);
  }, []);

  const logout = useCallback(async () => {
    const refresh = localStorage.getItem("fintrack_refresh");
    if (refresh) {
      try {
        await apiFetch("/auth/logout/", {
          method: "POST",
          body: JSON.stringify({ refresh }),
        });
      } catch {
        // Logging out locally matters more than the server round-trip.
      }
    }
    clearTokens();
    localStorage.removeItem(EMAIL_KEY);
    setEmail(null);
    setIsAuthenticated(false);
  }, []);

  const value = useMemo(
    () => ({ email, isAuthenticated, login, logout }),
    [email, isAuthenticated, login, logout],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthState {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside AuthProvider");
  return ctx;
}

import type {
  EntityName,
  LocalAccount,
  LocalCategory,
  LocalTransaction,
} from "../db/types";

type Json = Record<string, unknown>;

const num = (value: unknown, fallback = 0): number => {
  if (value === null || value === undefined || value === "") return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const numOrNull = (value: unknown): number | null =>
  value === null || value === undefined || value === "" ? null : num(value);

const str = (value: unknown, fallback = ""): string =>
  typeof value === "string" ? value : fallback;

const strOrNull = (value: unknown): string | null =>
  typeof value === "string" && value.length > 0 ? value : null;

/**
 * Local rows use `<fk>_id` keys, the server uses `<fk>`. Sending uses local keys
 * (the server normalizes both), receiving needs an explicit mapping.
 */
const FK_TO_LOCAL: Record<string, string> = {
  from_account: "from_account_id",
  to_account: "to_account_id",
  category: "category_id",
  parent: "parent_id",
  group: "group_id",
  linked_account: "linked_account_id",
};

export function fromServer(
  entity: EntityName,
  payload: Json,
  version: number,
  deletedAt: string | null,
): LocalAccount | LocalCategory | LocalTransaction {
  const updated = str(payload.updated_at, new Date().toISOString());
  const base = { version, deleted_at: deletedAt, sync_status: "synced" as const, updated_at: updated };

  if (entity === "accounts") {
    return {
      ...base,
      id: str(payload.id),
      name: str(payload.name),
      type: str(payload.type, "cash"),
      currency: str(payload.currency, "USD"),
      opening_balance: num(payload.opening_balance),
      current_balance: num(payload.current_balance),
      credit_limit: numOrNull(payload.credit_limit),
      archived: Boolean(payload.archived),
    };
  }

  if (entity === "categories") {
    return {
      ...base,
      id: str(payload.id),
      name: str(payload.name),
      parent_id: strOrNull(payload.parent),
      type: payload.type === "income" ? "income" : "expense",
      icon: strOrNull(payload.icon) ?? undefined,
      color: strOrNull(payload.color) ?? undefined,
      is_custom: Boolean(payload.is_custom),
    };
  }

  return {
    ...base,
    id: str(payload.id),
    type: payload.type === "income" || payload.type === "transfer" ? payload.type : "expense",
    amount: num(payload.amount),
    currency: str(payload.currency, "USD"),
    fx_rate: num(payload.fx_rate, 1),
    from_account_id: strOrNull(payload.from_account),
    to_account_id: strOrNull(payload.to_account),
    category_id: strOrNull(payload.category),
    date: str(payload.date, updated),
    notes: str(payload.notes),
    is_bookmarked: Boolean(payload.is_bookmarked),
    tag_ids: [],
  };
}

/** Field list per entity, sent verbatim to `POST /sync/push/`. */
const PAYLOAD_FIELDS: Record<EntityName, string[]> = {
  accounts: ["name", "type", "currency", "opening_balance", "credit_limit", "archived"],
  categories: ["name", "parent_id", "type", "icon", "color", "is_custom"],
  transactions: [
    "type",
    "amount",
    "currency",
    "fx_rate",
    "from_account_id",
    "to_account_id",
    "category_id",
    "date",
    "notes",
    "is_bookmarked",
  ],
};

export function toServerPayload(entity: EntityName, row: Record<string, unknown>): Json {
  const payload: Json = {};
  for (const field of PAYLOAD_FIELDS[entity]) {
    const value = row[field];
    if (value !== undefined) payload[field] = value;
  }
  return payload;
}

export function normalizeEntityName(name: string): EntityName | null {
  switch (name) {
    case "account":
      return "accounts";
    case "category":
      return "categories";
    case "transaction":
      return "transactions";
    default:
      return null;
  }
}

export { FK_TO_LOCAL };

