import { db } from "../db";
import type { EntityName, OutboxEntry } from "../db/types";
import { toServerPayload } from "./mapping";

/** Queue a local change for the server. Coalesces with an unsent entry per row. */
export async function enqueueMutation(
  entity: EntityName,
  entityId: string,
  op: OutboxEntry["op"],
  row: Record<string, unknown> | null,
  baseVersion: number,
): Promise<void> {
  const pending = await db.outbox
    .where("entity_id")
    .equals(entityId)
    .filter((entry) => entry.status !== "conflict" && entry.op !== "delete")
    .first();

  if (pending) {
    // Same row already queued: keep the original create/insert and merge the new values.
    const mergedOp = pending.op === "create" ? "create" : op;
    await db.outbox.update(pending.id, {
      op: mergedOp,
      payload: row ? { ...pending.payload, ...toServerPayload(entity, row) } : {},
      status: "pending",
      last_error: null,
    });
    return;
  }

  await db.outbox.add({
    id: crypto.randomUUID(),
    entity,
    entity_id: entityId,
    op,
    base_version: baseVersion,
    payload: row ? toServerPayload(entity, row) : {},
    status: "pending",
    attempts: 0,
    last_error: null,
    server_version: null,
    created_at: new Date().toISOString(),
  });
}

export async function pendingMutations(limit = 50): Promise<OutboxEntry[]> {
  const entries = await db.outbox
    .filter((entry) => entry.status === "pending" || entry.status === "failed")
    .sortBy("created_at");
  return entries.slice(0, limit);
}

export async function outboxCount(): Promise<number> {
  return db.outbox.count();
}

export async function conflictEntries(): Promise<OutboxEntry[]> {
  return db.outbox.filter((entry) => entry.status === "conflict").sortBy("created_at");
}

export async function getMeta(key: string): Promise<string | null> {
  const row = await db.meta.get(key);
  return row?.value ?? null;
}

export async function setMeta(key: string, value: string): Promise<void> {
  await db.meta.put({ key, value });
}

/** Stable per-browser identifier so the server can track a pull checkpoint. */
export async function getClientId(): Promise<string> {
  const existing = await getMeta("client_id");
  if (existing) return existing;
  const clientId = `web-${crypto.randomUUID()}`;
  await setMeta("client_id", clientId);
  return clientId;
}

/** Per-account checkpoint: switching users must not reuse the previous cursor. */
export async function getCheckpoint(accountKey: string): Promise<number> {
  return Number((await getMeta(`last_seq:${accountKey}`)) ?? 0);
}

export async function setCheckpoint(accountKey: string, seq: number): Promise<void> {
  await setMeta(`last_seq:${accountKey}`, String(seq));
}

content.text:
Now the sync engine. Key parts:

```ts
export type SyncState = "idle" | "syncing" | "offline" | "error" | "unauthenticated";

let running = false;

export async function runSync(opts: { accountKey: string }): Promise<SyncState> 
```

Implementation:
1. guard: running → return "syncing"
2. if (!navigator.onLine) return "offline"
3. if (!getAccessToken()) return "unauthenticated"
4. running = true
5. push loop: get pending; if any → POST; process results; loop while more pending (cap 5 iterations)
6. pull loop: since checkpoint; POST; apply; save; if has_more loop (cap 10)
7. running = false

Apply changes:
```ts
async function applyChange(change: SyncChange) {
  const entity = normalizeEntityName(change.entity);
  if (!entity) return;
  const table = tableFor(entity);
  const existing = await table.get(change.entity_id);
  if (change.op === "delete") {
    if (existing) await table.update(change.entity_id, { deleted_at: change.payload?.deleted_at ?? new Date().toISOString(), version: change.version, sync_status: "synced", updated_at: ... });
    if (entity === "transactions" && existing) await recalcBalances();
    return;
  }
  const payload = change.payload;
  if (!payload) return;
  // detect a concurrent server change while local edits are queued
  const queued = await db.outbox.where("entity_id").equals(change.entity_id).count();
  if (queued > 0 && existing && change.version > existing.version) {
    // record conflict: mark queued entries as conflict
    await markConflict(entity, change);
    return;
  }
  const row = fromServer(entity, {...payload}, change.version, (payload.deleted_at as string) ?? null);
  await table.put({ ...(existing ?? {}), ...row, tag_ids: ... });
  if (entity === "transactions") await recalcBalances();
}
```

For tag_ids preservation: `{...existing, ...row}` — row has tag_ids: [] which would wipe. Better: build merged = {...existing, ...row} then if entity==="transactions" and existing has tag_ids → keep. Let me handle: in applyChange, after computing row, `const merged = { ...existing, ...row, tag_ids: entity === "transactions" ? ((existing as LocalTransaction)?.tag_ids ?? []) : undefined }`. Simpler: in fromServer, omit tag_ids? But for create of a new transaction from another device, tag_ids should be []. Keep `tag_ids: []` and handle preserve only when existing exists:

```ts
if (entity === "transactions" && existing && Array.isArray((existing as LocalTransaction).tag_ids)) {
  (row as LocalTransaction).tag_ids = (existing as LocalTransaction).tag_ids;
}
```

Conflict recording: mark queued entries as conflict with error message and server_version. Actually the conflict might be for the *pulled* change while a queued mutation exists. Mark the queued entries as status "conflict", last_error "server has newer version", server_version = change.version. Then the Conflicts page shows them.

Also server_version is useful for "rebase & retry": set base_version = change.version and re-push.

Conflicts page actions:
- "Keep server version": delete outbox entries for that entity_id, set local row sync_status "synced" + version = server_version (the pull already applied? no — we skipped applying). On "keep server", we should apply the server change. Implementation: drop queued entries and then... we don't have the change payload in the page. Simplest: "Keep server" → delete outbox entries, set row sync_status = "synced", version = entry.server_version, and let the next pull apply the change (since no queued entries remain, the pending change at seq > checkpoint will be applied on the next pull). Since checkpoint wasn't advanced past that change (we return before applying but we DO save the checkpoint at the end of pull...). Careful: pull saves last_seq = server_seq even for changes we skipped. That would drop the change permanently.

Fix: when skipping a change due to conflict, we must not advance the checkpoint beyond it. Approach: track `blockedSeq`: if any conflict occurred, set checkpoint to (blockedSeq - 1) so the same changes are re-delivered next time. Implement: iterate changes; if a change is blocked by a conflict, set `blocked = true` and record its seq; stop applying further changes for that entity only (but continue others), and finally set checkpoint = min(blockedSeq - 1, ...). Simpler: if blocked, checkpoint = blockedSeq - 1 (re-deliver from there next time). Duplicates are idempotent on apply.

Alternatively store the conflicted payload in a `conflicts` table so the page can show and apply server version without waiting. That's cleaner for UX: conflicts table with { id, entity, entity_id, op, server_version, payload, message, created_at }. Let me do that: `conflicts` table in version 2? I already defined version 2 stores without conflicts. I can add `conflicts` to version 2 stores (schema not yet deployed anywhere — it's still just code; the Dexie DB upgrade hasn't happened in a real browser). So add `conflicts: "id, entity, entity_id, created_at"` to version 2.

So:
- outbox entry status "conflict" + conflicts row holding server state → Conflicts page: 
  - "Use server version" → delete outbox entries for entity_id, delete conflicts row, apply server payload locally (put row), recalc.
  - "Keep my version" → delete conflicts row, set queued outbox entry base_version = server_version, status pending → next sync pushes with correct base.

That's clean. And checkpoint advancement: since we saved the server payload in conflicts, we can advance the checkpoint freely.

Let me add conflicts table type:

```ts
export interface ConflictEntry {
  id: string;
  entity: EntityName;
  entity_id: string;
  op: SyncChange["op"];
  server_version: number;
  payload: Json | null;
  message: string;
  created_at: string;
}
```

Now writing syncEngine.ts. Also need `recalcBalances` from repositories — careful about circular imports: repositories imports outbox (enqueueMutation) and syncEngine imports repositories (recalcBalances). Circular ESM imports can be okay but risky. Let me move `recalcBalances` into its own module `db/balances.ts` and have repositories re-export it. Then syncEngine imports db/balances, repositories imports db/balances + outbox. No cycle: syncEngine → balances, outbox, mapping, api/client. repositories → balances, outbox. Good.

Also transactions.tsx imports repositories + SyncContext. Fine.

Let me now write:
1. `db/balances.ts` — recalcBalances (moved).
2. `db/repositories.ts` — rewrite with create/update/delete + outbox enqueue.
3. `sync/syncEngine.ts`.
4. `sync/SyncContext.tsx`.
5. `features/conflicts/ConflictsPage.tsx`.
6. `App.tsx` + page updates.
7. test setup wrap.

