import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useAuth } from "../auth/AuthContext";
import { db } from "../db";
import type { ConflictEntry } from "../db/types";
import { runSync, type SyncState } from "./syncEngine";

const SYNC_INTERVAL_MS = 30_000;

interface SyncContextValue {
  status: SyncState;
  pendingCount: number;
  conflicts: ConflictEntry[];
  lastSyncedAt: Date | null;
  syncNow: () => Promise<void>;
}

const SyncContext = createContext<SyncContextValue | null>(null);

export function SyncProvider({ children }: { children: ReactNode }) {
  const { isAuthenticated, email } = useAuth();
  const queryClient = useQueryClient();
  const [status, setStatus] = useState<SyncState>("idle");
  const [pendingCount, setPendingCount] = useState(0);
  const [conflicts, setConflicts] = useState<ConflictEntry[]>([]);
  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null);

  const accountKey = email ?? "anonymous";

  const syncNow = useCallback(async () => {
    const next = await runSync(accountKey);
    setStatus(next);
    if (next === "idle") {
      setLastSyncedAt(new Date());
      setPendingCount(await db.outbox.count());
      setConflicts(await db.conflicts.toArray());
      void queryClient.invalidateQueries();
    }
  }, [accountKey, queryClient]);

  useEffect(() => {
    if (!isAuthenticated) {
      setStatus("signed-out");
      return;
    }
    void syncNow();
  }, [isAuthenticated, syncNow]);

  useEffect(() => {
    if (!isAuthenticated) return;
    const onOnline = () => void syncNow();
    window.addEventListener("online", onOnline);
    const timer = window.setInterval(() => void syncNow(), SYNC_INTERVAL_MS);
    return () => {
      window.removeEventListener("online", onOnline);
      window.clearInterval(timer);
    };
  }, [isAuthenticated, syncNow]);

  const value = useMemo(
    () => ({ status, pendingCount, conflicts, lastSyncedAt, syncNow }),
    [status, pendingCount, conflicts, lastSyncedAt, syncNow],
  );

  return <SyncContext.Provider value={value}>{children}</SyncContext.Provider>;
}

export function useSync(): SyncContextValue {
  const ctx = useContext(SyncContext);
  if (!ctx) throw new Error("useSync must be used inside SyncProvider");
  return ctx;
}

import { useSync } from "../../sync/SyncContext";
import { resolveWithLocal, resolveWithServer } from "../../sync/syncEngine";
import { useQueryClient } from "@tanstack/react-query";

export default function ConflictsPage() {
  const { conflicts, syncNow } = useSync();
  const queryClient = useQueryClient();

  async function resolve(id: string, action: "server" | "local") {
    if (action === "server") {
      await resolveWithServer(id);
    } else {
      await resolveWithLocal(id);
    }
    void queryClient.invalidateQueries();
    void syncNow();
  }

  return (
    <section>
      <h2 className="text-xl font-semibold mb-1">Conflicts</h2>
      <p className="text-sm text-muted mb-4">
        Records changed on the server while this device had unsynced edits.
      </p>
      <ul className="space-y-3">
        {conflicts.map((conflict) => (
          <li key={conflict.id} className="card">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <div>
                <p className="font-medium">
                  {conflict.entity.replace(/s$/, "")} · {conflict.entity_id.slice(0, 8)}
                </p>
                <p className="text-sm text-muted">{conflict.message}</p>
                <p className="text-xs text-muted">
                  server version {conflict.server_version} · local op {conflict.op}
                </p>
              </div>
              <div className="flex gap-2">
                <button className="btn-ghost" onClick={() => void resolve(conflict.id, "server")}>
                  Use server
                </button>
                <button className="btn-primary" onClick={() => void resolve(conflict.id, "local")}>
                  Keep mine
                </button>
              </div>
            </div>
          </li>
        ))}
        {conflicts.length === 0 && <p className="text-muted">No conflicts.</p>}
      </ul>
    </section>
  );
}

import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { deleteAccount, listAccounts, updateAccount } from "../../db/repositories";
import type { LocalAccount } from "../../db/types";
import { SyncBadge } from "../../sync/SyncBadge";

const TYPES = ["cash", "bank", "ewallet", "savings", "investment", "credit", "debit", "loan", "deposit"];

function SyncStateBadge({ row }: { row: LocalAccount }) {
  if (row.sync_status === "synced") return <span className="badge-synced">synced</span>;
  if (row.sync_status === "pending") return <span className="badge-pending">pending</span>;
  return <span className="badge-failed">failed</span>;
}

export default function AccountsPage() {
  const queryClient = useQueryClient();
  const { data: accounts = [] } = useQuery({ queryKey: ["accounts"], queryFn: listAccounts });
  const [name, setName] = useState("");
  const [type, setType] = useState("cash");
  const [currency, setCurrency] = useState("USD");
  const [opening, setOpening] = useState("0");

  const invalidate = () => queryClient.invalidateQueries({ queryKey: ["accounts"] });

  const rename = useMutation({
    mutationFn: ({ id, nextName }: { id: string; nextName: string }) => updateAccount(id, { name: nextName }),
    onSettled: () => void invalidate(),
  });

  const remove = useMutation({
    mutationFn: (id: string) => deleteAccount(id),
    onSettled: () => void invalidate(),
  });

  return (
    <section>
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-semibold">Accounts</h2>
        <SyncBadge />
      </div>

      <form
        className="card mb-6 flex flex-wrap items-end gap-2"
        onSubmit={async (event) => {
          event.preventDefault();
          const { createAccount } = await import("../../db/repositories");
          await createAccount({
            name,
            type,
            currency: currency.toUpperCase(),
            opening_balance: Number(opening) || 0,
          });
          setName("");
          setOpening("0");
          void invalidate();
        }}
      >
        <label className="flex flex-col gap-1 text-sm text-muted">
          Name
          <input
            className="input"
            placeholder="Account name"
            value={name}
            onChange={(event) => setName(event.target.value)}
            required
          />
        </label>
        <label className="flex flex-col gap-1 text-sm text-muted">
          Type
          <select className="input" value={type} onChange={(event) => setType(event.target.value)}>
            {TYPES.map((option) => (
              <option key={option} value={option}>
                {option}
              </option>
            ))}
          </select>
        </label>
        <label className="flex flex-col gap-1 text-sm text-muted">
          Currency
          <input
            className="input w-24"
            value={currency}
            maxLength={3}
            onChange={(event) => setCurrency(event.target.value)}
          />
        </label>
        <label className="flex flex-col gap-1 text-sm text-muted">
          Opening balance
          <input
            className="input w-36"
            type="number"
            step="0.01"
            value={opening}
            onChange={(event) => setOpening(event.target.value)}
          />
        </label>
        <button className="btn-primary" type="submit">
          Add account
        </button>
      </form>

      <ul className="space-y-2">
        {accounts.map((account) => (
          <li key={account.id} className="card flex flex-wrap items-center justify-between gap-3">
            <div>
              <p className="font-medium">{account.name}</p>
              <p className="text-xs text-muted">
                {account.type} · {account.currency}
              </p>
            </div>
            <div className="flex items-center gap-3">
              <SyncStateBadge row={account} />
              <span className="font-mono text-lg">
                {account.current_balance.toFixed(2)} {account.currency}
              </span>
              <button
                className="btn-ghost"
                onClick={() => {
                  const nextName = window.prompt("Account name", account.name);
                  if (nextName && nextName !== account.name) {
                    rename.mutate({ id: account.id, nextName });
                  }
                }}
              >
                Edit
              </button>
              <button className="btn-danger" onClick={() => remove.mutate(account.id)}>
                Delete
              </button>
            </div>
          </li>
        ))}
        {accounts.length === 0 && <p className="text-muted">No accounts yet.</p>}
      </ul>
    </section>
  );
}

