import type { SyncStatus } from "../db/types";
import { useSync } from "./SyncContext";

export function SyncStateBadge({ status }: { status: SyncStatus }) {
  if (status === "synced") return <span className="badge-synced">synced</span>;
  if (status === "pending") return <span className="badge-pending">pending</span>;
  return <span className="badge-failed">failed</span>;
}

const LABELS: Record<string, string> = {
  idle: "up to date",
  syncing: "syncing…",
  offline: "offline",
  "signed-out": "signed out",
  error: "sync error",
};

export function SyncBadge() {
  const { status, pendingCount, conflicts, lastSyncedAt, syncNow } = useSync();
  const cls =
    status === "idle"
      ? "badge-synced"
      : status === "error"
        ? "badge-failed"
        : status === "syncing"
          ? "badge-pending"
          : "badge-idle";

  return (
    <button
      className={`${cls} gap-2`}
      onClick={() => void syncNow()}
      title={lastSyncedAt ? `Last synced ${lastSyncedAt.toLocaleTimeString()}` : "Not synced yet"}
    >
      {LABELS[status] ?? status}
      {pendingCount > 0 && <span className="text-warning">· {pendingCount} queued</span>}
      {conflicts.length > 0 && <span className="text-negative">· {conflicts.length} conflicts</span>}
    </button>
  );
}

import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  createCategory,
  deleteCategory,
  listCategories,
  updateCategory,
} from "../../db/repositories";
import type { LocalCategory } from "../../db/types";
import { SyncStateBadge } from "../../sync/SyncStateBadge";

export default function CategoriesPage() {
  const queryClient = useQueryClient();
  const { data: categories = [] } = useQuery({ queryKey: ["categories"], queryFn: listCategories });
  const [name, setName] = useState("");
  const [type, setType] = useState<"income" | "expense">("expense");

  const invalidate = () => queryClient.invalidateQueries({ queryKey: ["categories"] });

  const create = useMutation({
    mutationFn: () => createCategory({ name, type }),
    onSuccess: () => setName(""),
    onSettled: () => void invalidate(),
  });

  const rename = useMutation({
    mutationFn: ({ id, nextName }: { id: string; nextName: string }) => updateCategory(id, { name: nextName }),
    onSettled: () => void invalidate(),
  });

  const remove = useMutation({
    mutationFn: (id: string) => deleteCategory(id),
    onSettled: () => void invalidate(),
  });

  return (
    <section>
      <h2 className="text-xl font-semibold mb-4">Categories</h2>
      <form
        className="card mb-6 flex flex-wrap items-end gap-2"
        onSubmit={(event) => {
          event.preventDefault();
          create.mutate();
        }}
      >
        <label className="flex flex-1 flex-col gap-1 text-sm text-muted">
          Name
          <input
            className="input"
            placeholder="Category name"
            value={name}
            onChange={(event) => setName(event.target.value)}
            required
          />
        </label>
        <label className="flex flex-col gap-1 text-sm text-muted">
          Type
          <select
            className="input"
            value={type}
            onChange={(event) => setType(event.target.value as "income" | "expense")}
          >
            <option value="expense">Expense</option>
            <option value="income">Income</option>
          </select>
        </label>
        <button className="btn-primary" type="submit" disabled={!name}>
          Add category
        </button>
      </form>

      <ul className="space-y-2">
        {categories.map((category: LocalCategory) => (
          <li key={category.id} className="card flex items-center justify-between gap-3">
            <div>
              <p className="font-medium">{category.name}</p>
              <p className="text-xs text-muted">{category.type}</p>
            </div>
            <div className="flex items-center gap-2">
              <SyncStateBadge status={category.sync_status} />
              <button
                className="btn-ghost"
                onClick={() => {
                  const nextName = window.prompt("Category name", category.name);
                  if (nextName && nextName !== category.name) {
                    rename.mutate({ id: category.id, nextName });
                  }
                }}
              >
                Edit
              </button>
              <button className="btn-danger" onClick={() => remove.mutate(category.id)}>
                Delete
              </button>
            </div>
          </li>
        ))}
        {categories.length === 0 && <p className="text-muted">No categories yet.</p>}
      </ul>
    </section>
  );
}

import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  createTransaction,
  deleteTransaction,
  listAccounts,
  listCategories,
  listTransactions,
} from "../../db/repositories";
import type { LocalTransaction } from "../../db/types";
import { SyncStateBadge } from "../../sync/SyncStateBadge";

type TxType = "income" | "expense" | "transfer";

export default function TransactionsPage() {
  const queryClient = useQueryClient();
  const { data: txs = [] } = useQuery({ queryKey: ["transactions"], queryFn: listTransactions });
  const { data: accounts = [] } = useQuery({ queryKey: ["accounts"], queryFn: listAccounts });
  const { data: categories = [] } = useQuery({ queryKey: ["categories"], queryFn: listCategories });

  const [type, setType] = useState<TxType>("expense");
  const [amount, setAmount] = useState("");
  const [fromId, setFromId] = useState("");
  const [toId, setToId] = useState("");
  const [categoryId, setCategoryId] = useState("");
  const [notes, setNotes] = useState("");

  const invalidate = () => {
    void queryClient.invalidateQueries({ queryKey: ["transactions"] });
    void queryClient.invalidateQueries({ queryKey: ["accounts"] });
  };

  const create = useMutation({
    mutationFn: () =>
      createTransaction({
        type,
        amount: Number(amount),
        currency: "USD",
        fx_rate: 1,
        from_account_id: type === "income" ? null : fromId || null,
        to_account_id: type === "expense" ? null : toId || fromId || null,
        category_id: categoryId || null,
        date: new Date().toISOString(),
        notes,
      }),
    onSuccess: () => {
      setAmount("");
      setNotes("");
    },
    onSettled: invalidate,
  });

  const remove = useMutation({
    mutationFn: (id: string) => deleteTransaction(id),
    onSettled: invalidate,
  });

  const accountName = (id: string | null) => accounts.find((a) => a.id === id)?.name ?? "—";
  const accountCurrency = (id: string | null) => accounts.find((a) => a.id === id)?.currency ?? "USD";

  return (
    <section>
      <h2 className="text-xl font-semibold mb-4">Transactions</h2>

      <form
        className="card mb-6 flex flex-wrap items-end gap-2"
        onSubmit={(event) => {
          event.preventDefault();
          create.mutate();
        }}
      >
        <label className="flex flex-col gap-1 text-sm text-muted">
          Type
          <select className="input" value={type} onChange={(event) => setType(event.target.value as TxType)}>
            <option value="expense">Expense</option>
            <option value="income">Income</option>
            <option value="transfer">Transfer</option>
          </select>
        </label>
        <label className="flex flex-col gap-1 text-sm text-muted">
          Amount
          <input
            className="input w-32"
            type="number"
            step="0.01"
            placeholder="0.00"
            value={amount}
            onChange={(event) => setAmount(event.target.value)}
            required
          />
        </label>
        {type !== "income" && (
          <label className="flex flex-col gap-1 text-sm text-muted">
            From account
            <select
              className="input"
              value={fromId}
              onChange={(event) => setFromId(event.target.value)}
              required
            >
              <option value="">Select…</option>
              {accounts.map((account) => (
                <option key={account.id} value={account.id}>
                  {account.name}
                </option>
              ))}
            </select>
          </label>
        )}
        {type !== "expense" && (
          <label className="flex flex-col gap-1 text-sm text-muted">
            To account
            <select className="input" value={toId} onChange={(event) => setToId(event.target.value)}>
              <option value="">Select…</option>
              {accounts.map((account) => (
                <option key={account.id} value={account.id}>
                  {account.name}
                </option>
              ))}
            </select>
          </label>
        )}
        {type !== "transfer" && (
          <label className="flex flex-col gap-1 text-sm text-muted">
            Category
            <select className="input" value={categoryId} onChange={(event) => setCategoryId(event.target.value)}>
              <option value="">None</option>
              {categories
                .filter((category) => category.type === (type === "income" ? "income" : "expense"))
                .map((category) => (
                  <option key={category.id} value={category.id}>
                    {category.name}
                  </option>
                ))}
            </select>
          </label>
        )}
        <label className="flex flex-1 flex-col gap-1 text-sm text-muted">
          Notes
          <input className="input" placeholder="Notes" value={notes} onChange={(event) => setNotes(event.target.value)} />
        </label>
        <button className="btn-primary" type="submit">
          Add transaction
        </button>
      </form>

      <ul className="space-y-2">
        {txs.map((tx: LocalTransaction) => (
          <li key={tx.id} className="card flex flex-wrap items-center justify-between gap-3">
            <div>
              <p className="font-medium">
                {tx.type === "income" ? "←" : tx.type === "expense" ? "→" : "⇄"}{" "}
                {accountName(tx.from_account_id)} → {accountName(tx.to_account_id)}
              </p>
              <p className="text-xs text-muted">
                {new Date(tx.date).toLocaleString()}
                {tx.notes ? ` · ${tx.notes}` : ""}
              </p>
            </div>
            <div className="flex items-center gap-2">
              <SyncStateBadge status={tx.sync_status} />
              <span
                className={`font-mono text-lg ${
                  tx.type === "income" ? "text-positive" : tx.type === "expense" ? "text-negative" : ""
                }`}
              >
                {tx.type === "expense" ? "-" : tx.type === "income" ? "+" : ""}
                {tx.amount.toFixed(2)} {accountCurrency(tx.to_account_id ?? tx.from_account_id)}
              </span>
              <button className="btn-danger" onClick={() => remove.mutate(tx.id)}>
                Delete
              </button>
            </div>
          </li>
        ))}
        {txs.length === 0 && <p className="text-muted">No transactions yet.</p>}
      </ul>
    </section>
  );
}

import { NavLink, Route, Routes } from "react-router-dom";
import { useState } from "react";
import AccountsPage from "./features/accounts/AccountsPage";
import CategoriesPage from "./features/categories/CategoriesPage";
import ConflictsPage from "./features/conflicts/ConflictsPage";
import TransactionsPage from "./features/transactions/TransactionsPage";
import { useAuth } from "./auth/AuthContext";
import { SyncBadge } from "./sync/SyncStateBadge";

function LoginForm() {
  const { login } = useAuth();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  async function onSubmit(event: React.FormEvent) {
    event.preventDefault();
    setBusy(true);
    setError("");
    try {
      await login(email, password);
    } catch {
      setError("Login failed - check your email and password.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <form className="flex flex-wrap items-center gap-2" onSubmit={onSubmit}>
      <input
        className="input"
        type="email"
        autoComplete="email"
        placeholder="Email"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        required
      />
      <input
        className="input"
        type="password"
        autoComplete="current-password"
        placeholder="Password"
        value={password}
        onChange={(event) => setPassword(event.target.value)}
        required
      />
      <button className="btn-primary" type="submit" disabled={busy}>
        {busy ? "Signing in…" : "Log in"}
      </button>
      {error && <span className="text-sm text-negative">{error}</span>}
    </form>
  );
}

const navClass = ({ isActive }: { isActive: boolean }) =>
  isActive ? "nav-link nav-link-active" : "nav-link";

export default function App() {
  const { isAuthenticated, email, logout } = useAuth();

  return (
    <div className="min-h-screen">
      <header className="border-b border-line bg-surface">
        <div className="mx-auto flex max-w-4xl flex-wrap items-center justify-between gap-3 px-4 py-3">
          <h1 className="text-lg font-bold text-primary">Personal Money Manager</h1>
          <div className="flex items-center gap-3">
            {isAuthenticated && <SyncBadge />}
            {isAuthenticated ? (
              <div className="flex items-center gap-2">
                <span className="hidden text-sm text-muted sm:inline">{email}</span>
                <button className="btn-ghost" onClick={() => void logout()}>
                  Log out
                </button>
              </div>
            ) : (
              <LoginForm />
            )}
          </div>
        </div>
        <nav className="mx-auto flex max-w-4xl gap-1 px-4 pb-3">
          <NavLink to="/" end className={navClass}>
            Accounts
          </NavLink>
          <NavLink to="/transactions" className={navClass}>
            Transactions
          </NavLink>
          <NavLink to="/categories" className={navClass}>
            Categories
          </NavLink>
          <NavLink to="/conflicts" className={navClass}>
            Conflicts
          </NavLink>
        </nav>
      </header>

      <main className="mx-auto max-w-4xl px-4 py-6">
        <Routes>
          <Route path="/" element={<AccountsPage />} />
          <Route path="/transactions" element={<TransactionsPage />} />
          <Route path="/categories" element={<CategoriesPage />} />
          <Route path="/conflicts" element={<ConflictsPage />} />
        </Routes>
      </main>
    </div>
  );
}

