export async function enqueueMutation(
  entity: EntityName,
  entityId: string,
  op: OutboxEntry["op"],
  row: Record<string, unknown> | null,
  baseVersion: number,
): Promise<void> {
  const pending = await db.outbox
    .where("entity_id")
    .equals(entityId)
    .filter((entry) => entry.status !== "conflict" && entry.op !== "delete")
    .first();

  if (pending) {
    // Same row already queued: keep the original create/insert and merge the new values.
    const mergedOp = pending.op === "create" ? "create" : op;
    await db.outbox.update(pending.id, {
      op: mergedOp,
      payload: row ? { ...pending.payload, ...toServerPayload(entity, row) } : {},
      status: "pending",
      last_error: null,
    });
    return;
  }

  await db.outbox.add({
    id: crypto.randomUUID(),
    entity,
    entity_id: entityId,
    op,
    base_version: baseVersion,
    payload: row ? toServerPayload(entity, row) : {},
    status: "pending",
    attempts: 0,
    last_error: null,
    server_version: null,
    created_at: new Date().toISOString(),
  });
}

