def _json_safe(value):
    """DRF leaves related pks as UUID objects; JSONField needs primitives."""
    if isinstance(value, dict):
        return {key: _json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe(item) for item in value]
    if isinstance(value, (UUID, Decimal)):
        return str(value)
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    return value


def _record_event(user, entity, obj, op):
    payload = _json_safe(dict(_serializer_for(ENTITY_MAP[entity])(obj).data))
    payload["version"] = obj.version
    payload["deleted_at"] = obj.deleted_at.isoformat() if obj.deleted_at else None
    return SyncEvent.objects.create(
        user=user,
        entity=entity,
        entity_id=obj.id,
        version=obj.version,
        op=op,
        payload=payload,
    )

