136: async function applyChange(change: SyncChange): Promise<void> {
137:   const entity = normalizeEntityName(change.entity);
138:   if (!entity) return;
139:   const existing = (await tableFor(entity).get(change.entity_id)) as LocalTransaction | undefined;
140: 
141:   if (change.op === "delete") {
142:     if (existing) {
143:       const deletedAt =
144:         typeof change.payload?.deleted_at === "string"
145:           ? change.payload.deleted_at
146:           : new Date().toISOString();
147:       await patchRow(entity, change.entity_id, {
148:         deleted_at: deletedAt,
149:         version: change.version,
150:         sync_status: "synced",
151:         updated_at: new Date().toISOString(),
152:       });
153:     }
154:     if (entity === "transactions") await recalcBalances();
155:     return;
156:   }
157: 
158:   if (!change.payload) return;
159: 
160:   const queued = await db.outbox
161:     .where("entity_id")
162:     .equals(change.entity_id)
163:     .filter((entry) => entry.status === "pending" || entry.status === "failed")
164:     .count();
165: 
166:   if (queued > 0 && existing && change.version > existing.version) {
167:     // Server moved ahead while this device still has unsynced edits.
168:     await recordConflict(
169:       entity,
170:       change.entity_id,
171:       change.op,
172:       change.version,
173:       change.payload,
174:       "Server changed this record while you had unsynced edits",
175:     );
176:     for (const entry of await db.outbox.where("entity_id").equals(change.entity_id).toArray()) {
177:       await db.outbox.update(entry.id, {
178:         status: "conflict",
179:         server_version: change.version,
180:         last_error: "Server changed this record while you had unsynced edits",
181:       });
182:     }
183:     return;
184:   }
185: 
186:   const row = fromServer(entity, change.payload, change.version, null);
187:   const merged = { ...(existing ?? {}), ...row } as LocalTransaction;
188:   if (entity === "transactions" && Array.isArray(existing?.tag_ids)) {
189:     merged.tag_ids = existing?.tag_ids ?? [];
190:   }
191:   await putRow(entity, merged);
192:   if (entity === "transactions") await recalcBalances();
193: }
