209: async function runSyncInternal(accountKey: string): Promise<SyncState> {
210:   if (typeof navigator !== "undefined" && !navigator.onLine) return "offline";
211:   if (!getAccessToken()) return "signed-out";
212: 
213:   try {
214:     const clientId = await getClientId();
215:     for (let round = 0; round < MAX_PUSH_ROUNDS; round += 1) {
216:       const pushed = await pushRound(clientId);
217:       if (!pushed) break;
218:     }
219:     for (let round = 0; round < MAX_PULL_ROUNDS; round += 1) {
220:       const more = await pullRound(clientId, accountKey);
221:       if (!more) break;
222:     }
223:     return "idle";
224:   } catch (error) {
225:     if (error instanceof ApiError && error.status === 401) return "signed-out";
226:     return "error";
227:   }
228: }
