/* ---------------------------------------------------------------------- progress */

export function ProgressBar({
  value,
  tone = "primary",
  size = "md",
  label,
  showOverflow = true,
}: {
  /** 0-100+. Values above 100 are clamped for the bar but flagged. */
  value: number;
  tone?: "primary" | "income" | "expense" | "warning" | "info";
  size?: "xs" | "sm" | "md";
  label?: string;
  showOverflow?: boolean;
}) {
  const clamped = Math.max(0, Math.min(100, Number.isFinite(value) ? value : 0));
  const over = value > 100;
  const height = { xs: "h-1", sm: "h-1.5", md: "h-2.5" }[size];
  const fill = over
    ? "bg-expense"
    : {
        primary: "bg-primary",
        income: "bg-income",
        expense: "bg-expense",
        warning: "bg-warning",
        info: "bg-info",
      }[tone];

  return (
    <div
      role="progressbar"
      aria-valuenow={Math.round(value)}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-label={label}
      className={`w-full overflow-hidden rounded-full bg-surface-sunken ${height}`}
    >
      <div
        className={`h-full rounded-full transition-[width] duration-500 ease-smooth ${fill} ${showOverflow && over ? "" : ""}`}
        style={{ width: `${clamped}%` }}
      />
    </div>
  );
}

