import { useEffect, useRef, useState, type ReactNode } from "react";
import { ChevronDown } from "lucide-react";
import { currencySymbol, parseNumber } from "../../design/format";
import { IconButton } from "./Button";

/* -------------------------------------------------------------- AmountInput */

/**
 * The single most-used control in a finance app. Large, numeric-keyboard friendly,
 * and visually dominant - the amount is the point of the form.
 */
export function AmountInput({
  value,
  onChange,
  currency = "USD",
  tone = "default",
  autoFocus,
  id,
  size = "lg",
  disabled,
}: {
  value: number;
  onChange: (value: number) => void;
  currency?: string;
  tone?: "default" | "income" | "expense";
  autoFocus?: boolean;
  id?: string;
  size?: "md" | "lg";
  disabled?: boolean;
}) {
  const [text, setText] = useState(() => (value ? value.toFixed(2) : ""));
  const focused = useRef(false);

  useEffect(() => {
    if (focused.current) return;
    setText(value ? value.toFixed(2) : "");
  }, [value]);

  const toneClass =
    tone === "income" ? "text-income" : tone === "expense" ? "text-expense" : "text-ink";
  const textSize = size === "lg" ? "text-display-sm" : "text-title";

  return (
    <div className="flex items-baseline gap-1.5 border-b-2 border-line pb-1 transition-colors focus-within:border-primary">
      <span aria-hidden="true" className={`${textSize} font-medium text-muted`}>
        {currencySymbol(currency)}
      </span>
      <input
        id={id}
        type="text"
        inputMode="decimal"
        autoComplete="off"
        autoFocus={autoFocus}
        disabled={disabled}
        aria-label="Amount"
        value={text}
        onFocus={() => {
          focused.current = true;
        }}
        onBlur={() => {
          focused.current = false;
          setText(value ? value.toFixed(2) : "");
        }}
        onChange={(event) => {
          const next = event.target.value.replace(/[^0-9.]/g, "");
          if ((next.match(/\./g) ?? []).length > 1) return;
          setText(next);
          onChange(parseNumber(next));
        }}
        placeholder="0.00"
        className={`tabular w-full min-w-0 bg-transparent font-semibold tracking-tight outline-none ${textSize} ${toneClass} placeholder:text-faint`}
      />
      {text && !disabled && (
        <IconButton label="Clear amount" size="sm" onClick={() => { setText(""); onChange(0); }}>
          <span aria-hidden="true" className="text-xs font-medium text-muted">
            Clear
          </span>
        </IconButton>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------------- Tabs */

export interface TabItem<T extends string> {
  id: T;
  label: string;
  count?: number;
  icon?: ReactNode;
}

export function Tabs<T extends string>({
  items,
  value,
  onChange,
  size = "md",
  className = "",
  ariaLabel,
}: {
  items: TabItem<T>[];
  value: T;
  onChange: (id: T) => void;
  size?: "sm" | "md";
  className?: string;
  ariaLabel: string;
}) {
  return (
    <div role="tablist" aria-label={ariaLabel} className={`scroll-area -mx-1 flex gap-1 px-1 ${className}`}>
      {items.map((item) => {
        const active = item.id === value;
        return (
          <button
            key={item.id}
            role="tab"
            type="button"
            aria-selected={active}
            onClick={() => onChange(item.id)}
            className={`flex shrink-0 items-center gap-1.5 rounded-lg font-medium transition-colors ${
              size === "sm" ? "px-2.5 py-1.5 text-xs" : "px-3 py-1.5 text-sm"
            } ${
              active
                ? "bg-primary-soft-bg text-primary"
                : "text-muted hover:bg-surface-sunken hover:text-ink"
            }`}
          >
            {item.icon}
            {item.label}
            {item.count !== undefined && (
              <span className={`tabular text-xs ${active ? "text-primary" : "text-faint"}`}>{item.count}</span>
            )}
          </button>
        );
      })}
    </div>
  );
}

/* --------------------------------------------------------- SegmentedControl */

export interface SegmentOption<T extends string> {
  id: T;
  label: string;
  icon?: ReactNode;
  tone?: "default" | "income" | "expense" | "transfer";
}

export function SegmentedControl<T extends string>({
  options,
  value,
  onChange,
  size = "md",
  ariaLabel,
  className = "",
}: {
  options: SegmentOption<T>[];
  value: T;
  onChange: (id: T) => void;
  size?: "sm" | "md";
  ariaLabel: string;
  className?: string;
}) {
  return (
    <div
      role="radiogroup"
      aria-label={ariaLabel}
      className={`grid gap-1 rounded-xl bg-surface-sunken p-1 ${className}`}
      style={{ gridTemplateColumns: `repeat(${options.length}, minmax(0, 1fr))` }}
    >
      {options.map((option) => {
        const active = option.id === value;
        const toneClass =
          active && option.tone === "income"
            ? "bg-income-soft text-income"
            : active && option.tone === "expense"
              ? "bg-expense-soft text-expense"
              : active && option.tone === "transfer"
                ? "bg-transfer-soft text-transfer"
                : active
                  ? "bg-surface text-ink shadow-card"
                  : "text-muted hover:text-ink";
        return (
          <button
            key={option.id}
            type="button"
            role="radio"
            aria-checked={active}
            onClick={() => onChange(option.id)}
            className={`flex items-center justify-center gap-1.5 rounded-lg font-medium transition-colors ${
              size === "sm" ? "px-2 py-1.5 text-xs" : "px-3 py-2 text-sm"
            } ${toneClass}`}
          >
            {option.icon}
            {option.label}
          </button>
        );
      })}
    </div>
  );
}

/* ------------------------------------------------------------------ Dropdown */

export interface DropdownItem {
  id: string;
  label: string;
  icon?: ReactNode;
  tone?: "default" | "danger";
  onSelect: () => void;
  disabled?: boolean;
}

export function Dropdown({
  trigger,
  items,
  align = "end",
  label,
}: {
  trigger: ReactNode;
  items: DropdownItem[];
  align?: "start" | "end";
  label: string;
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: MouseEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  return (
    <div ref={rootRef} className="relative">
      <button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={label}
        onClick={() => setOpen((prev) => !prev)}
        className="icon-btn"
      >
        {trigger}
      </button>
      {open && (
        <div
          role="menu"
          aria-label={label}
          className={`absolute z-40 mt-1 min-w-44 animate-rise rounded-xl border border-line bg-surface py-1 shadow-overlay ${
            align === "end" ? "right-0" : "left-0"
          }`}
        >
          {items.map((item) => (
            <button
              key={item.id}
              role="menuitem"
              type="button"
              disabled={item.disabled}
              onClick={() => {
                setOpen(false);
                item.onSelect();
              }}
              className={`flex w-full items-center gap-2.5 px-3 py-2 text-left text-sm transition-colors hover:bg-surface-sunken disabled:opacity-50 ${
                item.tone === "danger" ? "text-expense" : "text-ink"
              }`}
            >
              {item.icon}
              {item.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/* --------------------------------------------------------------- Select-like */

export function OptionGrid<T extends string>({
  options,
  value,
  onChange,
  columns = 2,
  renderIcon,
}: {
  options: { id: T; label: string }[];
  value: T | null;
  onChange: (id: T) => void;
  columns?: number;
  renderIcon?: (id: T) => ReactNode;
}) {
  return (
    <div className="grid gap-2" style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}>
      {options.map((option) => {
        const active = option.id === value;
        return (
          <button
            key={option.id}
            type="button"
            aria-pressed={active}
            onClick={() => onChange(option.id)}
            className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-left text-sm transition-colors ${
              active
                ? "border-primary bg-primary-soft-bg font-medium text-primary"
                : "border-line bg-surface text-ink hover:border-line-strong"
            }`}
          >
            {renderIcon?.(option.id)}
            <span className="min-w-0 flex-1 truncate">{option.label}</span>
          </button>
        );
      })}
    </div>
  );
}

export function Collapsible({
  summary,
  children,
  defaultOpen = false,
  className = "",
}: {
  summary: ReactNode;
  children: ReactNode;
  defaultOpen?: boolean;
  className?: string;
}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className={className}>
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((prev) => !prev)}
        className="flex w-full items-center justify-between gap-2 text-sm font-medium text-ink"
      >
        {summary}
        <ChevronDown
          aria-hidden="true"
          className={`h-4 w-4 shrink-0 text-muted transition-transform duration-200 ${open ? "rotate-180" : ""}`}
        />
      </button>
      {open && <div className="animate-rise pt-3">{children}</div>}
    </div>
  );
}

import { createContext, useCallback, useContext, useMemo, useRef, useState, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { CircleAlert, CircleCheck, Info, TriangleAlert, X } from "lucide-react";

export type ToastTone = "info" | "success" | "warning" | "error";

export interface Toast {
  id: string;
  title: string;
  description?: string;
  tone: ToastTone;
  action?: { label: string; onSelect: () => void };
}

interface ToastContextValue {
  push: (toast: Omit<Toast, "id" | "tone"> & { tone?: ToastTone; durationMs?: number }) => void;
  dismiss: (id: string) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

const TONE_ICON: Record<ToastTone, ReactNode> = {
  info: <Info className="h-4 w-4" />,
  success: <CircleCheck className="h-4 w-4" />,
  warning: <TriangleAlert className="h-4 w-4" />,
  error: <CircleAlert className="h-4 w-4" />,
};

const TONE_CLASS: Record<ToastTone, string> = {
  info: "text-info",
  success: "text-income",
  warning: "text-warning",
  error: "text-expense",
};

const DEFAULT_DURATION = 4_000;

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const timers = useRef(new Map<string, number>());

  const dismiss = useCallback((id: string) => {
    setToasts((prev) => prev.filter((toast) => toast.id !== id));
    const timer = timers.current.get(id);
    if (timer) {
      window.clearTimeout(timer);
      timers.current.delete(id);
    }
  }, []);

  const push = useCallback<ToastContextValue["push"]>(
    ({ tone = "info", durationMs = DEFAULT_DURATION, ...rest }) => {
      const id = crypto.randomUUID();
      setToasts((prev) => [...prev.slice(-2), { ...rest, id, tone }]);
      if (durationMs > 0) {
        timers.current.set(id, window.setTimeout(() => dismiss(id), durationMs));
      }
    },
    [dismiss],
  );

  const value = useMemo(() => ({ push, dismiss }), [push, dismiss]);

  return (
    <ToastContext.Provider value={value}>
      {children}
      {createPortal(
        <div
          aria-live="polite"
          aria-atomic="false"
          className="pointer-events-none fixed inset-x-0 bottom-0 z-[60] flex flex-col items-center gap-2 px-3 pb-[calc(5rem+env(safe-area-inset-bottom,0px))] sm:bottom-4 sm:right-4 sm:left-auto sm:items-end sm:px-0 sm:pb-0"
        >
          {toasts.map((toast) => (
            <div
              key={toast.id}
              role="status"
              className="pointer-events-auto flex w-full max-w-sm animate-rise items-start gap-2.5 rounded-xl border border-line bg-surface px-3.5 py-3 shadow-overlay"
            >
              <span aria-hidden="true" className={`mt-0.5 shrink-0 ${TONE_CLASS[toast.tone]}`}>
                {TONE_ICON[toast.tone]}
              </span>
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold text-ink">{toast.title}</p>
                {toast.description && (
                  <p className="mt-0.5 text-xs leading-relaxed text-muted">{toast.description}</p>
                )}
                {toast.action && (
                  <button
                    type="button"
                    onClick={() => {
                      toast.action?.onSelect();
                      dismiss(toast.id);
                    }}
                    className="mt-1.5 text-xs font-semibold text-primary hover:underline"
                  >
                    {toast.action.label}
                  </button>
                )}
              </div>
              <button
                type="button"
                aria-label="Dismiss notification"
                onClick={() => dismiss(toast.id)}
                className="-mr-1 -mt-1 rounded p-1 text-faint transition-colors hover:text-ink"
              >
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
          ))}
        </div>,
        document.body,
      )}
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error("useToast must be used inside ToastProvider");
  return ctx;
}

/**
 * Hand-rolled SVG charts.
 *
 * Purpose-built rather than a charting library: the app only needs a handful of
 * shapes, they must render identically offline, stay accessible, and inherit the
 * design tokens. Every chart has a text alternative (`aria-label`) plus a table.
 */
import { useId, useMemo, type ReactNode } from "react";

export interface SeriesPoint {
  label: string;
  value: number;
  /** Optional secondary series (income on expense charts). */
  secondary?: number;
  meta?: string;
}

const TOKEN = {
  primary: "rgb(var(--color-primary))",
  accent: "rgb(var(--color-accent))",
  income: "rgb(var(--color-income))",
  expense: "rgb(var(--color-expense))",
  transfer: "rgb(var(--color-transfer))",
  warning: "rgb(var(--color-warning))",
  muted: "rgb(var(--color-muted))",
  grid: "rgb(var(--color-line))",
} as const;

export function ChartFrame({
  title,
  subtitle,
  action,
  legend,
  children,
  empty,
  className = "",
  bodyClassName = "",
}: {
  title: ReactNode;
  subtitle?: ReactNode;
  action?: ReactNode;
  legend?: ReactNode;
  children: ReactNode;
  empty?: boolean;
  className?: string;
  bodyClassName?: string;
}) {
  return (
    <section className={`card flex flex-col overflow-hidden ${className}`}>
      <header className="flex items-start justify-between gap-3 px-4 py-3">
        <div className="min-w-0">
          <h3 className="text-sm font-semibold text-ink">{title}</h3>
          {subtitle && <p className="mt-0.5 text-xs text-muted">{subtitle}</p>}
        </div>
        {action}
      </header>
      {legend && <div className="flex flex-wrap items-center gap-3 px-4 pb-2">{legend}</div>}
      <div className={`min-w-0 flex-1 px-2 pb-3 ${bodyClassName}`}>
        {empty ? <div className="flex h-40 items-center justify-center text-sm text-muted">{empty === true ? "No data yet" : empty}</div> : children}
      </div>
    </section>
  );
}

export function ChartLegend({
  items,
}: {
  items: { label: string; color: string; shape?: "line" | "square" }[];
}) {
  return (
    <>
      {items.map((item) => (
        <span key={item.label} className="flex items-center gap-1.5 text-xs text-muted">
          <span
            aria-hidden="true"
            className={item.shape === "line" ? "h-0.5 w-3 rounded-full" : "h-2.5 w-2.5 rounded-sm"}
            style={{ backgroundColor: item.color }}
          />
          {item.label}
        </span>
      ))}
    </>
  );
}

/* ------------------------------------------------------------------- bar chart */

export function BarChart({
  data,
  height = 180,
  currency = "USD",
  format = (value: number) => value.toFixed(0),
  ariaLabel,
  showSecondary = true,
}: {
  data: SeriesPoint[];
  height?: number;
  currency?: string;
  format?: (value: number) => string;
  ariaLabel: string;
  showSecondary?: boolean;
}) {
  const max = useMemo(() => {
    const values = data.flatMap((point) => (showSecondary && point.secondary !== undefined ? [point.value, point.secondary] : [point.value]));
    return Math.max(1, ...values.map((value) => Math.abs(value)));
  }, [data, showSecondary]);

  if (data.length === 0) return null;

  return (
    <figure className="w-full">
      <figcaption className="sr-only">{ariaLabel}</figcaption>
      <div className="flex items-end gap-1.5" style={{ height }} role="img" aria-label={ariaLabel}>
        {data.map((point) => {
          const expenseHeight = (Math.abs(point.value) / max) * (height - 24);
          const incomeHeight =
            point.secondary !== undefined ? (Math.abs(point.secondary) / max) * (height - 24) : 0;
          return (
            <div key={point.label} className="group flex h-full flex-1 flex-col justify-end gap-0.5">
              <div className="flex flex-1 items-end justify-center gap-0.5">
                {point.secondary !== undefined && (
                  <div
                    className="w-2.5 rounded-t-[3px] bg-income/80 transition-opacity group-hover:opacity-100 sm:w-3.5"
                    style={{ height: `${Math.max(2, incomeHeight)}px` }}
                    title={`${point.label} in: ${format(point.secondary)}`}
                  />
                )}
                <div
                  className="w-2.5 rounded-t-[3px] bg-primary/85 transition-opacity group-hover:opacity-100 sm:w-3.5"
                  style={{ height: `${Math.max(2, expenseHeight)}px` }}
                  title={`${point.label} out: ${format(point.value)}`}
                />
              </div>
              <span className="truncate text-center text-[10px] text-muted">{point.label}</span>
            </div>
          );
        })}
      </div>
    </figure>
  );
}

/* ----------------------------------------------------------------- line / area */

export function LineChart({
  data,
  height = 180,
  format = (value: number) => value.toFixed(0),
  ariaLabel,
  tone = "primary",
  fill = true,
  formatLabel,
}: {
  data: SeriesPoint[];
  height?: number;
  format?: (value: number) => string;
  ariaLabel: string;
  tone?: keyof typeof TOKEN;
  fill?: boolean;
  formatLabel?: (point: SeriesPoint) => string;
}) {
  const gradientId = useId();
  const values = data.map((point) => point.value);
  const max = Math.max(1, ...values);
  const min = Math.min(0, ...values);
  const span = max - min || 1;
  const step = data.length > 1 ? 100 / (data.length - 1) : 100;

  const coords = data.map((point, index) => ({
    x: index * step,
    y: 100 - ((point.value - min) / span) * 100,
    point,
  }));

  const line = coords.map(({ x, y }, index) => `${index === 0 ? "M" : "L"}${x},${y}`).join(" ");
  const area = `${line} L100,${100 - ((min === 0 ? 0 : min) - min) / span / 1} L100,100 L0,100 Z`;

  if (data.length === 0) return null;

  return (
    <figure className="w-full">
      <figcaption className="sr-only">{ariaLabel}</figcaption>
      <div role="img" aria-label={ariaLabel} className="relative w-full" style={{ height }}>
        <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-full w-full overflow-visible">
          {fill && (
            <>
              <defs>
                <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor={TOKEN[tone]} stopOpacity="0.22" />
                  <stop offset="100%" stopColor={TOKEN[tone]} stopOpacity="0" />
                </linearGradient>
              </defs>
              <path d={area} fill={`url(#${gradientId})`} />
            </>
          )}
          <path d={line} fill="none" stroke={TOKEN[tone]} strokeWidth="1.6" vectorEffect="non-scaling-stroke" strokeLinejoin="round" strokeLinecap="round" />
          {coords.map(({ x, y, point }) => (
            <circle key={point.label} cx={x} cy={y} r="1.6" fill={TOKEN[tone]}>
              <title>{formatLabel ? formatLabel(point) : `${point.label}: ${format(point.value)}`}</title>
            </circle>
          ))}
        </svg>
      </div>
      <div className="mt-1 flex justify-between text-[10px] text-muted">
        <span>{data[0]?.label}</span>
        <span>{data[data.length - 1]?.label}</span>
      </div>
    </figure>
  );
}

/* ---------------------------------------------------------------------- donut */

export interface Slice {
  label: string;
  value: number;
  color?: string;
}

export function DonutChart({
  slices,
  size = 168,
  thickness = 22,
  centerLabel,
  centerValue,
  ariaLabel,
  colors,
}: {
  slices: Slice[];
  size?: number;
  thickness?: number;
  centerLabel?: string;
  centerValue?: string;
  ariaLabel: string;
  colors?: readonly string[];
}) {
  const palette = colors ?? [
    TOKEN.primary,
    TOKEN.accent,
    TOKEN.transfer,
    TOKEN.warning,
    TOKEN.expense,
    TOKEN.income,
    TOKEN.muted,
  ];
  const total = slices.reduce((sum, slice) => sum + Math.abs(slice.value), 0);
  const radius = (size - thickness) / 2;
  const circumference = 2 * Math.PI * radius;

  let offset = 0;
  const segments = slices
    .filter((slice) => Math.abs(slice.value) > 0)
    .map((slice, index) => {
      const fraction = Math.abs(slice.value) / (total || 1);
      const dash = fraction * circumference;
      const segment = {
        ...slice,
        color: slice.color ?? palette[index % palette.length],
        dash,
        offset,
        percent: fraction * 100,
      };
      offset += dash;
      return segment;
    });

  return (
    <figure className="flex items-center gap-4">
      <figcaption className="sr-only">{ariaLabel}</figcaption>
      <div className="relative shrink-0" style={{ width: size, height: size }} role="img" aria-label={ariaLabel}>
        <svg viewBox={`0 0 ${size} ${size}`} className="-rotate-90">
          <circle cx={size / 2} cy={size / 2} r={radius} fill="none" stroke={TOKEN.grid} strokeWidth={thickness} opacity={0.55} />
          {segments.map((segment) => (
            <circle
              key={segment.label}
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke={segment.color}
              strokeWidth={thickness}
              strokeDasharray={`${segment.dash} ${circumference - segment.dash}`}
              strokeDashoffset={-segment.offset}
              strokeLinecap="butt"
            >
              <title>{`${segment.label}: ${segment.percent.toFixed(1)}%`}</title>
            </circle>
          ))}
        </svg>
        {(centerValue || centerLabel) && (
          <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
            {centerValue && <span className="tabular text-title font-semibold text-ink">{centerValue}</span>}
            {centerLabel && <span className="mt-0.5 text-[11px] text-muted">{centerLabel}</span>}
          </div>
        )}
      </div>
      <ul className="min-w-0 flex-1 space-y-1.5">
        {segments.slice(0, 7).map((segment) => (
          <li key={segment.label} className="flex items-center gap-2 text-xs">
            <span aria-hidden="true" className="h-2.5 w-2.5 shrink-0 rounded-sm" style={{ backgroundColor: segment.color }} />
            <span className="min-w-0 flex-1 truncate text-ink-soft">{segment.label}</span>
            <span className="tabular shrink-0 text-muted">{segment.percent.toFixed(0)}%</span>
          </li>
        ))}
        {segments.length > 7 && <li className="text-xs text-muted">+{segments.length - 7} more</li>}
      </ul>
    </figure>
  );
}

/* --------------------------------------------------------------- horizontal bars */

export function RankedBars({
  items,
  format,
  ariaLabel,
  tone = "primary",
  limit = 6,
}: {
  items: { label: string; value: number; caption?: string }[];
  format: (value: number) => string;
  ariaLabel: string;
  tone?: keyof typeof TOKEN;
  limit?: number;
}) {
  const rows = items.slice(0, limit);
  const max = Math.max(1, ...rows.map((row) => Math.abs(row.value)));
  if (rows.length === 0) return null;

  return (
    <figure className="w-full">
      <figcaption className="sr-only">{ariaLabel}</figcaption>
      <ul className="space-y-2.5">
        {rows.map((row) => (
          <li key={row.label}>
            <div className="mb-1 flex items-baseline justify-between gap-2 text-xs">
              <span className="min-w-0 truncate font-medium text-ink">{row.label}</span>
              <span className="tabular shrink-0 text-muted">
                {format(row.value)}
                {row.caption && <span className="ml-1 text-faint">{row.caption}</span>}
              </span>
            </div>
            <div className="h-1.5 w-full overflow-hidden rounded-full bg-surface-sunken">
              <div
                className="h-full rounded-full transition-[width] duration-500 ease-smooth"
                style={{ width: `${(Math.abs(row.value) / max) * 100}%`, backgroundColor: TOKEN[tone] }}
              />
            </div>
          </li>
        ))}
      </ul>
    </figure>
  );
}

/** Tiny inline trend line for stat cards. */
export function Sparkline({ values, className = "", tone = "primary" }: { values: number[]; className?: string; tone?: keyof typeof TOKEN }) {
  if (values.length < 2) return null;
  const max = Math.max(...values);
  const min = Math.min(...values);
  const span = max - min || 1;
  const points = values
    .map((value, index) => `${(index / (values.length - 1)) * 100},${22 - ((value - min) / span) * 22}`)
    .join(" ");

  return (
    <svg viewBox="0 0 100 22" preserveAspectRatio="none" aria-hidden="true" className={`h-6 w-20 ${className}`}>
      <polyline points={points} fill="none" stroke={TOKEN[tone]} strokeWidth="1.5" vectorEffect="non-scaling-stroke" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}

