10: /** Queue a local change for the server. Coalesces with an unsent entry per row. */
11: export async function enqueueMutation(
12:   entity: EntityName,
13:   entityId: string,
14:   op: OutboxEntry["op"],
15:   row: object | null,
16:   baseVersion: number,
17: ): Promise<void> {
18:   const pending = await db.outbox
19:     .where("entity_id")
20:     .equals(entityId)
21:     .filter((entry) => entry.status !== "conflict" && entry.op !== "delete")
22:     .first();
23: 
24:   if (pending) {
25:     // Same row already queued: keep the original create/insert and merge the new values.
26:     const mergedOp = pending.op === "create" ? "create" : op;
27:     await db.outbox.update(pending.id, {
28:       op: mergedOp,
29:       payload: row ? { ...pending.payload, ...toServerPayload(entity, row as Json) } : {},
30:       status: "pending",
31:       last_error: null,
32:     });
33:     return;
34:   }
35: 
36:   await db.outbox.add({
37:     id: crypto.randomUUID(),
38:     entity,
39:     entity_id: entityId,
40:     op,
41:     base_version: baseVersion,
42:     payload: row ? toServerPayload(entity, row as Json) : {},
43:     status: "pending",
44:     attempts: 0,
45:     last_error: null,
46:     server_version: null,
47:     created_at: new Date().toISOString(),
48:   });
49: }
50: 
51: export async function pendingMutations(limit = 50): Promise<OutboxEntry[]> {
52:   const entries = await db.outbox
53:     .filter(
54:       (entry) =>
55:         entry.status === "pending" ||
56:         (entry.status === "failed" && entry.attempts < MAX_ATTEMPTS),
57:     )
58:     .sortBy("created_at");
59:   return entries.slice(0, limit);
60: }
61: 
62: export async function outboxCount(): Promise<number> {
63:   return db.outbox.count();
64: }
65: 
66: export async function conflictEntries(): Promise<OutboxEntry[]> {
67:   return db.outbox.filter((entry) => entry.status === "conflict").sortBy("created_at");
68: }
69: 
70: export async function getMeta(key: string): Promise<string | null> {
71:   const row = await db.meta.get(key);
72:   return row?.value ?? null;
73: }
74: 
75: export async function setMeta(key: string, value: string): Promise<void> {
76:   await db.meta.put({ key, value });
77: }
78: 
79: /** Stable per-browser identifier so the server can track a pull checkpoint. */
80: export async function getClientId(): Promise<string> {
81:   const existing = await getMeta("client_id");
82:   if (existing) return existing;
83:   const clientId = `web-${crypto.randomUUID()}`;
84:   await setMeta("client_id", clientId);
85:   return clientId;
86: }
87: 
88: /** Per-account checkpoint: switching users must not reuse the previous cursor. */
89: export async function getCheckpoint(accountKey: string): Promise<number> {
90:   return Number((await getMeta(`last_seq:${accountKey}`)) ?? 0);
91: }
92: 
93: export async function setCheckpoint(accountKey: string, seq: number): Promise<void> {
94:   await setMeta(`last_seq:${accountKey}`, String(seq));
95: }

