    end.setHours(0, 0, 0, 0);
    return { start, end: addDays(end, 1) };
  }

  if (kind === "day") {
    const start = new Date(anchor.getFullYear(), anchor.getMonth(), anchor.getDate());
    return { start, end: addDays(start, 1) };
  }

  if (kind === "week") {
    // Weeks start on Monday.
    const start = new Date(anchor.getFullYear(), anchor.getMonth(), anchor.getDate());
    const offset = (start.getDay() + 6) % 7;
    const monday = addDays(start, -offset);
    return { start: monday, end: addDays(monday, 7) };
  }

  if (kind === "month") {
    const start = startOfMonth(anchor, monthStartDay);
    return { start, end: nextMonthStart(start) };
  }

  if (kind === "quarter") {
    const start = startOfMonth(anchor, monthStartDay);
    const offset = (start.getMonth() - startOfMonth(new Date(), monthStartDay).getMonth() + 12) % 3;
    const quarterStart = addMonths(start, -offset);
    return { start: quarterStart, end: addMonths(quarterStart, 3) };
  }

  if (kind === "year") {
    const start = startOfMonth(anchor, monthStartDay);
    return { start, end: addMonths(start, 12) };
  }

  if (kind === "mtd") {
    return { start: startOfMonth(anchor, monthStartDay), end: addDays(endOfMonth(anchor, monthStartDay), 1) };
  }

  // ytd - the financial year starts on the configured month-start day.
  const current = startOfMonth(anchor, monthStartDay);
  const previousYearStart = startOfMonth(addMonths(current, -12), monthStartDay);
  const year = current >= previousYearStart ? previousYearStart : addMonths(previousYearStart, -12);
  return { start: year, end: nextMonthStart(addMonths(year, 12)) };
}

