import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { apiFetch, clearTokens, getAccessToken, storeTokens } from "../api/client";

export interface UserProfile {
  id: string;
  email: string;
  full_name: string;
  preferred_currency: string;
  is_verified: boolean;
  mfa_enabled: boolean;
  date_joined: string;
  last_login?: string | null;
}

export interface AuthState {
  email: string | null;
  isAuthenticated: boolean;
  /** True once the access token exists but may be stale; verified by `/auth/profile/`. */
  profile: UserProfile | null;
  /**
   * Sign in. When the account has two-factor enabled the server answers
   * `mfa_required`; the caller must retry with `otp`.
   */
  login: (email: string, password: string, otp?: string) => Promise<{ mfaRequired: boolean }>;
  logout: () => Promise<void>;
  register: (input: RegisterInput) => Promise<void>;
  requestPasswordReset: (email: string) => Promise<void>;
  resetPassword: (input: ResetInput) => Promise<void>;
  verifyEmail: (uid: string, token: string) => Promise<void>;
  refreshProfile: () => Promise<UserProfile | null>;
  setProfile: (profile: UserProfile) => void;
}

export interface RegisterInput {
  email: string;
  password: string;
  password_confirm: string;
  full_name: string;
  preferred_currency: string;
}

export interface ResetInput {
  uid: string;
  token: string;
  new_password: string;
  new_password_confirm: string;
}

const AuthContext = createContext<AuthState | null>(null);

const EMAIL_KEY = "fintrack_email";

export function AuthProvider({ children }: { children: ReactNode }) {
  const [email, setEmail] = useState<string | null>(() => localStorage.getItem(EMAIL_KEY));
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => Boolean(getAccessToken()));

  const refreshProfile = useCallback(async (): Promise<UserProfile | null> => {
    if (!getAccessToken()) return null;
    try {
      const data = await apiFetch<UserProfile>("/auth/profile/");
      setProfile(data);
      return data;
    } catch {
      // An expired or revoked session must not block the shell: local data stays
      // readable and the sync indicator explains the rest.
      return null;
    }
  }, []);

  const login = useCallback(
    async (nextEmail: string, password: string, otp?: string): Promise<{ mfaRequired: boolean }> => {
      try {
        const data = await apiFetch<{ access: string; refresh: string }>("/auth/login/", {
          method: "POST",
          body: JSON.stringify(
            otp ? { email: nextEmail, password, otp } : { email: nextEmail, password },
          ),
        });
        storeTokens(data.access, data.refresh);
        localStorage.setItem(EMAIL_KEY, nextEmail);
        setEmail(nextEmail);
        setIsAuthenticated(true);
        void refreshProfile();
        return { mfaRequired: false };
      } catch (error) {
        if (error instanceof Error && error.message === "mfa_required") {
          return { mfaRequired: true };
        }
        throw error;
      }
    },
    [refreshProfile],
  );

  const logout = useCallback(async () => {
    const refresh = localStorage.getItem("fintrack_refresh");
    if (refresh) {
      try {
        await apiFetch("/auth/logout/", {
          method: "POST",
          body: JSON.stringify({ refresh }),
        });
      } catch {
        // Logging out locally matters more than the server round-trip.
      }
    }
    clearTokens();
    localStorage.removeItem(EMAIL_KEY);
    setEmail(null);
    setProfile(null);
    setIsAuthenticated(false);
  }, []);

  const register = useCallback(async (input: RegisterInput) => {
    await apiFetch("/auth/register/", { method: "POST", body: JSON.stringify(input) });
  }, []);

  const requestPasswordReset = useCallback(async (target: string) => {
    await apiFetch("/auth/password-reset/", {
      method: "POST",
      body: JSON.stringify({ email: target }),
    });
  }, []);

  const resetPassword = useCallback(async (input: ResetInput) => {
    await apiFetch("/auth/password-reset/confirm/", {
      method: "POST",
      body: JSON.stringify(input),
    });
  }, []);

  const verifyEmail = useCallback(async (uid: string, token: string) => {
    await apiFetch("/auth/verify-email/", {
      method: "POST",
      body: JSON.stringify({ uid, token }),
    });
  }, []);

  useEffect(() => {
    if (isAuthenticated) void refreshProfile();
  }, [isAuthenticated, refreshProfile]);

  const value = useMemo(
    () => ({
      email,
      isAuthenticated,
      profile,
      login,
      logout,
      register,
      requestPasswordReset,
      resetPassword,
      verifyEmail,
      refreshProfile,
      setProfile,
    }),
    [
      email,
      isAuthenticated,
      profile,
      login,
      logout,
      register,
      requestPasswordReset,
      resetPassword,
      verifyEmail,
      refreshProfile,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthState {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside AuthProvider");
  return ctx;
}

import type { ReactNode } from "react";
import { Link, useLocation } from "react-router-dom";
import { Wallet } from "lucide-react";

/**
 * Auth layout.
 *
 * Sign-in is a focused single task, so the marketing split-screen is only shown
 * from `lg` up; below that the form owns the viewport.
 */
export function AuthLayout({
  title,
  subtitle,
  children,
  footer,
}: {
  title: string;
  subtitle?: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
}) {
  return (
    <div className="grid min-h-dvh lg:grid-cols-[1fr_minmax(0,26rem)] xl:grid-cols-[1fr_minmax(0,30rem)]">
      <aside className="relative hidden overflow-hidden bg-primary p-10 text-primary-contrast lg:flex lg:flex-col">
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 opacity-25"
          style={{
            backgroundImage:
              "radial-gradient(circle at 18% 12%, rgba(255,255,255,0.35), transparent 42%), radial-gradient(circle at 82% 88%, rgba(255,255,255,0.25), transparent 46%)",
          }}
