/** Password strength hints, kept simple and actionable. */
function strengthOf(password: string): { score: 0 | 1 | 2 | 3 | 4; label: string } {
  let score = 0;
  if (password.length >= 8) score += 1;
  if (password.length >= 12) score += 1;
  if (/[A-Z]/.test(password) && /[a-z]/.test(password)) score += 1;
  if (/\d/.test(password) && /[^\w\s]/.test(password)) score += 1;
  const labels = ["Too short", "Weak", "Fair", "Good", "Strong"];
  return { score: Math.min(4, score) as 0 | 1 | 2 | 3 | 4, label: labels[Math.min(4, score)] };
}

export function LoginPage() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [needsOtp, setNeedsOtp] = useState(false);
  const [reveal, setReveal] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function submit(event: FormEvent) {
    event.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const result = await login(email.trim(), password, needsOtp ? otp.trim() : undefined);
      if (result.mfaRequired) {
        setNeedsOtp(true);
        setError("Enter the 6-digit code from your authenticator app.");
        return;
      }
      navigate("/", { replace: true });
    } catch (err) {
      setError(
        err instanceof ApiError
          ? err.message || "Those details didn't match. Check your email and password."
          : "Couldn't reach the server. Check your connection and try again.",
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <AuthLayout
      title="Welcome back"
      subtitle="Sign in to sync your accounts, budgets and goals."
      footer={
        <>
          New to FinTrack?{" "}
          <Link to="/register" className="font-medium text-primary hover:underline">
            Create an account
          </Link>
        </>
      }
    >
      <form onSubmit={submit} className="space-y-4" noValidate>
        {error && <FormError message={error} />}

        {!needsOtp ? (
          <>
            <Input
              label="Email"
              type="email"
              name="email"
              autoComplete="email"
              inputMode="email"
              required
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              leadingIcon={<Mail aria-hidden="true" className="h-4 w-4" />}
              placeholder="you@example.com"
            />
            <div className="relative">
              <Input
                label="Password"
                type={reveal ? "text" : "password"}
                name="password"
                autoComplete="current-password"
                required
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                leadingIcon={<KeyRound aria-hidden="true" className="h-4 w-4" />}
                className="pr-11"
              />
              <IconButton
                label={reveal ? "Hide password" : "Show password"}
                onClick={() => setReveal((prev) => !prev)}
                className="absolute top-6 right-0.5"
              >
                {reveal ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </IconButton>
            </div>
            <div className="-mt-1 text-right">
              <Link to="/forgot-password" className="text-xs font-medium text-primary hover:underline">
                Forgot password?
              </Link>
            </div>
          </>
        ) : (
          <>
            <Input
              label="Two-factor code"
              inputMode="numeric"
              autoComplete="one-time-code"
              maxLength={6}
              required
              value={otp}
              onChange={(event) => setOtp(event.target.value.replace(/\D/g, ""))}
              leadingIcon={<ShieldCheck aria-hidden="true" className="h-4 w-4" />}
              placeholder="123456"
              fieldClassName="[&_input]:tracking-[0.4em]"
            />
            <button
              type="button"
              onClick={() => {
                setNeedsOtp(false);
                setOtp("");
                setError(null);
              }}
              className="text-xs font-medium text-muted hover:text-ink"
            >
              Use a different account
            </button>
          </>
        )}

        <Button type="submit" variant="primary" size="lg" block loading={busy} trailingIcon={<ArrowRight className="h-4 w-4" />}>
          {needsOtp ? "Verify and sign in" : "Sign in"}
        </Button>
      </form>
    </AuthLayout>
  );
}

