  { id: "case", label: "Upper and lowercase letters", test: (value: string) => /[a-z]/.test(value) && /[A-Z]/.test(value) },
  { id: "digit", label: "A number", test: (value: string) => /\d/.test(value) },
];

export function RegisterPage() {
