121:     if (accountIds && !accountIds.some((id) => tx.from_account_id === id || tx.to_account_id === id)) {
122:       continue;
123:     }
124:     summary.transactionCount += 1;
125:     const value = convert(Math.abs(tx.amount), tx.currency, fx);
126:     if (tx.type === "income") {
127:       summary.income += value;
128:       summary.cashFlow += value;
129:     } else if (tx.type === "expense") {
130:       summary.expense += value;
131:       summary.cashFlow -= value;
132:     } else {
133:       summary.transferIn += tx.to_account_id ? value : 0;
134:       summary.transferOut += tx.from_account_id ? value : 0;
135:     }
136:   }
137:   summary.net = summary.income - summary.expense;
138:   return summary;
