164:   const childTotals = new Map<string, Map<string, { name: string; icon: string | null; value: number; count: number }>>();
165: 
166:   for (const tx of transactions) {
167:     if (tx.type !== type || !inRange(tx.date, range)) continue;
168:     const rootId = tx.category_id ? (lookups.categoryRoot.get(tx.category_id) ?? tx.category_id) : null;
169:     const key = rootId ?? "__uncategorised__";
170:     const bucket = totals.get(key) ?? { value: 0, count: 0 };
171:     bucket.value += convert(Math.abs(tx.amount), tx.currency, lookups.fx);
172:     bucket.count += 1;
173:     totals.set(key, bucket);
174: 
175:     if (rootId && tx.category_id !== rootId) {
176:       const child = tx.category_id ? lookups.category.get(tx.category_id) : undefined;
177:       if (!child) continue;
178:       const map = childTotals.get(rootId) ?? new Map();
179:       const entry = map.get(child.id) ?? { name: child.name, icon: child.icon, value: 0, count: 0 };
180:       entry.value += convert(Math.abs(tx.amount), tx.currency, lookups.fx);
181:       entry.count += 1;
182:       map.set(child.id, entry);
183:       childTotals.set(rootId, map);
184:     }
185:   }
