187:   const sum = [...totals.values()].reduce((acc, item) => acc + item.value, 0) || 1;
188:   const slices: CategorySlice[] = [...totals.entries()]
189:     .map(([id, item]) => {
190:       const category = id === "__uncategorised__" ? undefined : lookups.category.get(id);
191:       return {
