193:         name: category?.name ?? "Uncategorised",
194:         icon: category?.icon ?? null,
195:         color: category?.color ?? null,
196:         value: item.value,
197:         share: (item.value / sum) * 100,
198:         count: item.count,
199:         children: [...(childTotals.get(id)?.entries() ?? [])].map(([childId, entry]) => ({
200:           id: childId,
201:           name: entry.name,
202:           icon: entry.icon,
203:           value: entry.value,
