253: /**
254:  * Net worth over time: replay the ledger from the beginning so the curve is
255:  * correct even for accounts created long after the first transaction.
256:  */
257: export function netWorthSeries(
258:   dataset: Dataset,
259:   lookups: Lookups,
260:   period: Period,
261:   bucketCount = 12,
262: ): { key: string; label: string; assets: number; liabilities: number; net: number }[] {
263:   const buckets = buildBuckets(period, bucketCount);
264:   if (buckets.length === 0) return [];
265:   const points = buckets.map((bucket) => ({
266:     key: bucket.key,
267:     label: bucket.label,
268:     assets: 0,
269:     liabilities: 0,
270:     net: 0,
271:   }));
272: 
273:   const liabilityIds = new Set(dataset.accounts.filter((a) => isLiability(a.type)).map((a) => a.id));
274:   const balances = new Map<string, number>();
275:   for (const account of dataset.accounts) {
276:     balances.set(account.id, convert(account.opening_balance, account.currency, lookups.fx));
277:   }
278: 
279:   const snapshot = (index: number) => {
280:     let assets = 0;
281:     let liabilities = 0;
282:     for (const [id, balance] of balances) {
283:       if (liabilityIds.has(id)) liabilities += balance;
284:       else assets += balance;
285:     }
286:     points[index].assets = assets;
287:     points[index].liabilities = liabilities;
288:     points[index].net = assets + liabilities;
289:   };
290: 
291:   const ordered = [...dataset.transactions].sort((a, b) => a.date.localeCompare(b.date));
292:   let bucketIndex = 0;
293:   snapshot(0);
294:   for (const tx of ordered) {
295:     const when = new Date(tx.date);
296:     while (bucketIndex < buckets.length - 1 && when >= buckets[bucketIndex].end) {
297:       bucketIndex += 1;
298:       snapshot(bucketIndex);
299:     }
300:     if (when < buckets[0].start) continue;
301:     const { from, to } = signedImpact(tx, lookups.fx);
302:     if (tx.from_account_id && from) balances.set(tx.from_account_id, (balances.get(tx.from_account_id) ?? 0) + from);
303:     if (tx.to_account_id && to) balances.set(tx.to_account_id, (balances.get(tx.to_account_id) ?? 0) + to);
304:   }
305:   snapshot(buckets.length - 1);
306:   return points;
307: }
