333:   const activity = new Map<string, { income: number; expense: number; count: number }>();
334:   const bump = (id: string | null, field: "income" | "expense", value: number) => {
335:     if (!id) return;
336:     const bucket = activity.get(id) ?? { income: 0, expense: 0, count: 0 };
337:     bucket[field] += value;
338:     bucket.count += 1;
339:     activity.set(id, bucket);
340:   };
341: 
342:   for (const tx of dataset.transactions) {
343:     if (!inRange(tx.date, range)) continue;
344:     const value = convert(Math.abs(tx.amount), tx.currency, lookups.fx);
345:     // Income lands in `to_account`, expense leaves `from_account`; transfers move
346:     // value between the two and are counted on both sides of the history.
347:     if (tx.type === "income") bump(tx.to_account_id, "income", value);
348:     else if (tx.type === "expense") bump(tx.from_account_id, "expense", value);
349:     else {
350:       bump(tx.from_account_id, "expense", value);
351:       bump(tx.to_account_id, "income", value);
352:     }
353:   }
354: 
355:   return dataset.accounts.map((account) => {
356:     const bucket = activity.get(account.id) ?? { income: 0, expense: 0, count: 0 };
357:     const balance = convert(account.current_balance, account.currency, lookups.fx);
358:     const limit = account.credit_limit ? convert(account.credit_limit, account.currency, lookups.fx) : null;
359:     // Credit balances are stored negative, so the used amount is the absolute value.
360:     const used = limit !== null && isLiability(account.type) ? Math.abs(Math.min(0, balance)) : null;
361:     return {
362:       account,
363:       balance,
364:       income: bucket.income,
365:       expense: bucket.expense,
366:       net: bucket.income - bucket.expense,
367:       creditUsed: used,
368:       creditLimit: limit,
369:       utilization: limit && used !== null ? (used / limit) * 100 : null,
370:       transactionCount: bucket.count,
371:     };
372:   });
