386:   let liabilities = 0;
387:   let cashAvailable = 0;
388:   let creditTotal = 0;
389:   let creditUsed = 0;
390:   let hasCredit = false;
391: 
392:   for (const account of lookups.dataset.accounts) {
393:     if (!options.includeArchived && account.archived) continue;
394:     const balance = convert(account.current_balance, account.currency, lookups.fx);
395:     if (isLiability(account.type)) {
396:       liabilities += balance;
397:       if (account.credit_limit) {
398:         hasCredit = true;
399:         creditTotal += convert(account.credit_limit, account.currency, lookups.fx);
400:         creditUsed += Math.abs(Math.min(0, balance));
401:       }
402:     } else {
403:       assets += balance;
404:       cashAvailable += balance;
405:     }
406:   }
407: 
408:   return {
409:     assets,
410:     liabilities,
411:     netWorth: assets + liabilities,
412:     cashAvailable,
413:     creditAvailable: hasCredit ? Math.max(0, creditTotal - creditUsed) : null,
414:   };
415: }
