431: /** Budget spend is scoped to the budget's own period, not the report period. */
432: export function budgetProgress(
433:   budgets: LocalBudget[],
434:   transactions: LocalTransaction[],
435:   lookups: Lookups,
436:   anchor: Date,
437:   monthStartDay: number,
438: ): BudgetProgress[] {
439:   return budgets.map((budget) => {
440:     const range = budgetRange(budget, anchor, monthStartDay);
441:     let spent = 0;
442:     for (const tx of transactions) {
443:       if (tx.type !== "expense" || !inRange(tx.date, range)) continue;
444:       if (budget.category_id) {
445:         const root = tx.category_id
446:           ? (lookups.categoryRoot.get(tx.category_id) ?? tx.category_id)
447:           : null;
448:         if (root !== budget.category_id && tx.category_id !== budget.category_id) continue;
449:       }
450:       spent += convert(Math.abs(tx.amount), tx.currency, lookups.fx);
451:     }
452:     const limit = convert(budget.amount, lookups.dataset.baseCurrency, lookups.fx) || budget.amount;
453:     const percent = limit > 0 ? (spent / limit) * 100 : 0;
454:     return {
455:       budget,
456:       spent,
457:       remaining: limit - spent,
458:       percent,
459:       alert: percent >= budget.alert_threshold,
460:       overBudget: percent > 100,
461:       categoryName: budget.category_id
462:         ? (lookups.category.get(budget.category_id)?.name ?? null)
463:         : null,
464:       period: range,
465:     };
466:   });
467: }
