469: function budgetRange(budget: LocalBudget, anchor: Date, monthStartDay: number): DateRange | null {
470:   const start = new Date(budget.start_date);
471:   if (Number.isNaN(start.getTime())) return null;
472:   const from = new Date(start.getFullYear(), start.getMonth(), start.getDate());
473:   switch (budget.period) {
474:     case "weekly":
475:       return { start: from, end: addDays(from, 7) };
476:     case "yearly":
477:       return { start: from, end: addDays(from, 365) };
478:     default: {
479:       const period: Period = { kind: "month", anchor, monthStartDay };
480:       const range = periodRange(period);
481:       return range;
482:     }
483:   }
484: }
