501: export function goalProgress(
502:   goals: LocalSavingsGoal[],
503:   transactions: LocalTransaction[],
504:   lookups: Lookups,
505: ): GoalProgress[] {
506:   return goals.map((goal) => {
507:     const contributions = transactions
508:       .filter((tx) => !tx.deleted_at && tx.savings_goal_id === goal.id)
509:       .sort((a, b) => b.date.localeCompare(a.date));
510:     const saved = contributions.reduce((acc, tx) => {
511:       const value = convert(Math.abs(tx.amount), tx.currency, lookups.fx);
512:       // Transfers *into* the goal fund it; anything else is a withdrawal.
513:       const sign = tx.type === "income" || (tx.type === "transfer" && tx.to_account_id) ? value : -value;
514:       return acc + sign;
515:     }, 0);
516:     const target = convert(goal.target_amount, goal.currency, lookups.fx);
517:     const percent = target > 0 ? (saved / target) * 100 : 0;
518:     const daysLeft = goal.target_date
519:       ? Math.round((new Date(goal.target_date).getTime() - Date.now()) / 86_400_000)
520:       : null;
521:     const monthsLeft = daysLeft === null ? null : Math.max(1, Math.ceil(daysLeft / 30.44));
522:     return {
523:       goal,
524:       saved: Math.max(0, saved),
525:       percent,
526:       remaining: Math.max(0, target - saved),
527:       target,
528:       contributions,
529:       onTrack: percent >= 100,
530:       daysLeft,
531:       requiredMonthly: monthsLeft === null ? null : Math.max(0, (target - saved)) / monthsLeft,
532:     };
533:   });
