575: export interface InstallmentProgress {
576:   plan: LocalInstallment;
577:   partAmount: number;
578:   paidParts: number;
579:   remainingParts: number;
580:   paidAmount: number;
581:   percent: number;
582:   nextDueDate: Date | null;
583:   schedule: { index: number; date: Date; amount: number; paid: boolean }[];
