585: 
586: export function installmentProgress(
587:   plans: LocalInstallment[],
588:   transactions: LocalTransaction[],
589:   lookups: Lookups,
590: ): InstallmentProgress[] {
591:   return plans.map((plan) => {
592:     // Remainder cents land on the final part, exactly like the server generator.
593:     const partAmount = Math.floor((plan.total_amount / plan.parts_count) * 100) / 100;
594:     const linked = transactions
595:       .filter((tx) => !tx.deleted_at && tx.installment_id === plan.id)
596:       .sort((a, b) => a.date.localeCompare(b.date));
597:     const schedule = Array.from({ length: plan.parts_count }, (_, index) => {
598:       const amount =
599:         index === plan.parts_count - 1
600:           ? Number((plan.total_amount - partAmount * (plan.parts_count - 1)).toFixed(2))
601:           : partAmount;
602:       return { index, date: installmentDueDate(new Date(plan.start_date), plan.frequency, index), amount, paid: false };
603:     });
604:     let paidAmount = 0;
605:     let paidParts = 0;
606:     for (const payment of linked) {
607:       paidAmount += convert(Math.abs(payment.amount), payment.currency, lookups.fx);
608:       paidParts += 1;
609:       const dueIndex = Math.min(schedule.length - 1, Math.floor(paidParts - 1));
610:       if (schedule[dueIndex]) schedule[dueIndex].paid = true;
611:     }
612:     const nextDue = schedule.find((item) => !item.paid)?.date ?? null;
613:     return {
614:       plan,
615:       partAmount,
616:       paidParts: Math.min(paidParts, plan.parts_count),
617:       remainingParts: Math.max(0, plan.parts_count - paidParts),
618:       paidAmount,
619:       percent: plan.total_amount > 0 ? (paidAmount / plan.total_amount) * 100 : 0,
620:       nextDueDate: nextDue,
621:       schedule,
622:     };
623:   });
624: }
