639: /** Everything due or recorded on a day, for the calendar grid and day sheet. */
640: export function calendarEvents(
641:   lookups: Lookups,
642:   start: Date,
643:   end: Date,
644:   options: { horizonDays?: number } = {},
645: ): Map<string, CalendarEvent[]> {
646:   const events = new Map<string, CalendarEvent[]>();
647:   const push = (event: CalendarEvent) => {
648:     const list = events.get(event.date) ?? [];
649:     list.push(event);
650:     events.set(event.date, list);
651:   };
652: 
653:   for (const tx of lookups.dataset.transactions) {
654:     if (!inRange(tx.date, { start, end })) continue;
655:     const account = tx.from_account_id ? lookups.account.get(tx.from_account_id)?.name : undefined;
656:     const category = tx.category_id ? lookups.category.get(tx.category_id)?.name : undefined;
657:     const label =
658:       tx.type === "transfer"
659:         ? `Transfer ${account ?? "?"}`
660:         : [category, account].filter(Boolean).join(" · ") || tx.type;
661:     push({
662:       key: `tx:${tx.id}`,
663:       date: toDateKey(tx.date),
664:       kind: "transaction",
665:       title: tx.notes || label,
666:       amount: convert(Math.abs(tx.amount), tx.currency, lookups.fx),
667:       currency: lookups.dataset.baseCurrency,
668:       tone: tx.type === "income" ? "income" : tx.type === "expense" ? "expense" : "transfer",
669:       transactionId: tx.id,
670:     });
671:   }
672: 
673:   const horizon = options.horizonDays ?? 0;
674:   const upcomingEnd = addDays(end, horizon);
675:   for (const rule of lookups.dataset.recurring) {
676:     if (!rule.enabled) continue;
677:     let when = toDate(rule.next_run_at);
678:     // Walk occurrences forward until past the window. The guard bounds the loop if
679:     // a daily rule is scanned across a long range.
680:     let guard = 0;
681:     while (when < start && guard < 400) {
682:       when = advanceOccurrence(when, rule.frequency);
683:       guard += 1;
684:     }
685:     while (when < upcomingEnd && guard < 400) {
686:       const category = rule.category_id ? lookups.category.get(rule.category_id)?.name : null;
687:       push({
688:         key: `rec:${rule.id}:${toDateKey(when)}`,
689:         date: toDateKey(when),
690:         kind: "recurring",
691:         title: category ?? `${rule.type} · recurring`,
692:         amount: convert(Math.abs(rule.amount), rule.currency, lookups.fx),
693:         currency: lookups.dataset.baseCurrency,
694:         tone: rule.type === "income" ? "income" : rule.type === "expense" ? "expense" : "transfer",
695:       });
696:       when = advanceOccurrence(when, rule.frequency);
697:       guard += 1;
698:     }
699:   }
700: 
701:   for (const progress of installmentProgress(lookups.dataset.installments, lookups.dataset.transactions, lookups)) {
702:     for (const item of progress.schedule) {
703:       if (item.paid || item.date < start || item.date >= upcomingEnd) continue;
704:       push({
705:         key: `ins:${progress.plan.id}:${item.index}`,
706:         date: toDateKey(item.date),
707:         kind: "installment",
708:         title: `Installment ${item.index + 1} of ${progress.plan.parts_count}`,
709:         amount: item.amount,
710:         currency: progress.plan.currency,
711:         tone: "expense",
712:       });
713:     }
714:   }
715: 
716:   for (const debt of lookups.dataset.debts) {
717:     if (!debt.due_date) continue;
718:     const when = toDate(debt.due_date);
719:     if (when < start || when >= upcomingEnd) continue;
720:     push({
721:       key: `debt:${debt.id}`,
722:       date: toDateKey(when),
723:       kind: "debt",
724:       title: `${debt.direction === "i_owe" ? "Pay" : "Collect"} ${debt.counterparty}`,
725:       amount: convert(debt.remaining_amount, debt.currency, lookups.fx),
726:       currency: lookups.dataset.baseCurrency,
727:       tone: debt.direction === "i_owe" ? "expense" : "income",
728:     });
729:   }
730: 
731:   for (const progress of goalProgress(lookups.dataset.goals, lookups.dataset.transactions, lookups)) {
732:     if (!progress.goal.target_date || progress.percent >= 100) continue;
733:     const when = toDate(progress.goal.target_date);
734:     if (when < start || when >= upcomingEnd) continue;
735:     push({
736:       key: `goal:${progress.goal.id}`,
737:       date: toDateKey(progress.goal.target_date),
738:       kind: "goal",
739:       title: `Goal: ${progress.goal.name}`,
740:       amount: progress.remaining,
741:       currency: progress.goal.currency,
742:       tone: "neutral",
743:     });
744:   }
745: 
746:   for (const list of events.values()) {
747:     list.sort((a, b) => a.kind.localeCompare(b.kind));
748:   }
749:   return events;
750: }
