766: /** Bills, recurring payments, installments and goal deadlines - the next N days. */
767: export function upcoming(lookups: Lookups, days = 30): UpcomingItem[] {
768:   const today = new Date();
769:   today.setHours(0, 0, 0, 0);
770:   const end = addDays(today, days);
771:   const events = calendarEvents(lookups, today, end);
772:   const items: UpcomingItem[] = [];
773: 
774:   for (const [date, list] of events) {
775:     const inDays = Math.round((new Date(`${date}T00:00:00`).getTime() - today.getTime()) / 86_400_000);
776:     for (const event of list) {
777:       if (event.kind === "transaction") continue;
778:       items.push({
779:         key: event.key,
780:         date: new Date(`${date}T00:00:00`),
781:         inDays,
782:         title: event.title,
783:         subtitle: event.kind,
784:         amount: event.amount,
785:         currency: event.currency,
786:         tone: event.tone,
787:         kind: event.kind,
788:       });
789:     }
790:   }
791:   return items.sort((a, b) => a.date.getTime() - b.date.getTime()).slice(0, 25);
792: }
