810: export function yearInReview(dataset: Dataset, lookups: Lookups, year: number): YearInReview {
811:   const range: DateRange = {
812:     start: new Date(year, 0, 1),
813:     end: new Date(year + 1, 0, 1),
814:   };
815:   const inYear = dataset.transactions.filter((tx) => inRange(tx.date, range));
816:   const summary = summarize(inYear, range, lookups.fx);
817:   const points = series(
818:     inYear,
819:     { kind: "year", anchor: new Date(year, 0, 1), monthStartDay: 1 },
820:     lookups,
821:     12,
822:   );
823:   const expenses = inYear.filter((tx) => tx.type === "expense");
824:   const biggest = expenses.reduce<LocalTransaction | null>(
825:     (worst, tx) => (!worst || tx.amount > worst.amount ? tx : worst),
826:     null,
827:   );
828:   const daysElapsed = year === new Date().getFullYear() ? Math.max(1, Math.ceil((Date.now() - range.start.getTime()) / 86_400_000)) : 365;
829: 
830:   return {
831:     year,
832:     income: summary.income,
833:     expense: summary.expense,
834:     net: summary.net,
835:     topCategories: categoryBreakdown(inYear, range, lookups, "expense", 6),
836:     topIncome: categoryBreakdown(inYear, range, lookups, "income", 6),
837:     bestMonth: points.reduce<SeriesPoint | null>((best, point) => (!best || point.net > best.net ? point : best), null),
838:     biggestExpense: biggest,
839:     transactionCount: summary.transactionCount,
840:     averageDailySpend: summary.expense / daysElapsed,
841:     savingsRate: summary.income > 0 ? (summary.net / summary.income) * 100 : 0,
842:   };
843: }

