520: /**
521:  * Keeps `Debt.remaining_amount` in step with the ledger. Payment history is the
522:  * transactions carrying `debt_id`, so the two can never disagree.
523:  */
524: async function applyDebtPayment(tx: LocalTransaction): Promise<void> {
525:   const debt = await db.debts.get(tx.debt_id ?? "");
526:   if (!debt) return;
527:   const remaining = Math.max(0, debt.remaining_amount - Math.abs(tx.amount));
528:   if (remaining !== debt.remaining_amount) {
529:     await db.debts.update(debt.id, { remaining_amount: remaining, updated_at: now() });
530:   }
531: }
