36: export async function refreshAccessToken(): Promise<boolean> {
37:   const refresh = getRefreshToken();
38:   if (!refresh) return false;
39:   try {
40:     const res = await fetch(`${API_BASE_URL}/auth/refresh/`, {
41:       method: "POST",
42:       headers: { "Content-Type": "application/json" },
43:       body: JSON.stringify({ refresh }),
44:     });
45:     if (!res.ok) return false;
46:     const data = (await res.json()) as { access?: string; refresh?: string };
47:     if (!data.access) return false;
48:     localStorage.setItem(ACCESS_KEY, data.access);
49:     if (data.refresh) localStorage.setItem(REFRESH_KEY, data.refresh);
50:     return true;
51:   } catch {
52:     return false;
53:   }
