56: export async function apiFetch<T>(
57:   path: string,
58:   init: RequestInit = {},
59:   allowRetry = true,
60: ): Promise<T> {
61:   const headers = new Headers(init.headers);
62:   if (init.body && !headers.has("Content-Type")) {
63:     headers.set("Content-Type", "application/json");
64:   }
65:   const token = getAccessToken();
66:   if (token) headers.set("Authorization", `Bearer ${token}`);
67: 
68:   const res = await fetch(`${API_BASE_URL}${path}`, { ...init, headers });
69: 
70:   if (res.status === 401 && allowRetry && (await refreshAccessToken())) {
71:     return apiFetch<T>(path, init, false);
72:   }
73:   if (!res.ok) {
74:     let detail = `Request failed (${res.status})`;
75:     try {
76:       const body = (await res.json()) as Record<string, unknown>;
77:       if (typeof body.detail === "string") detail = body.detail;
78:     } catch {
79:       /* keep the generic message */
80:     }
81:     throw new ApiError(res.status, detail);
82:   }
83:   if (res.status === 204) return undefined as T;
84:   return (await res.json()) as T;
85: }

