47: function score(haystack: string, needle: string): number {
48:   if (!needle) return 0;
49:   const value = haystack.toLowerCase();
50:   if (value === needle) return 100;
51:   if (value.startsWith(needle)) return 60;
52:   if (value.includes(needle)) return 30;
53:   // Fall back to loose word matching, e.g. "mcdon" -> "McDonald's".
54:   return needle.split(/\s+/).some((word) => word.length > 2 && value.includes(word)) ? 15 : -1;
