64: 
65:   if (!filters.entities.includes("transactions")) return [];
66: 
67:   const hits: TransactionHit[] = [];
68:   for (const tx of transactions) {
69:     if (tx.deleted_at) continue;
70:     if (!inRange(tx.date, filters.range)) continue;
71:     if (filters.types.length > 0 && !filters.types.includes(tx.type)) continue;
72:     if (filters.bookmarkedOnly && !tx.is_bookmarked) continue;
73:     if (filters.accountIds.length > 0) {
