75:         (id) => tx.from_account_id === id || tx.to_account_id === id,
76:       );
77:       if (!touched) continue;
78:     }
79:     if (categorySet.size > 0) {
80:       const root = tx.category_id ? (lookups.categoryRoot.get(tx.category_id) ?? tx.category_id) : null;
