1: /**
2:  * Currency conversion from locally cached exchange rates.
3:  *
4:  * Multi-currency reporting must work offline, so conversion never calls the
5:  * network: it uses the newest rate stored for each pair, and treats the base
6:  * currency of the report as 1.0. Rates are symmetric (A/B == 1 / B/A).
7:  */
8: import type { LocalExchangeRate } from "../../db/types";
9: 
10: export interface FxTable {
11:   base: string;
12:   /** Direct rates keyed `A/B` -> units of B per 1 A. */
13:   rates: Map<string, number>;
14:   /** Date of the newest rate that fed the table, for "rates as of" copy. */
15:   asOf: string | null;
16:   missing: Set<string>;
17: }
18: 
19: export function buildFxTable(rows: LocalExchangeRate[], baseCurrency: string): FxTable {
20:   const rates = new Map<string, number>();
21:   const missing = new Set<string>();
22:   let asOf: string | null = null;
23: 
24:   // Newest first, so the first hit for a pair wins.
25:   const ordered = [...rows]
26:     .filter((row) => !row.deleted_at && row.rate > 0)
27:     .sort((a, b) => b.date.localeCompare(a.date));
28: 
29:   for (const row of ordered) {
30:     const key = `${row.base_currency}/${row.quote_currency}`;
31:     if (!rates.has(key)) {
32:       rates.set(key, row.rate);
33:       asOf = row.date > (asOf ?? "") ? row.date : asOf;
34:     }
35:   }
36:   // Derive the inverse pairs the user has not entered explicitly.
37:   for (const [key, rate] of [...rates]) {
38:     const inverse = `${key.split("/")[1]}/${key.split("/")[0]}`;
39:     if (!rates.has(inverse) && rate !== 0) rates.set(inverse, 1 / rate);
40:   }
41: 
42:   const base = baseCurrency.toUpperCase();
43:   if (!rates.has(`${base}/${base}`)) rates.set(`${base}/${base}`, 1);
44: 
45:   return { base, rates, asOf, missing };
46: }
