49: export function rateToBase(table: FxTable, currency: string): number {
50:   const code = currency.toUpperCase();
51:   if (code === table.base) return 1;
52:   const direct = table.rates.get(`${code}/${table.base}`);
53:   if (direct !== undefined && direct > 0) return direct;
54:   table.missing.add(`${code}/${table.base}`);
