/**
 * Transaction list primitives.
 *
 * One row component serves the overview, the ledger, account history and search
 * results, so a transaction always *looks* like a transaction (§16). Rows are
 * list items, not cards: dense enough to scan on desktop, still tappable on
 * mobile.
 */
import { Fragment, useMemo } from "react";
import { Link } from "react-router-dom";
import { Bookmark, Cloud, CloudOff, Paperclip } from "lucide-react";
import type { LocalAccount, LocalTransaction } from "../../db/types";
import {
  formatMoney,
  formatRelativeDay,
  isToday,
  toDateKey,
} from "../../design/format";
import { categoryIcon } from "../../design/icons";
import type { Lookups } from "../analytics/engine";
import { convert } from "../analytics/fx";

export interface TransactionRowProps {
  transaction: LocalTransaction;
  lookups: Lookups;
  /** Show the account name under the description. */
  showAccount?: boolean;
  /** Show the category name next to the title. */
  showCategory?: boolean;
  /** Render a leading bookmark flag. */
  onToggleBookmark?: () => void;
  /** Attachment count badge. */
  attachments?: number;
  className?: string;
}

/** Human label for a row: the note wins, then the category, then the type. */
export function transactionTitle(tx: LocalTransaction, lookups: Lookups): string {
  if (tx.notes.trim()) return tx.notes.trim();
  if (tx.type === "transfer") {
    const from = tx.from_account_id ? lookups.account.get(tx.from_account_id)?.name : null;
    const to = tx.to_account_id ? lookups.account.get(tx.to_account_id)?.name : null;
    return `Transfer ${from ?? "?"} → ${to ?? "?"}`;
  }
  const category = tx.category_id ? lookups.category.get(tx.category_id)?.name : null;
  return category ?? (tx.type === "income" ? "Income" : "Expense");
}

export function transactionAccounts(tx: LocalTransaction, lookups: Lookups): string {
  const name = (id: string | null) => (id ? lookups.account.get(id)?.name ?? "Unknown" : null);
  if (tx.type === "transfer") {
    const from = name(tx.from_account_id);
    const to = name(tx.to_account_id);
    if (from && to) return `${from} → ${to}`;
    return from ?? to ?? "Transfer";
  }
  return name(tx.type === "income" ? tx.to_account_id : tx.from_account_id) ?? "";
}

export function TransactionRow({
  transaction: tx,
  lookups,
  showAccount = true,
  showCategory = false,
  onToggleBookmark,
  attachments = 0,
  className = "",
}: TransactionRowProps) {
  const category = tx.category_id ? lookups.category.get(tx.category_id) : undefined;
  const Icon = categoryIcon(category?.icon ?? null, category?.name);
  const accountLine = showAccount ? transactionAccounts(tx, lookups) : "";
  const amount = convert(Math.abs(tx.amount), tx.currency, lookups.fx);
  const foreign = tx.currency !== lookups.dataset.baseCurrency;

  const tone =
    tx.type === "income" ? "text-income" : tx.type === "expense" ? "text-expense" : "text-transfer";
  const signed = tx.type === "income" ? "+" : tx.type === "expense" ? "−" : "";

  return (
    <div className={`flex items-center gap-3 px-4 py-2.5 ${className}`}>
      <span
        aria-hidden="true"
        className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-surface-sunken text-ink-soft"
      >
        <Icon className="h-4.5 w-[18px]" />
      </span>

      <Link to={`/transactions/${tx.id}`} className="min-w-0 flex-1 rounded-md">
        <span className="flex items-center gap-1.5">
          <span className="truncate text-sm font-medium text-ink">{transactionTitle(tx, lookups)}</span>
          {tx.is_bookmarked && (
            <Bookmark aria-label="Bookmarked" className="h-3.5 w-3.5 shrink-0 fill-warning/20 text-warning" />
          )}
          {tx.sync_status === "pending" && (
            <Cloud
              aria-label="Waiting to sync"
              className="h-3.5 w-3.5 shrink-0 text-faint"
            />
          )}
          {tx.sync_status === "failed" && (
            <CloudOff aria-label="Sync failed" className="h-3.5 w-3.5 shrink-0 text-expense" />
          )}
          {attachments > 0 && (
            <span className="inline-flex shrink-0 items-center gap-0.5 text-faint">
              <Paperclip aria-hidden="true" className="h-3 w-3" />
              <span className="tabular text-[11px]">{attachments}</span>
            </span>
          )}
        </span>
        <span className="mt-0.5 flex items-center gap-1.5 text-xs text-muted">
          <span>{formatRelativeDay(tx.date)}</span>
          {showCategory && category && (
            <>
              <span aria-hidden="true">·</span>
              <span className="truncate">{category.name}</span>
            </>
          )}
          {accountLine && (
            <>
              <span aria-hidden="true">·</span>
              <span className="truncate">{accountLine}</span>
            </>
          )}
        </span>
      </Link>

      <div className="flex shrink-0 items-center gap-1.5">
        {onToggleBookmark && (
          <button
            type="button"
            aria-label={tx.is_bookmarked ? "Remove bookmark" : "Bookmark this transaction"}
            aria-pressed={tx.is_bookmarked}
            onClick={onToggleBookmark}
            className={`icon-btn h-8 w-8 ${tx.is_bookmarked ? "text-warning" : ""}`}
          >
            <Bookmark className={`h-4 w-4 ${tx.is_bookmarked ? "fill-warning/25" : ""}`} />
          </button>
        )}
        <div className="text-right">
          <p className={`tabular text-sm font-semibold ${tone}`}>
            {signed}
            {formatMoney(amount, tx.currency)}
          </p>
          {foreign && (
            <p className="tabular text-[11px] text-faint">
              ≈{formatMoney(amount, lookups.dataset.baseCurrency, { compact: true })}
            </p>
          )}
          {isToday(tx.date) && (
            <span className="sr-only">{formatRelativeDay(tx.date, tx.date)}</span>
          )}
        </div>
      </div>
    </div>
  );
}

/** `Today` / `Yesterday` / date headings between groups of rows. */
export function groupByDay(
  transactions: LocalTransaction[],
): { key: string; label: string; rows: LocalTransaction[] }[] {
  const groups = new Map<string, LocalTransaction[]>();
  for (const tx of transactions) {
    const key = toDateKey(tx.date);
    const list = groups.get(key) ?? [];
    list.push(tx);
    groups.set(key, list);
  }
  return [...groups.entries()].map(([key, rows]) => ({
    key,
    label: formatRelativeDay(key),
    rows,
  }));
}

export interface DayTotal {
  income: number;
  expense: number;
  transfer: number;
}

export function dayTotals(rows: LocalTransaction[], fx: Lookups["fx"]): DayTotal {
  return rows.reduce<DayTotal>(
    (acc, tx) => {
      const value = convert(Math.abs(tx.amount), tx.currency, fx);
      if (tx.type === "income") acc.income += value;
      else if (tx.type === "expense") acc.expense += value;
      else acc.transfer += value;
      return acc;
    },
    { income: 0, expense: 0, transfer: 0 },
  );
}

/** Day-grouped, day-summed ledger. The default presentation for transactions. */
export function TransactionDayList({
  transactions,
  lookups,
  onToggleBookmark,
  showCategory = false,
  className = "",
}: {
  transactions: LocalTransaction[];
  lookups: Lookups;
  onToggleBookmark?: (id: string) => void;
  showCategory?: boolean;
  className?: string;
}) {
  const groups = useMemo(() => groupByDay(transactions), [transactions]);

  return (
    <div className={className}>
      {groups.map((group) => {
        const totals = dayTotals(group.rows, lookups.fx);
        return (
          <Fragment key={group.key}>
            <div className="flex items-baseline justify-between gap-3 border-y border-line bg-surface-sunken px-4 py-1.5">
              <span className="text-xs font-semibold tracking-wide text-ink-soft uppercase">
                {group.label}
              </span>
              <span className="tabular text-xs text-muted">
                {totals.income > 0 && (
                  <span className="text-income">+{formatMoney(totals.income, lookups.dataset.baseCurrency, { compact: true })}</span>
                )}
                {totals.income > 0 && totals.expense > 0 && <span aria-hidden="true"> · </span>}
                {totals.expense > 0 && (
                  <span className="text-expense">−{formatMoney(totals.expense, lookups.dataset.baseCurrency, { compact: true })}</span>
                )}
              </span>
            </div>
            <div className="divide-y divide-line">
              {group.rows.map((tx) => (
                <TransactionRow
                  key={tx.id}
                  transaction={tx}
                  lookups={lookups}
                  showCategory={showCategory}
                  onToggleBookmark={onToggleBookmark ? () => onToggleBookmark(tx.id) : undefined}
                />
              ))}
            </div>
          </Fragment>
        );
      })}
    </div>
  );
}

/** Flat, dense table used on desktop where horizontal space is free. */
export function TransactionTable({
  transactions,
  lookups,
  accounts,
  onToggleBookmark,
}: {
  transactions: LocalTransaction[];
  lookups: Lookups;
  accounts: LocalAccount[];
  onToggleBookmark?: (id: string) => void;
}) {
  const accountNames = new Map(accounts.map((a) => [a.id, a.name]));
  return (
    <div className="scroll-area max-h-[70vh] overflow-x-auto">
      <table className="w-full min-w-[44rem] border-collapse">
        <thead className="sticky top-0 z-10 bg-surface">
          <tr className="border-b border-line">
            <th scope="col" className="th w-24">Date</th>
            <th scope="col" className="th">Description</th>
            <th scope="col" className="th">Category</th>
            <th scope="col" className="th">Account</th>
            <th scope="col" className="th w-16" />
            <th scope="col" className="th w-32 text-right">Amount</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-line">
          {transactions.map((tx) => {
            const category = tx.category_id ? lookups.category.get(tx.category_id) : undefined;
            const tone =
              tx.type === "income"
                ? "text-income"
                : tx.type === "expense"
                  ? "text-expense"
                  : "text-transfer";
            const accountId = tx.type === "income" ? tx.to_account_id : tx.from_account_id;
            return (
              <tr key={tx.id} className="row-link">
                <td className="td whitespace-nowrap text-muted">{formatRelativeDay(tx.date)}</td>
                <td className="td max-w-[18rem]">
                  <Link
                    to={`/transactions/${tx.id}`}
                    className="block truncate font-medium text-ink hover:text-primary"
                  >
                    {transactionTitle(tx, lookups)}
                  </Link>
                </td>
                <td className="td truncate text-muted">{category?.name ?? "—"}</td>
                <td className="td truncate text-muted">
                  {accountId ? (accountNames.get(accountId) ?? "Unknown") : "—"}
                </td>
                <td className="td">
                  <button
                    type="button"
                    aria-label={tx.is_bookmarked ? "Remove bookmark" : "Bookmark this transaction"}
                    onClick={() => onToggleBookmark?.(tx.id)}
                    className={`icon-btn h-8 w-8 ${tx.is_bookmarked ? "text-warning" : ""}`}
                  >
                    <Bookmark className={`h-4 w-4 ${tx.is_bookmarked ? "fill-warning/25" : ""}`} />
                  </button>
                </td>
                <td className={`td tabular text-right font-semibold ${tone}`}>
                  {tx.type === "income" ? "+" : tx.type === "expense" ? "−" : ""}
                  {formatMoney(convert(Math.abs(tx.amount), tx.currency, lookups.fx), lookups.dataset.baseCurrency)}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

/**
 * The transaction editor.
 *
 * One form, two hosts: the quick-add sheet (create) and the transaction detail
 * screen (create + edit). Amount first, then type, account, category, then the
 * optional metadata - the order a person actually records an expense in (§17).
 * Saving always goes through the repositories, so the change is written to
 * IndexedDB and queued for sync even with no connection.
 */
import { useMemo, useState, type FormEvent } from "react";
import {
  ArrowLeftRight,
  Bookmark,
  Paperclip,
  TrendingDown,
  TrendingUp,
} from "lucide-react";
import type { LocalTransaction } from "../../db/types";
import { CURRENCIES, formatDate, todayKey } from "../../design/format";
import { categoryIcon } from "../../design/icons";
import {
  AmountInput,
  Button,
  Collapsible,
  Field,
  IconButton,
  Input,
  SegmentedControl,
  Select,
  Textarea,
  useToast,
} from "../../components/ui";
import { useLocalData } from "../analytics/useLocalData";
import { usePreferences } from "../settings/preferences";
import { createTransaction, createTag, toggleBookmark, updateTransaction } from "../../db/repositories";

export type TransactionType = LocalTransaction["type"];

const TYPE_OPTIONS: { id: TransactionType; label: string; icon: React.ReactNode; tone: "expense" | "income" | "transfer" }[] = [
  { id: "expense", label: "Expense", icon: <TrendingDown className="h-4 w-4" />, tone: "expense" },
  { id: "income", label: "Income", icon: <TrendingUp className="h-4 w-4" />, tone: "income" },
  { id: "transfer", label: "Transfer", icon: <ArrowLeftRight className="h-4 w-4" />, tone: "transfer" },
];

export interface TransactionFormProps {
  /** Omit to create. Provide to edit in place. */
  transaction?: LocalTransaction;
  onSaved?: (id: string) => void;
  onCancel?: () => void;
  /** Compact variant used inside the bottom sheet. */
  dense?: boolean;
}

export function TransactionForm({
  transaction,
  onSaved,
  onCancel,
  dense = false,
}: TransactionFormProps) {
  const { lookups } = useLocalData();
  const { preferences, update } = usePreferences();
  const toast = useToast();

  const accounts = useMemo(
    () => lookups.dataset.accounts.filter((a) => !a.archived).sort((a, b) => a.name.localeCompare(b.name)),
    [lookups.dataset.accounts],
  );

  const [type, setType] = useState<TransactionType>(transaction?.type ?? "expense");
  const [amount, setAmount] = useState<number>(transaction ? Math.abs(transaction.amount) : 0);
  const [currency, setCurrency] = useState(transaction?.currency ?? accounts[0]?.currency ?? preferences.baseCurrency);
  const [fromAccount, setFromAccount] = useState<string>(
    transaction?.from_account_id ?? preferences.lastAccountId ?? accounts[0]?.id ?? "",
  );
  const [toAccount, setToAccount] = useState<string>(transaction?.to_account_id ?? "");
  const [categoryId, setCategoryId] = useState<string>(transaction?.category_id ?? "");
  const [date, setDate] = useState(transaction ? transaction.date.slice(0, 10) : todayKey());
  const [notes, setNotes] = useState(transaction?.notes ?? "");
  const [tagName, setTagName] = useState("");
  const [selectedTags, setSelectedTags] = useState<string[]>(transaction?.tag_ids ?? []);
  const [bookmarked, setBookmarked] = useState(transaction?.is_bookmarked ?? false);
  const [expanded, setExpanded] = useState(!dense && Boolean(transaction));
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const categories = useMemo(
    () =>
      lookups.dataset.categories
        .filter((c) => c.type === (type === "income" ? "income" : "expense"))
        .sort((a, b) => a.name.localeCompare(b.name)),
    [lookups.dataset.categories, type],
  );

  // Income credits an account; expense and transfer debit one. Keep the picker
  // semantically correct so the ledger stays consistent.
  const creditAccountId = type === "income" ? toAccount || fromAccount : toAccount;
  const debitAccountId = type === "income" ? fromAccount : fromAccount;
  const selectedAccountId = type === "income" ? creditAccountId : debitAccountId;

  const availableTags = useMemo(
    () => [...lookups.dataset.tags].sort((a, b) => a.name.localeCompare(b.name)),
    [lookups.dataset.tags],
  );

  async function submit(event: FormEvent) {
    event.preventDefault();
    setError(null);

    if (!amount || amount <= 0) {
      setError("Enter an amount greater than zero.");
      return;
    }
    if (!fromAccount) {
      setError("Choose an account.");
      return;
    }
    if (type === "transfer" && !toAccount) {
      setError("Choose the destination account for this transfer.");
      return;
    }
    if (type === "transfer" && toAccount === fromAccount) {
      setError("A transfer needs two different accounts.");
      return;
    }

    setBusy(true);
    try {
      let tagIds = selectedTags;
      if (tagName.trim()) {
        const existing = availableTags.find((tag) => tag.name.toLowerCase() === tagName.trim().toLowerCase());
        const tag = existing ?? (await createTag(tagName.trim()));
        tagIds = [...tagIds, tag.id];
      }

      // Income lands in an account, so it always uses the credit-side field.
      const payload = {
        type,
        amount: Math.abs(amount),
        currency,
        from_account_id: type === "income" ? null : fromAccount,
        to_account_id: type === "expense" ? null : (type === "income" ? fromAccount : toAccount),
        category_id: type === "transfer" ? null : categoryId || null,
        date: new Date(`${date}T12:00:00`).toISOString(),
        notes: notes.trim(),
        tag_ids: tagIds,
        is_bookmarked: bookmarked,
      };

      const saved = transaction
        ? ((await updateTransaction(transaction.id, payload)) ?? transaction)
        : await createTransaction({ ...payload, fx_rate: 1 });

      await update({
        lastAccountId: selectedAccountId || null,
        lastCategoryId: categoryId || null,
      });

      toast.push({
        tone: "success",
        title: transaction ? "Transaction updated" : `${type === "expense" ? "Expense" : type === "income" ? "Income" : "Transfer"} saved`,
        description: transaction ? undefined : "Stored on this device and queued for sync.",
      });
      onSaved?.(saved.id);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't save that transaction.");
    } finally {
      setBusy(false);
    }
  }

  async function bookmarkNow() {
    const next = !bookmarked;
    setBookmarked(next);
    if (transaction) await toggleBookmark(transaction.id);
  }

  return (
    <form onSubmit={submit} className="space-y-4" noValidate>
      {error && (
        <p role="alert" className="rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
          {error}
        </p>
      )}

      <SegmentedControl
        options={TYPE_OPTIONS}
        value={type}
        onChange={(next) => {
          setType(next);
          setCategoryId("");
        }}
        ariaLabel="Transaction type"
      />

      <Field label="Amount" htmlFor="tx-amount">
        <AmountInput
          id="tx-amount"
          value={amount}
          onChange={setAmount}
          currency={currency}
          tone={type === "income" ? "income" : type === "expense" ? "expense" : "default"}
          autoFocus={!transaction}
        />
      </Field>

      {type === "transfer" ? (
        <div className="grid grid-cols-2 gap-3">
          <Select
            label="From"
            value={fromAccount}
            onChange={(e) => setFromAccount(e.target.value)}
            required
          >
            <option value="">Select account</option>
            {accounts.map((a) => (
              <option key={a.id} value={a.id}>
                {a.name}
              </option>
            ))}
          </Select>
          <Select label="To" value={toAccount} onChange={(e) => setToAccount(e.target.value)} required>
            <option value="">Select account</option>
            {accounts.filter((a) => a.id !== fromAccount).map((a) => (
              <option key={a.id} value={a.id}>
                {a.name}
              </option>
            ))}
          </Select>
        </div>
      ) : (
        <div className="grid gap-3 sm:grid-cols-2">
          <Select
            label={type === "income" ? "Deposit into" : "Paid from"}
            value={fromAccount}
            onChange={(e) => setFromAccount(e.target.value)}
            required
          >
            <option value="">Select account</option>
            {accounts.map((a) => (
              <option key={a.id} value={a.id}>
                {a.name} · {a.currency}
              </option>
            ))}
          </Select>
          {type === "expense" && (
            <Select
              label="Category"
              value={categoryId}
              onChange={(e) => setCategoryId(e.target.value)}
              hint={!categories.length ? "Create categories first." : undefined}
            >
              <option value="">Uncategorised</option>
              {categories.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.parent_id ? "↳ " : ""}
                  {c.name}
                </option>
              ))}
            </Select>
          )}
        </div>
      )}

      <div className="grid gap-3 sm:grid-cols-2">
        <Input
          label="Date"
          type="date"
          value={date}
          max={todayKey()}
          onChange={(e) => setDate(e.target.value)}
          required
        />
        {type !== "transfer" && (
          <Select
            label="Currency"
            value={currency}
            onChange={(e) => setCurrency(e.target.value)}
            hint={`Reports use ${preferences.baseCurrency}`}
          >
            {CURRENCIES.map((code) => (
              <option key={code} value={code}>
                {code}
              </option>
            ))}
          </Select>
        )}
      </div>

      <Textarea
        label="Note"
        value={notes}
        onChange={(e) => setNotes(e.target.value)}
        placeholder="Merchant, description or anything you'll want to remember"
        maxLength={280}
        addon={
          <button
            type="button"
            onClick={bookmarkNow}
            aria-pressed={bookmarked}
            aria-label={bookmarked ? "Remove bookmark" : "Bookmark this transaction"}
            className={`icon-btn h-7 w-7 ${bookmarked ? "text-warning" : ""}`}
          >
            <Bookmark className={`h-4 w-4 ${bookmarked ? "fill-warning/25" : ""}`} />
          </button>
        }
      />

      <Collapsible
        defaultOpen={expanded}
        summary={
          <span className="flex items-center gap-1.5 text-sm font-medium text-ink">
            <Paperclip aria-hidden="true" className="h-4 w-4 text-muted" />
            Tags & attachments
          </span>
        }
      >
        <div className="space-y-3">
          {availableTags.length > 0 && (
            <div>
              <p className="label mb-1.5">Existing tags</p>
              <div className="flex flex-wrap gap-1.5">
                {availableTags.map((tag) => {
                  const on = selectedTags.includes(tag.id);
                  return (
                    <button
                      key={tag.id}
                      type="button"
                      aria-pressed={on}
                      onClick={() =>
                        setSelectedTags((prev) =>
                          on ? prev.filter((id) => id !== tag.id) : [...prev, tag.id],
                        )
                      }
                      className={`rounded-full border px-2.5 py-1 text-xs font-medium transition-colors ${
                        on
                          ? "border-primary bg-primary-soft-bg text-primary"
                          : "border-line-strong text-muted hover:text-ink"
                      }`}
                    >
                      {tag.name}
                    </button>
                  );
                })}
              </div>
            </div>
          )}
          <Input
            label="Add a tag"
            value={tagName}
            onChange={(e) => setTagName(e.target.value)}
            placeholder="e.g. Reimbursable"
          />
          <p className="field-hint">
            Receipt uploads need a connection. Attach from the transaction screen once it is saved.
          </p>
        </div>
      </Collapsible>

      <div className="flex items-center gap-2 pt-1">
        <Button type="submit" variant="primary" size="lg" loading={busy} className="flex-1">
          {transaction ? "Save changes" : "Save transaction"}
        </Button>
        {onCancel && (
          <Button type="button" variant="ghost" size="lg" onClick={onCancel}>
            Cancel
          </Button>
        )}
      </div>
    </form>
  );
}

/** Read-only preview of the category chip shown above the amount. */
export function CategoryChip({ categoryId }: { categoryId: string | null }) {
  const { lookups } = useLocalData();
  if (!categoryId) return null;
  const category = lookups.category.get(categoryId);
  if (!category) return null;
  const Icon = categoryIcon(category.icon, category.name);
  return (
    <span className="inline-flex items-center gap-1.5 text-sm text-muted">
      <Icon aria-hidden="true" className="h-4 w-4" />
      {category.name}
    </span>
  );
}

/** Icon button helper kept local so the form file has no layout dependencies. */
export { IconButton };

/** Human date helper re-exported for host screens that show the saved date. */
export { formatDate };

/**
 * Quick add.
 *
 * The fastest path from "I just spent money" to a recorded transaction: bottom
 * sheet on mobile, side drawer on desktop, amount first. Opened from the central
 * "+" in the mobile bottom bar and from the Overview/Transactions actions.
 */
import { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { Overlay } from "../../components/ui";
import { TransactionForm } from "./TransactionForm";
import type { TransactionType } from "./TransactionForm";

export interface QuickAddSheetProps {
  open: boolean;
  onClose: () => void;
}

const TYPES: TransactionType[] = ["expense", "income", "transfer"];

/**
 * Deep-linkable: `/transactions?add=expense` opens the sheet straight into that
 * type, which is what the "New expense" / "New income" buttons use.
 */
export function QuickAddSheet({ open, onClose }: QuickAddSheetProps) {
  const [params, setParams] = useSearchParams();
  const requested = params.get("add");
  const initial = TYPES.includes(requested as TransactionType) ? (requested as TransactionType) : null;
  const [, setType] = useState<TransactionType | null>(initial);
  setType(initial);

  // Clear the deep link once the sheet closes so a refresh doesn't reopen it.
  useEffect(() => {
    if (!open && requested) {
      const next = new URLSearchParams(params);
      next.delete("add");
      setParams(next, { replace: true });
    }
    // Only react to the query string, not to params identity churn.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, requested]);

  if (!open) return null;

  return (
    <Overlay
      open={open}
      onClose={onClose}
      title="Add transaction"
      description="Saved on this device first, then synced."
      variant="sheet"
      size="md"
    >
      <TransactionForm dense onSaved={onClose} onCancel={onClose} />
    </Overlay>
  );
}

/**
 * Quick add.
 *
 * The fastest path from "I just spent money" to a recorded transaction: bottom
 * sheet on mobile, side drawer on desktop, amount first. Opened from the central
 * "+" in the mobile bottom bar and from the Overview/Transactions actions.
 */
import { useEffect } from "react";
import { useSearchParams } from "react-router-dom";
import { Overlay } from "../../components/ui";
import { TransactionForm, type TransactionType } from "./TransactionForm";

export interface QuickAddSheetProps {
  open: boolean;
  onClose: () => void;
}

const TYPES: TransactionType[] = ["expense", "income", "transfer"];

/**
 * Deep-linkable: `/transactions?add=expense` opens the sheet straight into that
 * type, which is what the "New expense" / "New income" buttons link to.
 */
export function QuickAddSheet({ open, onClose }: QuickAddSheetProps) {
  const [params, setParams] = useSearchParams();
  const requested = params.get("add");
  const initialType = TYPES.includes(requested as TransactionType)
    ? (requested as TransactionType)
    : undefined;

  // Clear the deep link once the sheet closes so a refresh doesn't reopen it.
  const requestedKey = requested ?? "";
  useEffect(() => {
    if (open || !requestedKey) return;
    const next = new URLSearchParams(params);
    next.delete("add");
    setParams(next, { replace: true });
    // `params` is intentionally omitted: depending on its identity would loop.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, requestedKey]);

  if (!open) return null;

  return (
    <Overlay
      open={open}
      onClose={onClose}
      title="Add transaction"
      description="Saved on this device first, then synced."
      variant="sheet"
      size="md"
    >
      <TransactionForm
        key={initialType ?? "default"}
        initialType={initialType}
        dense
        onSaved={onClose}
        onCancel={onClose}
      />
    </Overlay>
  );
}

