/**
 * Account editor.
 *
 * Shared by the Accounts page and the account detail screen. Credit-limit and
 * statement fields only appear for card accounts, so the form stays short for
 * the common case.
 */
import { useState, type FormEvent } from "react";
import type { LocalAccount } from "../../db/types";
import { CURRENCIES } from "../../design/format";
import {
  AmountInput,
  Button,
  Field,
  Input,
  Overlay,
  Select,
  Textarea,
  useToast,
} from "../../components/ui";
import { ACCOUNT_TYPE_LABELS, ACCOUNT_TYPE_GROUPS, accountIcon } from "../../design/icons";
import { useLocalData } from "../analytics/useLocalData";
import { createAccount, updateAccount } from "../../db/repositories";

const CREDIT_TYPES = new Set(["credit", "debit"]);

export interface AccountFormOverlayProps {
  open: boolean;
  onClose: () => void;
  /** Omit to create a new account. */
  account?: LocalAccount;
}

export function AccountFormOverlay({ open, onClose, account }: AccountFormOverlayProps) {
  const { lookups } = useLocalData();
  const toast = useToast();
  const editing = Boolean(account);

  const [name, setName] = useState(account?.name ?? "");
  const [type, setType] = useState(account?.type ?? "bank");
  const [currency, setCurrency] = useState(account?.currency ?? lookups.dataset.baseCurrency);
  const [opening, setOpening] = useState(account ? account.opening_balance : 0);
  const [limit, setLimit] = useState(account?.credit_limit ?? 0);
  const [statementDay, setStatementDay] = useState(account?.statement_day ?? 1);
  const [dueDay, setDueDay] = useState(account?.due_day ?? 20);
  const [groupId, setGroupId] = useState(account?.group_id ?? "");
  const [notes, setNotes] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const isCard = CREDIT_TYPES.has(type);

  async function submit(event: FormEvent) {
    event.preventDefault();
    setError(null);
    if (!name.trim()) {
      setError("Give the account a name you will recognise.");
      return;
    }
    setBusy(true);
    try {
      if (account) {
        await updateAccount(account.id, {
          name: name.trim(),
          type,
          currency,
          opening_balance: opening,
          credit_limit: isCard && limit > 0 ? limit : null,
          statement_day: isCard ? statementDay : null,
          due_day: isCard ? dueDay : null,
          group_id: groupId || null,
        });
        toast.push({ tone: "success", title: "Account updated" });
      } else {
        await createAccount({
          name: name.trim(),
          type,
          currency,
          opening_balance: opening,
          credit_limit: isCard && limit > 0 ? limit : null,
          statement_day: isCard ? statementDay : null,
          due_day: isCard ? dueDay : null,
          group_id: groupId || null,
        });
        toast.push({
          tone: "success",
          title: "Account added",
          description: "Balances update as soon as you record transactions.",
        });
      }
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't save that account.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <Overlay
      open={open}
      onClose={onClose}
      title={editing ? "Edit account" : "Add account"}
      description={editing ? undefined : "Cash, bank, e-wallet, savings, investment or card."}
      variant="sheet"
      size="md"
    >
      <form onSubmit={submit} className="space-y-4" noValidate>
        {error && (
          <p role="alert" className="rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
            {error}
          </p>
        )}

        <Input
          label="Account name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="e.g. BDO Savings"
          maxLength={60}
          required
          autoFocus
        />

        <Field label="Type" required>
          <div className="grid grid-cols-3 gap-1.5 sm:grid-cols-5">
            {ACCOUNT_TYPE_GROUPS.map((group) => {
              const Icon = accountIcon(group.key);
              const active = type === group.key;
              return (
                <button
                  key={group.key}
                  type="button"
                  aria-pressed={active}
                  onClick={() => setType(group.key)}
                  className={`flex flex-col items-center gap-1 rounded-lg border px-2 py-2 text-[11px] font-medium transition-colors ${
                    active
                      ? "border-primary bg-primary-soft-bg text-primary"
                      : "border-line-strong text-muted hover:text-ink"
                  }`}
                >
                  <Icon aria-hidden="true" className="h-4 w-4" />
                  <span className="truncate">{ACCOUNT_TYPE_LABELS[group.key] ?? group.label}</span>
                </button>
              );
            })}
          </div>
        </Field>

        <div className="grid gap-3 sm:grid-cols-2">
          <Select label="Currency" value={currency} onChange={(e) => setCurrency(e.target.value)}>
            {CURRENCIES.map((code) => (
              <option key={code} value={code}>
                {code}
              </option>
            ))}
          </Select>
          <Field
            label={editing ? "Opening balance" : "Starting balance"}
            htmlFor="acct-opening"
            hint={editing ? "Changing this recalculates history." : undefined}
          >
            <AmountInput
              id="acct-opening"
              value={opening}
              onChange={setOpening}
              currency={currency}
              size="md"
            />
          </Field>
        </div>

        {isCard && (
          <div className="space-y-3 rounded-lg border border-line bg-surface-sunken p-3">
            <p className="text-xs font-semibold tracking-wide text-ink-soft uppercase">
              Card details
            </p>
            <Field label="Credit limit" htmlFor="acct-limit" hint="0 means no limit set.">
              <AmountInput id="acct-limit" value={limit} onChange={setLimit} currency={currency} size="md" />
            </Field>
            <div className="grid grid-cols-2 gap-3">
              <Input
                label="Statement day"
                type="number"
                min={1}
                max={31}
                value={statementDay}
                onChange={(e) => setStatementDay(Number(e.target.value))}
              />
              <Input
                label="Payment due day"
                type="number"
                min={1}
                max={31}
                value={dueDay}
                onChange={(e) => setDueDay(Number(e.target.value))}
              />
            </div>
          </div>
        )}

        {lookups.dataset.accounts.length > 0 && (
          <Select
            label="Group"
            value={groupId}
            onChange={(e) => setGroupId(e.target.value)}
            hint="Optional — used to group related accounts."
          >
            <option value="">No group</option>
            {["Personal", "Business", "Shared", "Savings"].map((name) => (
              <option key={name} value={name}>
                {name}
              </option>
            ))}
          </Select>
        )}

        <Textarea
          label="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Account number, bank branch, anything useful"
        />

        <div className="flex gap-2 pt-1">
          <Button type="submit" variant="primary" size="lg" loading={busy} className="flex-1">
            {editing ? "Save account" : "Add account"}
          </Button>
          <Button type="button" variant="ghost" size="lg" onClick={onClose}>
            Cancel
          </Button>
        </div>
      </form>
    </Overlay>
  );
}

/**
 * Accounts.
 *
 * A ledger-first list: totals across the top, then accounts grouped by type with
 * the metadata that matters per type (credit limit and utilization for cards,
 * plain balances for everything else). No permanent creation form - the editor
 * is a sheet that opens from the header (§14).
 */
import { useEffect, useMemo, useState } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import {
  Archive,
  ArrowLeft,
  ChevronRight,
  CreditCard,
  Landmark,
  MoreHorizontal,
  Plus,
  Wallet,
} from "lucide-react";
import {
  Badge,
  Button,
  Card,
  ConfirmOverlay,
  Dropdown,
  EmptyState,
  IconButton,
  PageHeader,
  ProgressBar,
  Stat,
  useToast,
} from "../../components/ui";
import type { LocalAccount } from "../../db/types";
import { formatMoney, formatPercent } from "../../design/format";
import { ACCOUNT_TYPE_GROUPS, ACCOUNT_TYPE_LABELS, accountIcon } from "../../design/icons";
import { useLocalData } from "../analytics/useLocalData";
import { accountTotals, isLiability, portfolio, type AccountTotals } from "../analytics/engine";
import { periodRange, type Period } from "../analytics/period";
import { usePreferences } from "../settings/preferences";
import { deleteAccount, updateAccount } from "../../db/repositories";
import { AccountFormOverlay } from "./AccountFormOverlay";

export function AccountsPage() {
  const { lookups, ready } = useLocalData();
  const { preferences, update } = usePreferences();
  const toast = useToast();
  const navigate = useNavigate();
  const [params, setParams] = useSearchParams();

  const [editorOpen, setEditorOpen] = useState(false);
  const [editing, setEditing] = useState<LocalAccount | undefined>();
  const [pendingDelete, setPendingDelete] = useState<LocalAccount | null>(null);
  const [busy, setBusy] = useState(false);

  // Deep link: `/accounts?new=1` opens the create sheet (used by the Overview
  // empty state so a first-time user never lands on a dead page).
  const wantNew = params.get("new") === "1";
  useEffect(() => {
    if (!wantNew || !ready) return;
    setEditing(undefined);
    setEditorOpen(true);
    const next = new URLSearchParams(params);
    next.delete("new");
    setParams(next, { replace: true });
  }, [wantNew, ready, params, setParams]);

  const period: Period = useMemo(
    () => ({ kind: "month", anchor: new Date(), monthStartDay: preferences.monthStartDay }),
    [preferences.monthStartDay],
  );
  const range = periodRange(period);

  const totals = useMemo(
    () => accountTotals(lookups.dataset, lookups, range),
    [lookups, range],
  );
  const summary = useMemo(() => portfolio(lookups), [lookups]);

  const visible = useMemo(
    () => (preferences.showArchived ? totals : totals.filter((t) => !t.account.archived)),
    [totals, preferences.showArchived],
  );

  const grouped = useMemo(() => {
    const map = new Map<string, AccountTotals[]>();
    for (const item of visible) {
      const list = map.get(item.account.type) ?? [];
      list.push(item);
      map.set(item.account.type, list);
    }
    return ACCOUNT_TYPE_GROUPS.map((group) => ({
      ...group,
      items: (map.get(group.key) ?? []).sort((a, b) =>
        Math.abs(b.balance) - Math.abs(a.balance),
      ),
    })).filter((group) => group.items.length > 0);
  }, [visible]);

  function openCreate() {
    setEditing(undefined);
    setEditorOpen(true);
  }

  function openEdit(account: LocalAccount) {
    setEditing(account);
    setEditorOpen(true);
  }

  async function toggleArchive(account: LocalAccount) {
    await updateAccount(account.id, { archived: !account.archived });
    toast.push({
      tone: "success",
      title: account.archived ? "Account restored" : "Account archived",
      description: account.archived
        ? "It will show on your Accounts page again."
        : "History is kept — it just leaves your default lists.",
    });
  }

  async function confirmDelete() {
    if (!pendingDelete) return;
    setBusy(true);
    try {
      await deleteAccount(pendingDelete.id);
      toast.push({ tone: "success", title: "Account deleted" });
      setPendingDelete(null);
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't delete account",
        description: err instanceof Error ? err.message : undefined,
      });
    } finally {
      setBusy(false);
    }
  }

  const archivedCount = totals.filter((t) => t.account.archived).length;

  return (
    <div className="space-y-4">
      <PageHeader
        title="Accounts"
        subtitle={`${visible.length} ${visible.length === 1 ? "account" : "accounts"} · balances in ${lookups.dataset.baseCurrency}`}
        actions={
          <>
            {archivedCount > 0 && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => void update({ showArchived: !preferences.showArchived })}
              >
                {preferences.showArchived ? "Hide archived" : `Show archived (${archivedCount})`}
              </Button>
            )}
            <Button variant="primary" size="sm" icon={<Plus className="h-4 w-4" />} onClick={openCreate}>
              Add account
            </Button>
          </>
        }
      />

      {/* Totals first: assets, liabilities, net worth. */}
      <Card>
        <div className="grid grid-cols-1 divide-y divide-line sm:grid-cols-3 sm:divide-x sm:divide-y-0">
          <div className="px-4 py-3.5">
            <Stat
              label="Total assets"
              value={formatMoney(summary.assets, lookups.dataset.baseCurrency)}
              icon={<Wallet className="h-3.5 w-3.5" />}
            />
          </div>
          <div className="px-4 py-3.5">
            <Stat
              label="Total liabilities"
              tone={summary.liabilities < 0 ? "expense" : "default"}
              value={formatMoney(summary.liabilities, lookups.dataset.baseCurrency)}
              icon={<Landmark className="h-3.5 w-3.5" />}
            />
          </div>
          <div className="px-4 py-3.5">
            <Stat
              label="Net worth"
              emphasis="large"
              tone={summary.netWorth >= 0 ? "primary" : "expense"}
              value={formatMoney(summary.netWorth, lookups.dataset.baseCurrency)}
            />
          </div>
        </div>
      </Card>

      {totals.length === 0 ? (
        <Card>
          <EmptyState
            icon={<Wallet className="h-7 w-7" />}
            title="No accounts yet"
            description="Add the cash, bank and card accounts you actually use. FinTrack recalculates balances from your transactions, so an accurate opening balance is all it needs."
            action={
              <Button variant="primary" icon={<Plus className="h-4 w-4" />} onClick={openCreate}>
                Add your first account
              </Button>
            }
            secondaryAction={
              <Button variant="ghost" onClick={() => navigate("/settings")}>
                Change base currency
              </Button>
            }
          />
        </Card>
      ) : (
        <div className="space-y-4">
          {grouped.map((group) => (
            <section key={group.key} className="card overflow-hidden">
              <header className="flex items-center justify-between gap-2 border-b border-line px-4 py-2.5">
                <h2 className="text-xs font-semibold tracking-wider text-muted uppercase">
                  {group.label}
                </h2>
                <span className="tabular text-xs text-muted">
                  {group.items.length} ·{" "}
                  {formatMoney(
                    group.items.reduce((sum, item) => sum + item.balance, 0),
                    lookups.dataset.baseCurrency,
                  )}
                </span>
              </header>
              <ul className="divide-y divide-line">
                {group.items.map((item) => (
                  <AccountListRow
                    key={item.account.id}
                    item={item}
                    currency={lookups.dataset.baseCurrency}
                    onEdit={() => openEdit(item.account)}
                    onToggleArchive={() => void toggleArchive(item.account)}
                    onDelete={() => setPendingDelete(item.account)}
                  />
                ))}
              </ul>
            </section>
          ))}
        </div>
      )}

      <AccountFormOverlay open={editorOpen} onClose={() => setEditorOpen(false)} account={editing} />

      <ConfirmOverlay
        open={pendingDelete !== null}
        busy={busy}
        onClose={() => setPendingDelete(null)}
        onConfirm={() => void confirmDelete()}
        title="Delete this account?"
        confirmLabel="Delete account"
        message={
          <>
            <strong>{pendingDelete?.name}</strong> will be removed from this device and your other
            devices. Accounts with transactions can only be archived.
          </>
        }
      />
    </div>
  );
}

/** One row. Credit cards get their utilization line instead of plain metadata. */
function AccountListRow({
  item,
  currency,
  onEdit,
  onToggleArchive,
  onDelete,
}: {
  item: AccountTotals;
  currency: string;
  onEdit: () => void;
  onToggleArchive: () => void;
  onDelete: () => void;
}) {
  const account = item.account;
  const Icon = accountIcon(account.type);
  const isCard = account.type === "credit" || account.type === "debit";
  const liability = isLiability(account.type);
  const tone = liability ? "text-expense" : "text-ink";

  return (
    <li className="row-link flex items-center gap-3 px-4 py-3">
      <Link to={`/accounts/${account.id}`} className="flex min-w-0 flex-1 items-center gap-3">
        <span
          aria-hidden="true"
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-surface-sunken text-ink-soft"
        >
          {isCard ? <CreditCard className="h-4 w-4" /> : <Icon className="h-4 w-4" />}
        </span>

        <span className="min-w-0 flex-1">
          <span className="flex items-center gap-1.5">
            <span className="truncate text-sm font-medium text-ink">{account.name}</span>
            {account.archived && <Badge tone="neutral">Archived</Badge>}
          </span>
          <span className="tabular block truncate text-xs text-muted">
            {isCard && item.creditLimit !== null ? (
              <>
                {formatMoney(item.creditUsed ?? 0, account.currency)} of{" "}
                {formatMoney(item.creditLimit, account.currency)} used
                {item.utilization !== null && ` · ${formatPercent(item.utilization)}`}
              </>
            ) : (
              <>
                {ACCOUNT_TYPE_LABELS[account.type] ?? account.type} · {account.currency}
                {item.transactionCount > 0 && ` · ${item.transactionCount} this month`}
              </>
            )}
          </span>
          {isCard && item.utilization !== null && (
            <ProgressBar
              value={item.utilization}
              size="xs"
              className="mt-1.5 max-w-xs"
              tone={item.utilization > 80 ? "warning" : "primary"}
              label={`${account.name} credit utilization`}
            />
          )}
        </span>

        <span className={`tabular shrink-0 text-sm font-semibold ${tone}`}>
          {formatMoney(item.balance, currency)}
        </span>
      </Link>

      <Dropdown
        label={`Actions for ${account.name}`}
        trigger={<MoreHorizontal className="h-5 w-5" />}
        items={[
          {
            id: "open",
            label: "View history",
            icon: <ArrowLeft aria-hidden="true" className="h-4 w-4" />,
            onSelect: () => {
              window.location.assign(`/accounts/${account.id}`);
            },
          },
          {
            id: "edit",
            label: "Edit",
            icon: <ChevronRight aria-hidden="true" className="h-4 w-4" />,
            onSelect: onEdit,
          },
          {
            id: "archive",
            label: account.archived ? "Restore" : "Archive",
            icon: <Archive aria-hidden="true" className="h-4 w-4" />,
            onSelect: onToggleArchive,
          },
          {
            id: "delete",
            label: "Delete",
            tone: "danger",
            icon: <Archive aria-hidden="true" className="h-4 w-4" />,
            onSelect: onDelete,
          },
        ]}
      />
    </li>
  );
}

