const esbuild=require('esbuild');const fs=require('fs');
const p='src/features/overview/OverviewPage.tsx';
const orig=fs.readFileSync(p,'utf8').split(/\r?\n/);
async function check(lines){ try{ await esbuild.transform(lines.join('\n'),{loader:'tsx'}); return null; }catch(e){ return e.errors[0].location.line; } }
(async()=>{
  // Greedy shrink: repeatedly try deleting chunks until it parses.
  let lines=orig.slice();
  for (let step=0; step<200; step++){
    const err=await check(lines);
    if(err===null){ console.log('PARSES after removing', orig.length-lines.length,'lines'); fs.writeFileSync('_min.txt',lines.join('\n')); return; }
    // try removing a window around the error, expanding size each iteration
    let removed=false;
    for(const size of [1,2,4,8,16,32,64,128,256]){
      const start=Math.max(0,err-1-Math.floor(size/2));
      const cand=lines.filter((_,i)=>!(i>=start && i<start+size));
      if(cand.length===lines.length) continue;
      const e2=await check(cand);
      if(e2===null || e2!==err){ lines=cand; removed=true; break; }
    }
    if(!removed){ console.log('stuck at line',err); break; }
  }
  fs.writeFileSync('_min.txt',lines.join('\n'));
  console.log('final lines',lines.length);
})();
