/**
 * Sync conflicts.
 *
 * Reached from the header badge and the account menu at `/sync/conflicts`. A
 * conflict means this device and the server both changed the same row while the
 * device was offline; nothing is lost until the user picks a side, and both
 * copies are shown side by side so the choice is informed (§9).
 */
import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { ArrowDownToLine, ArrowUpFromLine, CircleCheck, CloudSync, ShieldAlert } from "lucide-react";
import {
  Alert,
  Badge,
  Button,
  Card,
  CardHeader,
  EmptyState,
  PageHeader,
  useToast,
} from "../../components/ui";
import type { ConflictEntry } from "../../db/types";
import { formatDate } from "../../design/format";
import { useSync } from "../../sync/SyncContext";
import { resolveWithLocal, resolveWithServer } from "../../sync/syncEngine";

export function ConflictsPage() {
  const { conflicts, syncNow, pendingCount } = useSync();
  const queryClient = useQueryClient();
  const toast = useToast();
  const [busy, setBusy] = useState<string | null>(null);

  async function resolve(conflict: ConflictEntry, side: "server" | "local") {
    setBusy(conflict.id);
    try {
      if (side === "server") {
        await resolveWithServer(conflict.id);
        toast.push({
          tone: "success",
          title: "Kept the server version",
          description: "Your local edit for this row was discarded.",
        });
      } else {
        await resolveWithLocal(conflict.id);
        toast.push({
          tone: "success",
          title: "Kept your version",
          description: "It will be pushed to the server on the next sync.",
        });
      }
      void queryClient.invalidateQueries();
      void syncNow();
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't resolve conflict",
        description: err instanceof Error ? err.message : undefined,
      });
    } finally {
      setBusy(null);
    }
  }

  return (
    <div className="space-y-4">
      <PageHeader
        title="Sync conflicts"
        subtitle={`${conflicts.length} row${conflicts.length === 1 ? "" : "s"} need a decision`}
        actions={
          <Button variant="secondary" size="sm" icon={<CloudSync className="h-4 w-4" />} loading={busy === "__sync"} onClick={() => void syncNow()}>
            Sync now
          </Button>
        }
      />

      <Alert tone="info" title="Nothing here is lost">
        A conflict means both this device and your server copy changed the same record while you
        were offline. Pick the version to keep — the other one is discarded for that row only, and
        everything else keeps syncing normally.
      </Alert>

      {conflicts.length === 0 ? (
        <Card>
          <EmptyState
            icon={<CircleCheck className="h-7 w-7" />}
            title="No sync conflicts"
            description="Every change you make on this device has been accepted by the server. Conflicts show up here if an edit races ahead while you're offline."
            action={
              <Button variant="secondary" icon={<CloudSync className="h-4 w-4" />} onClick={() => void syncNow()}>
                Run a sync
              </Button>
            }
            secondaryAction={
              pendingCount > 0 ? <Badge tone="warning">{pendingCount} changes waiting</Badge> : undefined
            }
          />
        </Card>
      ) : (
        <div className="space-y-3">
          {conflicts.map((conflict) => (
            <Card key={conflict.id}>
              <CardHeader
                title={
                  <span className="flex items-center gap-2">
                    <span className="capitalize">{conflict.entity.replace(/s$/, "")}</span>
                    <span className="font-mono text-xs text-faint">{conflict.entity_id.slice(0, 8)}</span>
                  </span>
                }
                subtitle={formatDate(conflict.created_at, "medium")}
                icon={<ShieldAlert className="h-4 w-4" />}
                action={<Badge tone="warning">{conflict.op}</Badge>}
              />
              <div className="space-y-3 px-4 py-3">
                <p className="text-sm text-ink">{conflict.message}</p>
                <p className="text-xs text-muted">
                  Server version {conflict.server_version} · local operation "{conflict.op}"
                </p>

                <div className="grid gap-3 sm:grid-cols-2">
                  <div className="rounded-lg border border-line bg-surface-sunken p-3">
                    <p className="mb-1.5 flex items-center gap-1.5 text-xs font-semibold tracking-wide text-muted uppercase">
                      <ArrowDownToLine aria-hidden="true" className="h-3.5 w-3.5" />
                      Server copy
                    </p>
                    <p className="line-clamp-3 text-xs break-all text-ink-soft">
                      {conflict.payload ? JSON.stringify(conflict.payload).slice(0, 220) : "Not cached on this device"}
                    </p>
                    <Button
                      variant="secondary"
                      size="sm"
                      className="mt-2 w-full"
                      loading={busy === conflict.id}
                      onClick={() => void resolve(conflict, "server")}
                    >
                      Use server version
                    </Button>
                  </div>

                  <div className="rounded-lg border border-line bg-surface-sunken p-3">
                    <p className="mb-1.5 flex items-center gap-1.5 text-xs font-semibold tracking-wide text-muted uppercase">
                      <ArrowUpFromLine aria-hidden="true" className="h-3.5 w-3.5" />
                      Your edit
                    </p>
                    <p className="line-clamp-3 text-xs break-all text-ink-soft">
                      {conflict.op === "delete"
                        ? "You deleted this row on this device."
                        : "The pending change queued in your outbox."}
                    </p>
                    <Button
                      variant="primary"
                      size="sm"
                      className="mt-2 w-full"
                      loading={busy === conflict.id}
                      onClick={() => void resolve(conflict, "local")}
                    >
                      Keep my version
                    </Button>
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Budget editor.
 *
 * Routed at `/budgets/new` and `/budgets/:budgetId/edit` so the URL is the
 * source of truth — the browser Back button closes it and a shared link opens
 * the same sheet.
 */
import { useEffect, useState, type FormEvent } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "../../db";
import { createBudget, deleteBudget, updateBudget } from "../../db/repositories";
import type { LocalBudget } from "../../db/types";
import {
  AmountInput,
  Button,
  ConfirmOverlay,
  Field,
  Input,
  Overlay,
  Select,
  useToast,
} from "../../components/ui";
import { useLocalData } from "../analytics/useLocalData";

type Period = LocalBudget["period"];

const PERIODS: { id: Period; label: string }[] = [
  { id: "monthly", label: "Monthly" },
  { id: "weekly", label: "Weekly" },
  { id: "yearly", label: "Yearly" },
];

export function BudgetEditor() {
  const navigate = useNavigate();
  const toast = useToast();
  const { budgetId } = useParams<{ budgetId: string }>();
  const editing = budgetId !== undefined;
  const { lookups, ready } = useLocalData();

  const budget = useLiveQuery(
    async () => (budgetId ? db.budgets.get(budgetId) : undefined),
    [budgetId],
    undefined,
  );

  const [amount, setAmount] = useState(0);
  const [categoryId, setCategoryId] = useState("");
  const [period, setPeriod] = useState<Period>("monthly");
  const [startDate, setStartDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [threshold, setThreshold] = useState(80);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);

  useEffect(() => {
    if (!editing || !budget) return;
    setAmount(budget.amount);
    setCategoryId(budget.category_id ?? "");
    setPeriod(budget.period);
    setStartDate(budget.start_date.slice(0, 10));
    setThreshold(budget.alert_threshold);
  }, [editing, budget]);

  const categories = [...lookups.dataset.categories]
    .filter((row) => !row.parent_id && row.type === "expense")
    .sort((a, b) => a.name.localeCompare(b.name));

  const currency = lookups.dataset.baseCurrency;

  async function save() {
    setError(null);
    if (!amount || amount <= 0) {
      setError("Set a budget greater than zero.");
      return;
    }
    setBusy(true);
    try {
      if (editing && budget) {
        await updateBudget(budget.id, {
          amount,
          category_id: categoryId || null,
          period,
          start_date: startDate,
          alert_threshold: threshold,
        });
        toast.push({ tone: "success", title: "Budget updated" });
      } else {
        await createBudget({
          amount,
          category_id: categoryId || null,
          period,
          start_date: startDate,
          alert_threshold: threshold,
        });
        toast.push({
          tone: "success",
          title: "Budget created",
          description: "Spending in this category now counts against it.",
        });
      }
      navigate("/budgets");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't save that budget.");
    } finally {
      setBusy(false);
    }
  }

  function submit(event: FormEvent) {
    event.preventDefault();
    void save();
  }

  async function remove() {
    if (!budgetId) return;
    setBusy(true);
    try {
      await deleteBudget(budgetId);
      toast.push({ tone: "success", title: "Budget deleted" });
      navigate("/budgets");
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't delete budget",
        description: err instanceof Error ? err.message : undefined,
      });
    } finally {
      setBusy(false);
      setConfirmDelete(false);
    }
  }

  if (editing && !budget && ready) {
    return (
      <Overlay
        open
        onClose={() => navigate("/budgets")}
        title="Budget not found"
        variant="sheet"
        size="sm"
        footer={
          <Button variant="primary" onClick={() => navigate("/budgets")}>
            Back to budgets
          </Button>
        }
      >
        <p className="text-sm text-muted">It may have been deleted on another device.</p>
      </Overlay>
    );
  }

  return (
    <>
      <Overlay
        open
        onClose={() => navigate("/budgets")}
        title={editing ? "Edit budget" : "New budget"}
        description="Leave the category empty to budget your total spending."
        variant="sheet"
        size="md"
        footer={
          <>
            {editing && <Button variant="danger" onClick={() => setConfirmDelete(true)}>Delete</Button>}
            <Button variant="ghost" onClick={() => navigate("/budgets")}>
              Cancel
            </Button>
            <Button variant="primary" loading={busy} onClick={() => void save()}>
              {editing ? "Save changes" : "Create budget"}
            </Button>
          </>
        }
      >
        <form onSubmit={submit} className="space-y-4" noValidate>
          {error && (
            <p role="alert" className="rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
              {error}
            </p>
          )}

          <Field label="Limit" htmlFor="budget-amount" required>
            <AmountInput
              id="budget-amount"
              value={amount}
              onChange={setAmount}
              currency={currency}
              autoFocus={!editing}
            />
          </Field>

          <div className="grid gap-3 sm:grid-cols-2">
            <Select
              label="Category"
              value={categoryId}
              onChange={(event) => setCategoryId(event.target.value)}
              hint="Empty means total spending."
            >
              <option value="">Everything I spend</option>
              {categories.map((row) => (
                <option key={row.id} value={row.id}>
                  {row.name}
                </option>
              ))}
            </Select>

            <Select label="Period" value={period} onChange={(event) => setPeriod(event.target.value as Period)}>
              {PERIODS.map((option) => (
                <option key={option.id} value={option.id}>
                  {option.label}
                </option>
              ))}
            </Select>
          </div>

          <div className="grid gap-3 sm:grid-cols-2">
            <Input
              label="Starts"
              type="date"
              value={startDate}
              onChange={(event) => setStartDate(event.target.value)}
              hint="Weekly and yearly budgets run from this date."
            />
            <Input
              label="Alert me at"
              type="number"
              min={1}
              max={200}
              value={threshold}
              onChange={(event) => setThreshold(Number(event.target.value))}
              suffix="% of the limit"
              hint="Turns the bar amber once crossed."
            />
          </div>

          <button type="submit" className="sr-only">
            Save
          </button>
        </form>
      </Overlay>

      <ConfirmOverlay
        open={confirmDelete}
        busy={busy}
        tone="danger"
        onClose={() => setConfirmDelete(false)}
        onConfirm={() => void remove()}
        title="Delete this budget?"
        confirmLabel="Delete budget"
        message="Your transactions are untouched — you just lose the limit for that category."
      />
    </>
  );
}

