/**
 * Savings-goal editor.
 *
 * Routed at `/goals/new` and `/goals/:goalId/edit`. Contributions are never
 * entered here — they are ledger entries tagged with the goal, so the balance
 * always traces back to real transactions.
 */
import { useEffect, useState, type FormEvent } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "../../db";
import {
  createSavingsGoal,
  deleteSavingsGoal,
  updateSavingsGoal,
} from "../../db/repositories";
import {
  AmountInput,
  Button,
  ConfirmOverlay,
  Field,
  Input,
  Overlay,
  Select,
  useToast,
} from "../../components/ui";
import { useLocalData } from "../analytics/useLocalData";

export function GoalEditor() {
  const navigate = useNavigate();
  const toast = useToast();
  const { goalId } = useParams<{ goalId: string }>();
  const editing = goalId !== undefined;
  const { lookups, ready } = useLocalData();

  const goal = useLiveQuery(
    async () => (goalId ? db.savings_goals.get(goalId) : undefined),
    [goalId],
    undefined,
  );

  const [name, setName] = useState("");
  const [target, setTarget] = useState(0);
  const [currency, setCurrency] = useState(lookups.dataset.baseCurrency);
  const [targetDate, setTargetDate] = useState("");
  const [linkedAccount, setLinkedAccount] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);

  useEffect(() => {
    if (!editing || !goal) return;
    setName(goal.name);
    setTarget(goal.target_amount);
    setCurrency(goal.currency);
    setTargetDate(goal.target_date ? goal.target_date.slice(0, 10) : "");
    setLinkedAccount(goal.linked_account_id ?? "");
  }, [editing, goal]);

  const accounts = [...lookups.dataset.accounts]
    .filter((row) => !row.archived)
    .sort((a, b) => a.name.localeCompare(b.name));

  async function save() {
    setError(null);
    if (!name.trim()) {
      setError("Name the goal so you recognise it later.");
      return;
    }
    if (!target || target <= 0) {
      setError("Set a target greater than zero.");
      return;
    }
    setBusy(true);
    try {
      if (editing && goal) {
        await updateSavingsGoal(goal.id, {
          name: name.trim(),
          target_amount: target,
          currency,
          target_date: targetDate || null,
          linked_account_id: linkedAccount || null,
        });
        toast.push({ tone: "success", title: "Goal updated" });
      } else {
        await createSavingsGoal({
          name: name.trim(),
          target_amount: target,
          currency,
          target_date: targetDate || null,
          linked_account_id: linkedAccount || null,
        });
        toast.push({
          tone: "success",
          title: "Goal created",
          description: "Transfer money to it and progress updates automatically.",
        });
      }
      navigate("/goals");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't save that goal.");
    } finally {
      setBusy(false);
    }
  }

  function submit(event: FormEvent) {
    event.preventDefault();
    void save();
  }

  async function remove() {
    if (!goalId) return;
    setBusy(true);
    try {
      await deleteSavingsGoal(goalId);
      toast.push({ tone: "success", title: "Goal deleted" });
      navigate("/goals");
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't delete goal",
        description: err instanceof Error ? err.message : undefined,
      });
    } finally {
      setBusy(false);
      setConfirmDelete(false);
    }
  }

  if (editing && !goal && ready) {
    return (
      <Overlay
        open
        onClose={() => navigate("/goals")}
        title="Goal not found"
        variant="sheet"
        size="sm"
        footer={<Button variant="primary" onClick={() => navigate("/goals")}>Back to goals</Button>}
      >
        <p className="text-sm text-muted">It may have been deleted on another device.</p>
      </Overlay>
    );
  }

  return (
    <>
      <Overlay
        open
        onClose={() => navigate("/goals")}
        title={editing ? "Edit goal" : "New savings goal"}
        description="Progress comes from the transactions tagged with this goal."
        variant="sheet"
        size="md"
        footer={
          <>
            {editing && <Button variant="danger" onClick={() => setConfirmDelete(true)}>Delete</Button>}
            <Button variant="ghost" onClick={() => navigate("/goals")}>Cancel</Button>
            <Button variant="primary" loading={busy} onClick={() => void save()}>
              {editing ? "Save changes" : "Create goal"}
            </Button>
          </>
        }
      >
        <form onSubmit={submit} className="space-y-4" noValidate>
          {error && (
            <p role="alert" className="rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
              {error}
            </p>
          )}

          <Input
            label="What are you saving for?"
            value={name}
            onChange={(event) => setName(event.target.value)}
            placeholder="e.g. Emergency fund"
            maxLength={80}
            required
            autoFocus={!editing}
          />

          <Field label="Target" htmlFor="goal-target" required>
            <AmountInput
              id="goal-target"
              value={target}
              onChange={setTarget}
              currency={currency}
              autoFocus={false}
            />
          </Field>

          <div className="grid gap-3 sm:grid-cols-2">
            <Select label="Currency" value={currency} onChange={(event) => setCurrency(event.target.value)}>
              {[...new Set([lookups.dataset.baseCurrency, ...accounts.map((a) => a.currency)])].map(
                (code) => (
                  <option key={code} value={code}>
                    {code}
                  </option>
                ),
              )}
            </Select>
            <Input
              label="Target date"
              type="date"
              value={targetDate}
              onChange={(event) => setTargetDate(event.target.value)}
              hint="Optional — enables the required-per-month figure."
            />
          </div>

          <Select
            label="Linked account"
            value={linkedAccount}
            onChange={(event) => setLinkedAccount(event.target.value)}
            hint="Optional — shows the account alongside progress."
          >
            <option value="">None</option>
            {accounts.map((row) => (
              <option key={row.id} value={row.id}>
                {row.name}
              </option>
            ))}
          </Select>

          <button type="submit" className="sr-only">
            Save
          </button>
        </form>
      </Overlay>

      <ConfirmOverlay
        open={confirmDelete}
        busy={busy}
        tone="danger"
        onClose={() => setConfirmDelete(false)}
        onConfirm={() => void remove()}
        title="Delete this goal?"
        confirmLabel="Delete goal"
        message="Contributions you recorded stay in your ledger — only the target goes away."
      />
    </>
  );
}

/**
 * Savings goals.
 *
 * Progress is derived from the ledger — contributions are transactions tagged
 * with the goal — so the bar is honest even when recorded offline. A goal that
 * needs money each month to hit its date says exactly how much (§26).
 */
import { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { ArrowRight, CalendarClock, PiggyBank, Plus, Target, Trophy } from "lucide-react";
import {
  Button,
  Card,
  EmptyState,
  LinkButton,
  PageHeader,
  ProgressBar,
  Stat,
} from "../../components/ui";
import { formatMoney, formatPercent, formatRelativeTime } from "../../design/format";
import { useLocalData } from "../analytics/useLocalData";
import { goalProgress, type GoalProgress } from "../analytics/engine";

export function GoalsPage() {
  const { lookups, dataset, ready } = useLocalData();
  const navigate = useNavigate();

  const progress = useMemo(
    () => goalProgress(dataset.goals, dataset.transactions, lookups),
    [dataset.goals, dataset.transactions, lookups],
  );

  const currency = lookups.dataset.baseCurrency;
  const savedTotal = progress.reduce((sum, item) => sum + item.saved, 0);
  const targetTotal = progress.reduce((sum, item) => sum + item.target, 0);
  const completed = progress.filter((item) => item.percent >= 100).length;
  const onSchedule = progress.filter((item) => item.onTrack || item.daysLeft === null).length;

  const [selected, setSelected] = useState<string | null>(null);
  const detail = progress.find((item) => item.goal.id === selected) ?? null;

  return (
    <div className="space-y-4">
      <PageHeader
        title="Savings goals"
        subtitle={
          progress.length > 0
            ? `${completed} complete · ${onSchedule} of ${progress.length} on track`
            : "Set a target, then fund it from your ledger"
        }
        actions={
          <Button
            variant="primary"
            size="sm"
            icon={<Plus className="h-4 w-4" />}
            onClick={() => navigate("/goals/new")}
          >
            New goal
          </Button>
        }
      />

      {progress.length > 0 && (
        <Card>
          <div className="flex flex-wrap items-end justify-between gap-4 px-4 py-4">
            <Stat
              label="Total saved toward goals"
              emphasis="hero"
              value={formatMoney(savedTotal, currency)}
              caption={`of ${formatMoney(targetTotal, currency)} targeted`}
              icon={<Target className="h-3.5 w-3.5" />}
            />
            <div className="grid grid-cols-2 gap-x-8">
              <Stat
                label="Overall"
                value={formatPercent(targetTotal > 0 ? (savedTotal / targetTotal) * 100 : 0)}
              />
              <Stat label="Completed" value={`${completed}`} />
            </div>
          </div>
          {targetTotal > 0 && (
            <div className="px-4 pb-4">
              <ProgressBar
                value={(savedTotal / targetTotal) * 100}
                tone="income"
                label="Overall savings progress"
              />
            </div>
          )}
        </Card>
      )}

      {ready && dataset.goals.length === 0 ? (
        <Card>
          <EmptyState
            icon={<Target className="h-7 w-7" />}
            title="No savings goals yet"
            description="A goal turns an abstract number into something you can chase: it tracks what you've put aside, tells you what's left, and shows whether a target date is realistic. Create one for the next thing you're saving for."
            action={
              <Button variant="primary" icon={<Plus className="h-4 w-4" />} onClick={() => navigate("/goals/new")}>
                Create a goal
              </Button>
            }
            secondaryAction={<LinkButton to="/transactions?add=transfer">Record a contribution</LinkButton>}
          />
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {progress.map((item) => (
            <GoalCard
              key={item.goal.id}
              item={item}
              currency={currency}
              selected={selected === item.goal.id}
              onSelect={() => setSelected(selected === item.goal.id ? null : item.goal.id)}
              onEdit={() => navigate(`/goals/${item.goal.id}/edit`)}
            />
          ))}
        </div>
      )}

      {detail && (
        <Card>
          <div className="border-b border-line px-4 py-3">
            <h2 className="text-sm font-semibold text-ink">{detail.goal.name} — activity</h2>
            <p className="text-xs text-muted">
              {detail.contributions.length} contribution
              {detail.contributions.length === 1 ? "" : "s"} recorded
            </p>
          </div>
          {detail.contributions.length === 0 ? (
            <EmptyState
              compact
              icon={<PiggyBank className="h-6 w-6" />}
              title="No contributions yet"
              description="Record a transfer into the goal's account and tag it here — the bar updates immediately."
              action={
                <Button
                  variant="secondary"
                  size="sm"
                  onClick={() => navigate("/transactions?add=transfer")}
                >
                  Add a contribution
                </Button>
              }
            />
          ) : (
            <ul className="divide-y divide-line">
              {detail.contributions.slice(0, 8).map((tx) => (
                <li key={tx.id} className="flex items-center justify-between gap-3 px-4 py-2.5">
                  <div className="min-w-0">
                    <p className="truncate text-sm text-ink">{tx.notes || "Contribution"}</p>
                    <p className="text-xs text-muted">{formatRelativeTime(tx.date)}</p>
                  </div>
                  <span className="tabular text-sm font-semibold text-income">
                    +{formatMoney(Math.abs(tx.amount), tx.currency)}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      )}
    </div>
  );
}

function GoalCard({
  item,
  currency,
  selected,
  onSelect,
  onEdit,
}: {
  item: GoalProgress;
  currency: string;
  selected: boolean;
  onSelect: () => void;
  onEdit: () => void;
}) {
  const done = item.percent >= 100;
  const pct = Math.min(100, item.percent);

  return (
    <Card
      className={`p-4 transition-colors ${selected ? "border-primary ring-1 ring-primary/30" : ""}`}
    >
      <button type="button" onClick={onSelect} aria-expanded={selected} className="w-full text-left">
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <p className="flex items-center gap-1.5 truncate text-sm font-semibold text-ink">
              <Target aria-hidden="true" className="h-4 w-4 shrink-0 text-primary" />
              {item.goal.name}
            </p>
            {item.goal.target_date && (
              <p className="mt-0.5 flex items-center gap-1 text-xs text-muted">
                <CalendarClock aria-hidden="true" className="h-3.5 w-3.5" />
                By {formatRelativeTime(item.goal.target_date)}
              </p>
            )}
          </div>
          {done && <Trophy aria-label="Goal complete" className="h-5 w-5 shrink-0 text-warning" />}
        </div>

        <div className="mt-3 flex items-baseline justify-between gap-2">
          <span className={`tabular text-title font-semibold ${done ? "text-income" : "text-ink"}`}>
            {formatMoney(item.saved, currency)}
          </span>
          <span className="tabular text-xs text-muted">of {formatMoney(item.target, currency)}</span>
        </div>

        <ProgressBar
          value={pct}
          size="sm"
          tone={done ? "income" : "primary"}
          className="mt-2"
          label={`${item.goal.name} progress`}
        />

        <div className="mt-2 flex items-center justify-between gap-2 text-xs">
          <span className="tabular font-medium text-ink-soft">{formatPercent(item.percent)}</span>
          <span className="tabular text-muted">
            {done ? "Complete" : `${formatMoney(item.remaining, currency)} to go`}
          </span>
        </div>
      </button>

      {!done && item.requiredMonthly !== null && item.daysLeft !== null && item.daysLeft > 0 && (
        <p className="mt-2 border-t border-line pt-2 text-xs text-muted">
          <span className="font-medium text-ink">
            {formatMoney(item.requiredMonthly, currency)}
          </span>{" "}
          per month to hit your date
        </p>
      )}

      <div className="mt-3 flex items-center justify-between">
        <button
          type="button"
          onClick={onSelect}
          className="inline-flex items-center gap-1 text-xs font-medium text-primary hover:underline"
        >
          {selected ? "Hide activity" : "View activity"}
          <ArrowRight aria-hidden="true" className="h-3 w-3" />
        </button>
        <button
          type="button"
          onClick={onEdit}
          className="text-xs font-medium text-muted hover:text-ink"
        >
          Edit
        </button>
      </div>
    </Card>
  );
}

/**
 * Debt editor.
 *
 * Routed at `/debts/new` and `/debts/:debtId/edit`. The direction ("I owe" vs
 * "owed to me") is chosen first because it decides whether payments reduce or
 * increase your net worth — never both.
 */
import { useEffect, useState, type FormEvent } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "../../db";
import { createDebt, deleteDebt, updateDebt } from "../../db/repositories";
import {
  AmountInput,
  Button,
  ConfirmOverlay,
  Field,
  Input,
  Overlay,
  SegmentedControl,
  Select,
  Textarea,
  useToast,
} from "../../components/ui";
import { useLocalData } from "../analytics/useLocalData";

export function DebtEditor() {
  const navigate = useNavigate();
  const toast = useToast();
  const { debtId } = useParams<{ debtId: string }>();
  const editing = debtId !== undefined;
  const { lookups, ready } = useLocalData();

  const debt = useLiveQuery(
    async () => (debtId ? db.debts.get(debtId) : undefined),
    [debtId],
    undefined,
  );

  const [counterparty, setCounterparty] = useState("");
  const [direction, setDirection] = useState<"i_owe" | "owed_to_me">("i_owe");
  const [amount, setAmount] = useState(0);
  const [currency, setCurrency] = useState(lookups.dataset.baseCurrency);
  const [dueDate, setDueDate] = useState("");
  const [notes, setNotes] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);

  useEffect(() => {
    if (!editing || !debt) return;
    setCounterparty(debt.counterparty);
    setDirection(debt.direction);
    setAmount(debt.original_amount);
    setCurrency(debt.currency);
    setDueDate(debt.due_date ? debt.due_date.slice(0, 10) : "");
    setNotes(debt.notes);
  }, [editing, debt]);

  async function save() {
    setError(null);
    if (!counterparty.trim()) {
      setError("Name the person or institution on the other side.");
      return;
    }
    if (!amount || amount <= 0) {
      setError("Enter an amount greater than zero.");
      return;
    }
    setBusy(true);
    try {
      if (editing && debt) {
        await updateDebt(debt.id, {
          counterparty: counterparty.trim(),
          direction,
          original_amount: amount,
          currency,
          due_date: dueDate || null,
          notes,
        });
        toast.push({ tone: "success", title: "Debt updated" });
      } else {
        await createDebt({
          counterparty: counterparty.trim(),
          direction,
          original_amount: amount,
          currency,
          due_date: dueDate || null,
          notes,
        });
        toast.push({
          tone: "success",
          title: direction === "i_owe" ? "Debt recorded" : "Receivable recorded",
          description: "Payments made against it will show up in its history.",
        });
      }
      navigate("/debts");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't save that debt.");
    } finally {
      setBusy(false);
    }
  }

  function submit(event: FormEvent) {
    event.preventDefault();
    void save();
  }

  async function remove() {
    if (!debtId) return;
    setBusy(true);
    try {
      await deleteDebt(debtId);
      toast.push({ tone: "success", title: "Debt deleted" });
      navigate("/debts");
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't delete debt",
        description: err instanceof Error ? err.message : undefined,
      });
    } finally {
      setBusy(false);
      setConfirmDelete(false);
    }
  }

  if (editing && !debt && ready) {
    return (
      <Overlay
        open
        onClose={() => navigate("/debts")}
        title="Debt not found"
        variant="sheet"
        size="sm"
        footer={<Button variant="primary" onClick={() => navigate("/debts")}>Back to debts</Button>}
      >
        <p className="text-sm text-muted">It may have been deleted on another device.</p>
      </Overlay>
    );
  }

  return (
    <>
      <Overlay
        open
        onClose={() => navigate("/debts")}
        title={editing ? "Edit" : "New"}
        description="Who owes whom, how much, and by when."
        variant="sheet"
        size="md"
        footer={
          <>
            {editing && <Button variant="danger" onClick={() => setConfirmDelete(true)}>Delete</Button>}
            <Button variant="ghost" onClick={() => navigate("/debts")}>Cancel</Button>
            <Button variant="primary" loading={busy} onClick={() => void save()}>
              {editing ? "Save changes" : "Create"}
            </Button>
          </>
        }
      >
        <form onSubmit={submit} className="space-y-4" noValidate>
          {error && (
            <p role="alert" className="rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
              {error}
            </p>
          )}

          <Field label="Direction" required>
            <SegmentedControl
              options={[
                { id: "i_owe", label: "I owe", tone: "expense" },
                { id: "owed_to_me", label: "Owed to me", tone: "income" },
              ]}
              value={direction}
              onChange={(next) => setDirection(next)}
              ariaLabel="Debt direction"
            />
          </Field>

          <Input
            label={direction === "i_owe" ? "Owed to" : "Owed by"}
            value={counterparty}
            onChange={(event) => setCounterparty(event.target.value)}
            placeholder={direction === "i_owe" ? "e.g. Bank" : "e.g. Alex"}
            maxLength={80}
            required
            autoFocus={!editing}
          />

          <Field label="Amount" htmlFor="debt-amount" required>
            <AmountInput
              id="debt-amount"
              value={amount}
              onChange={setAmount}
              currency={currency}
              tone={direction === "i_owe" ? "expense" : "income"}
              autoFocus={false}
            />
          </Field>

          <div className="grid gap-3 sm:grid-cols-2">
            <Select label="Currency" value={currency} onChange={(event) => setCurrency(event.target.value)}>
              {[lookups.dataset.baseCurrency, "USD", "EUR", "GBP", "PHP"].filter(
                (code, index, all) => all.indexOf(code) === index,
              ).map((code) => (
                <option key={code} value={code}>
                  {code}
                </option>
              ))}
            </Select>
            <Input
              label="Due date"
              type="date"
              value={dueDate}
              onChange={(event) => setDueDate(event.target.value)}
              hint="Optional — drives the overdue badge."
            />
          </div>

          <Textarea
            label="Notes"
            value={notes}
            onChange={(event) => setNotes(event.target.value)}
            placeholder="Agreement, interest rate, anything worth remembering"
            maxLength={280}
          />

          <button type="submit" className="sr-only">
            Save
          </button>
        </form>
      </Overlay>

      <ConfirmOverlay
        open={confirmDelete}
        busy={busy}
        tone="danger"
        onClose={() => setConfirmDelete(false)}
        onConfirm={() => void remove()}
        title="Delete this record?"
        confirmLabel="Delete"
        message="Linked payment transactions stay in your ledger; only this running balance goes away."
      />
    </>
  );
}

/**
 * Debts & receivables.
 *
 * Two lists, never mixed: money you owe and money owed to you. Each row shows
 * how much is settled, and the whole page stays explicitly separate from income
 * and expense so a borrowed sum can never inflate a report (§27).
 */
import { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  ArrowDownRight,
  ArrowUpRight,
  CalendarClock,
  HandCoins,
  Landmark,
  Plus,
} from "lucide-react";
import {
  Alert,
  Button,
  Card,
  CardHeader,
  EmptyState,
  LinkButton,
  PageHeader,
  ProgressBar,
  SegmentedControl,
  Stat,
} from "../../components/ui";
import { formatMoney, formatPercent, formatRelativeDay } from "../../design/format";
import { useLocalData } from "../analytics/useLocalData";
import { debtSummary, type DebtSummary } from "../analytics/engine";

export function DebtsPage() {
  const { lookups, dataset, ready } = useLocalData();
  const navigate = useNavigate();
  const [direction, setDirection] = useState<"i_owe" | "owed_to_me">("i_owe");

  const summary = useMemo(
    () => debtSummary(dataset.debts, dataset.transactions, lookups),
    [dataset.debts, dataset.transactions, lookups],
  );

  const currency = lookups.dataset.baseCurrency;
  const owed = summary.filter((item) => item.debt.direction === "i_owe");
  const receivable = summary.filter((item) => item.debt.direction === "owed_to_me");

  const sumRemaining = (rows: DebtSummary[]) =>
    rows.reduce(
      (total, item) =>
        total +
        // Amounts may be in another currency; the converted remainder keeps the
        // page's own totals in one unit.
        item.debt.remaining_amount,
      0,
    );

  const outstanding = sumRemaining(owed);
    void sumRemaining(receivable);

  const active = direction === "i_owe" ? owed : receivable;
  const overdueCount = summary.filter((item) => item.overdue).length;

  return (
    <div className="space-y-4">
      <PageHeader
        title="Debts"
        subtitle={
          summary.length > 0
            ? `${overdueCount} overdue · ${summary.length} open`
            : "Track what you owe and what you're owed"
        }
        actions={
          <Button
            variant="primary"
            size="sm"
            icon={<Plus className="h-4 w-4" />}
            onClick={() => navigate("/debts/new")}
          >
            New
          </Button>
        }
        tabs={
          <div className="flex flex-wrap items-center gap-2">
            <SegmentedControl
              size="sm"
              options={[
                { id: "i_owe", label: `I owe (${owed.length})`, icon: <ArrowDownRight className="h-3.5 w-3.5" /> },
                { id: "owed_to_me", label: `Owed to me (${receivable.length})`, icon: <ArrowUpRight className="h-3.5 w-3.5" /> },
              ]}
              value={direction}
              onChange={setDirection}
              ariaLabel="Debt direction"
            />
          </div>
        }
      />

      <Alert tone="info" title="Debts are not income or expense">
        A loan is money moving, not money earned. Repayments are recorded as transfers, so
        spending reports and net worth stay correct while a balance is being settled.
      </Alert>

      {summary.length > 0 && (
        <Card>
          <div className="grid grid-cols-1 divide-y divide-line sm:grid-cols-3 sm:divide-x sm:divide-y-0">
            <div className="px-4 py-3.5">
              <Stat
                label="You owe"
                tone="expense"
                value={formatMoney(outstanding, currency)}
                icon={<Landmark className="h-3.5 w-3.5" />}
              />
            </div>
            <div className="px-4 py-3.5">
              <Stat
                label="Owed to you"
                tone="income"
                value={formatMoney(
                  receivable.reduce((sum, item) => sum + item.debt.remaining_amount, 0),
                  currency,
                )}
                icon={<HandCoins className="h-3.5 w-3.5" />}
              />
            </div>
            <div className="px-4 py-3.5">
              <Stat
                label="Overdue"
                tone={overdueCount > 0 ? "expense" : "muted"}
                value={`${overdueCount}`}
                caption={overdueCount > 0 ? "Needs attention" : "All clear"}
              />
            </div>
          </div>
        </Card>
      )}

      {ready && dataset.debts.length === 0 ? (
        <Card>
          <EmptyState
            icon={<Landmark className="h-7 w-7" />}
            title="No debts recorded"
            description="Whether it's a credit-card balance, a friend you'll repay, or money someone owes you, keeping it here means the total is always visible instead of lurking in the back of your mind."
            action={
              <Button variant="primary" icon={<Plus className="h-4 w-4" />} onClick={() => navigate("/debts/new")}>
                Record one
              </Button>
            }
            secondaryAction={<LinkButton to="/credit-cards">Open credit cards</LinkButton>}
          />
        </Card>
      ) : active.length === 0 ? (
        <Card>
          <EmptyState
            icon={direction === "i_owe" ? <Landmark className="h-7 w-7" /> : <HandCoins className="h-7 w-7" />}
            title={direction === "i_owe" ? "Nothing owed" : "Nobody owes you anything"}
            description={
              direction === "i_owe"
                ? "Switch the tab to record a receivable, or add a new one."
                : "Switch the tab to record something you're owed, or add a new one."
            }
            action={
              <Button variant="secondary" onClick={() => setDirection(direction === "i_owe" ? "owed_to_me" : "i_owe")}>
                Switch view
              </Button>
            }
          />
        </Card>
      ) : (
        <div className="space-y-3">
          {active.map((item) => (
            <DebtRow key={item.debt.id} item={item} currency={currency} />
          ))}
        </div>
      )}
    </div>
  );
}

function DebtRow({ item, currency }: { item: DebtSummary; currency: string }) {
  const navigate = useNavigate();
  const { debt } = item;
  const iOwe = debt.direction === "i_owe";

  return (
    <Card className="p-4">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <p className="flex items-center gap-2 text-sm font-semibold text-ink">
            <span className="truncate">{debt.counterparty}</span>
            {item.overdue && <span className="badge-failed">Overdue</span>}
          </p>
          <p className="mt-0.5 text-xs text-muted">
            {iOwe ? "You owe" : "Owed to you"} ·{" "}
            {debt.due_date ? `due ${formatRelativeDay(debt.due_date)}` : "no due date"}
            {debt.notes && ` · ${debt.notes}`}
          </p>
        </div>
        <button
          type="button"
          onClick={() => navigate(`/debts/${debt.id}/edit`)}
          className="shrink-0 text-xs font-medium text-primary hover:underline"
        >
          Edit
        </button>
      </div>

      <div className="mt-3 flex items-baseline justify-between gap-3">
        <span className={`tabular text-title font-semibold ${iOwe ? "text-expense" : "text-income"}`}>
          {formatMoney(debt.remaining_amount, debt.currency)}
        </span>
        <span className="tabular text-xs text-muted">
          of {formatMoney(debt.original_amount, debt.currency)} · {formatPercent(item.percent)} settled
        </span>
      </div>

      <ProgressBar
        value={item.percent}
        size="sm"
        tone={item.percent >= 100 ? "income" : "primary"}
        className="mt-2"
        label={`${debt.counterparty} repayment progress`}
      />

      <div className="mt-2 flex items-center justify-between gap-2 text-xs">
        <span className="text-muted">
          {item.percent >= 100 ? "Settled in full" : `${item.payments.length} payment${item.payments.length === 1 ? "" : "s"} recorded`}
        </span>
        {debt.due_date && (
          <span className={`flex items-center gap-1 ${item.overdue ? "text-expense" : "text-muted"}`}>
            <CalendarClock aria-hidden="true" className="h-3.5 w-3.5" />
            {item.daysUntilDue !== null &&
              (item.daysUntilDue < 0
                ? `${Math.abs(item.daysUntilDue)} days late`
                : item.daysUntilDue === 0
                  ? "Due today"
                  : `In ${item.daysUntilDue} days`)}
          </span>
        )}
      </div>

      {item.payments.length > 0 && (
        <ul className="mt-3 divide-y divide-line border-t border-line pt-1">
          {item.payments.slice(0, 3).map((tx) => (
            <li key={tx.id} className="flex items-center justify-between gap-3 py-1.5">
              <span className="min-w-0 truncate text-xs text-muted">
                {tx.notes || "Payment"} · {formatRelativeDay(tx.date)}
              </span>
              <span className="tabular shrink-0 text-xs font-semibold text-ink">
                {formatMoney(Math.abs(tx.amount), tx.currency)}
              </span>
            </li>
          ))}
        </ul>
      )}
    </Card>
  );
}

