input.content:
/**
 * Routed account editor.
 *
 * One component serves four URLs — `/accounts/new`, `/accounts/:accountId/edit`,
 * `/credit-cards/new` and `/credit-cards/:cardId/edit` — so the overlay is always
 * addressable, the Back button closes it, and a shared link opens the right row.
 */
import { useNavigate, useParams } from "react-router-dom";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "../../db";
import { Button, Overlay } from "../../components/ui";
import { AccountFormOverlay } from "./AccountFormOverlay";
import { useLocalData } from "../analytics/useLocalData";

export function AccountEditor() {
  const navigate = useNavigate();
  const { accountId, cardId } = useParams<{ accountId: string; cardId: string }>();
  const id = accountId ?? cardId;
  const editing = id !== undefined;
  const { ready } = useLocalData();

  const account = useLiveQuery(
    async () => (id ? db.accounts.get(id) : undefined),
    [id],
    undefined,
  );

  const close = () => navigate(editing && id ? `/accounts/${id}` : "/accounts");

  if (editing && !account && ready) {
    return (
      <Overlay
        open
        onClose={() => navigate("/accounts")}
        title="Account not found"
        description="It may have been deleted on another device, or the link is out of date."
        variant="sheet"
        size="sm"
        footer={
          <Button variant="primary" onClick={() => navigate("/accounts")}>
            Back to accounts
          </Button>
        }
      >
        <p className="text-sm text-muted">Nothing here matches a stored account.</p>
      </Overlay>
    );
  }

  // `AccountFormOverlay` owns its own state, so it is keyed by id: switching
  // between rows remounts it rather than carrying stale fields across.
  return <AccountFormOverlay key={id ?? "new"} open onClose={close} account={account} />;
}

/**
 * Credit cards.
 *
 * Their own section because the questions differ from a bank account: what have
 * I used, when does the statement close, when is it due. Balances and history
 * come from the same ledger, so nothing here is a second source of truth (§25).
 */
import { useMemo } from "react";
import { useNavigate, useParams } from "react-router-dom";
import {
  CalendarClock,
  CreditCard,
  Landmark,
  Plus,
  TrendingUp,
} from "lucide-react";
import {
  Alert,
  Button,
  Card,
  EmptyState,
  LinkButton,
  PageHeader,
  ProgressBar,
  Stat,
} from "../../components/ui";
import { formatMoney, formatPercent } from "../../design/format";
import { useLocalData } from "../analytics/useLocalData";
import { usePreferences } from "../settings/preferences";
import { isLiability, summarize } from "../analytics/engine";
import { periodRange, type Period } from "../analytics/period";

const CARD_TYPES = new Set(["credit", "debit"]);

export function CreditCardsPage() {
  const { lookups, dataset, ready } = useLocalData();
  const { preferences } = usePreferences();
  const navigate = useNavigate();

  const cards = useMemo(
    () =>
      dataset.accounts
        .filter((account) => CARD_TYPES.has(account.type) && !account.archived)
        .sort((a, b) => a.name.localeCompare(b.name)),
    [dataset.accounts],
  );

  const period: Period = useMemo(
    () => ({ kind: "month", anchor: new Date(), monthStartDay: preferences.monthStartDay }),
    [preferences.monthStartDay],
  );
  const range = periodRange(period);

  const totalLimit = cards.reduce((sum, card) => sum + (card.credit_limit ?? 0), 0);
  const totalUsed = cards.reduce(
    (sum, card) => sum + Math.abs(Math.min(0, card.current_balance)),
    0,
  );
  const utilization = totalLimit > 0 ? (totalUsed / totalLimit) * 100 : 0;

  const monthCharges = useMemo(
    () =>
      cards.reduce((total, card) => {
        const summary = summarize(
          dataset.transactions.filter((tx) => tx.from_account_id === card.id),
          range,
          lookups.fx,
          [card.id],
        );
        return total + summary.expense;
      }, 0),
    [cards, dataset.transactions, range, lookups.fx],
  );

  const currency = lookups.dataset.baseCurrency;

  return (
    <div className="space-y-4">
      <PageHeader
        title="Credit cards"
        subtitle={`${cards.length} active card${cards.length === 1 ? "" : "s"}`}
        actions={
          <Button
            variant="primary"
            size="sm"
            icon={<Plus className="h-4 w-4" />}
            onClick={() => navigate("/credit-cards/new")}
          >
            Add card
          </Button>
        }
      />

      {cards.length > 0 && (
        <Card>
          <div className="flex flex-wrap items-end justify-between gap-4 px-4 py-4">
            <Stat
              label="Total available credit"
              emphasis="hero"
              value={formatMoney(Math.max(0, totalLimit - totalUsed), currency)}
              caption={`of ${formatMoney(totalLimit, currency)} limit`}
              icon={<CreditCard className="h-3.5 w-3.5" />}
            />
            <div className="grid grid-cols-3 gap-x-8">
              <Stat
                label="Used"
                tone={utilization > 80 ? "expense" : "default"}
                value={formatMoney(totalUsed, currency)}
              />
              <Stat label="Utilization" value={formatPercent(utilization)} />
              <Stat
                label="This month"
                tone="expense"
                value={formatMoney(monthCharges, currency, { compact: true })}
              />
            </div>
          </div>
          <div className="px-4 pb-4">
            <ProgressBar
              value={utilization}
              tone={utilization > 80 ? "warning" : "primary"}
              label="Overall credit utilization"
            />
            <p className="mt-1.5 text-xs text-muted">
              Staying below 30% of your combined limit is generally easiest on your score.
            </p>
          </div>
        </Card>
      )}

      {ready && cards.length === 0 ? (
        <Card>
          <EmptyState
            icon={<CreditCard className="h-7 w-7" />}
            title="No credit cards yet"
            description="Add one and FinTrack tracks its balance, statement day, payment due date and utilization — then shows everything you owe in one place on this screen."
            action={
              <Button variant="primary" icon={<Plus className="h-4 w-4" />} onClick={() => navigate("/credit-cards/new")}>
                Add a card
              </Button>
            }
            secondaryAction={<LinkButton to="/accounts">See all accounts</LinkButton>}
          />
        </Card>
      ) : (
        <div className="space-y-3">
          {cards.map((card) => (
            <Card key={card.id} className="p-4">
              <div className="flex items-start justify-between gap-3">
                <button
                  type="button"
                  onClick={() => navigate(`/credit-cards/${card.id}`)}
                  className="min-w-0 flex-1 text-left"
                >
                  <p className="flex items-center gap-2 text-sm font-semibold text-ink">
                    <CreditCard aria-hidden="true" className="h-4 w-4 shrink-0 text-primary" />
                    <span className="truncate">{card.name}</span>
                  </p>
                  <p className="tabular mt-0.5 text-xs text-muted">
                    {card.currency} · {card.credit_limit ? `${formatMoney(card.credit_limit, card.currency)} limit` : "No limit set"}
                  </p>
                </button>
                <button
                  type="button"
                  onClick={() => navigate(`/credit-cards/${card.id}/edit`)}
                  className="shrink-0 text-xs font-medium text-primary hover:underline"
                >
                  Edit
                </button>
              </div>

              <div className="mt-3 flex items-baseline justify-between gap-3">
                <span className="tabular text-title font-semibold text-expense">
                  {formatMoney(Math.abs(Math.min(0, card.current_balance)), card.currency)}
                </span>
                <span className="tabular text-xs text-muted">
                  {card.credit_limit
                    ? `${formatMoney(Math.max(0, card.credit_limit + Math.min(0, card.current_balance)), card.currency)} available`
                    : "Set a limit to track utilization"}
                </span>
              </div>

              {card.credit_limit ? (
                <ProgressBar
                  value={
                    (Math.abs(Math.min(0, card.current_balance)) / card.credit_limit) * 100
                  }
                  size="sm"
                  tone={
                    (Math.abs(Math.min(0, card.current_balance)) / card.credit_limit) * 100 > 80
                      ? "warning"
                      : "primary"
                  }
                  className="mt-2"
                  label={`${card.name} credit utilization`}
                />
              ) : null}

              {(card.statement_day || card.due_day) && (
                <div className="mt-3 grid grid-cols-2 gap-3 border-t border-line pt-3">
                  {card.statement_day && (
                    <div className="flex items-center gap-2 text-xs text-muted">
                      <TrendingUp aria-hidden="true" className="h-3.5 w-3.5" />
                      Statement on day {card.statement_day}
                    </div>
                  )}
                  {card.due_day && (
                    <div className="flex items-center gap-2 text-xs text-muted">
                      <CalendarClock aria-hidden="true" className="h-3.5 w-3.5" />
                      Payment due day {card.due_day}
                    </div>
                  )}
                </div>
              )}
            </Card>
          ))}
        </div>
      )}

      <Alert tone="info" title="Where the balance comes from">
        Every swipe is a transaction against the card's account. That means the number here is
        always your real ledger balance, not a remembered total — including charges recorded on
        this device while offline.
      </Alert>

      <Card>
        <CardHeader
          title="Loan & installment accounts"
          icon={<Landmark className="h-4 w-4" />}
          action={<LinkButton to="/accounts">Open accounts</LinkButton>}
        />
        <ul className="divide-y divide-line">
          {dataset.accounts
            .filter((account) => isLiability(account.type) && !CARD_TYPES.has(account.type))
            .map((account) => (
              <li key={account.id} className="flex items-center justify-between gap-3 px-4 py-2.5">
                <button
                  type="button"
                  onClick={() => navigate(`/accounts/${account.id}`)}
                  className="min-w-0 flex-1 text-left"
                >
                  <p className="truncate text-sm font-medium text-ink">{account.name}</p>
                  <p className="text-xs text-muted">{account.currency}</p>
                </button>
                <span className="tabular text-sm font-semibold text-expense">
                  {formatMoney(Math.abs(account.current_balance), account.currency)}
                </span>
              </li>
            ))}
          {dataset.accounts.filter((account) => isLiability(account.type) && !CARD_TYPES.has(account.type))
            .length === 0 && (
            <li className="px-4 py-3 text-sm text-muted">
              No loan or deposit accounts to show here yet.
            </li>
          )}
        </ul>
      </Card>
    </div>
  );
}

/**
 * Recurring rule editor.
 *
 * `/recurring/new` and `/recurring/:recurringId/edit`. The rule describes the
 * schedule; occurrences become real transactions when the generator runs, so a
 * rule never fabricates money on its own.
 */
import { useEffect, useState, type FormEvent } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "../../db";
import { createRecurring, deleteRecurring, updateRecurring } from "../../db/repositories";
import type { LocalRecurring } from "../../db/types";
import {
  AmountInput,
  Button,
  ConfirmOverlay,
  Field,
  Input,
  Overlay,
  SegmentedControl,
  Select,
  Textarea,
  useToast,
} from "../../components/ui";
import { useLocalData } from "../analytics/useLocalData";

type Kind = LocalRecurring["type"];
type Frequency = LocalRecurring["frequency"];

const FREQUENCIES: { id: Frequency; label: string }[] = [
  { id: "daily", label: "Every day" },
  { id: "weekly", label: "Every week" },
  { id: "monthly", label: "Every month" },
  { id: "yearly", label: "Every year" },
];

export function RecurringEditor() {
  const navigate = useNavigate();
  const toast = useToast();
  const { recurringId } = useParams<{ recurringId: string }>();
  const editing = recurringId !== undefined;
  const { lookups, ready } = useLocalData();

  const rule = useLiveQuery(
    async () => (recurringId ? db.recurring.get(recurringId) : undefined),
    [recurringId],
    undefined,
  );

  const [type, setType] = useState<Kind>("expense");
  const [amount, setAmount] = useState(0);
  const [currency, setCurrency] = useState(lookups.dataset.baseCurrency);
  const [fromAccount, setFromAccount] = useState("");
  const [toAccount, setToAccount] = useState("");
  const [categoryId, setCategoryId] = useState("");
  const [frequency, setFrequency] = useState<Frequency>("monthly");
  const [nextRun, setNextRun] = useState(() => new Date().toISOString().slice(0, 10));
  const [endAt, setEndAt] = useState("");
  const [notes, setNotes] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);

  useEffect(() => {
    if (!editing || !rule) return;
    setType(rule.type);
    setAmount(rule.amount);
    setCurrency(rule.currency);
    setFromAccount(rule.from_account_id ?? "");
    setToAccount(rule.to_account_id ?? "");
    setCategoryId(rule.category_id ?? "");
    setFrequency(rule.frequency);
    setNextRun(rule.next_run_at.slice(0, 10));
    setEndAt(rule.end_at ? rule.end_at.slice(0, 10) : "");
    setNotes(rule.notes);
  }, [editing, rule]);

  const accounts = [...lookups.dataset.accounts]
    .filter((row) => !row.archived)
    .sort((a, b) => a.name.localeCompare(b.name));
  const categories = [...lookups.dataset.categories]
    .filter((row) => row.type === (type === "income" ? "income" : "expense"))
    .sort((a, b) => a.name.localeCompare(b.name));

  async function save() {
    setError(null);
    if (!amount || amount <= 0) {
      setError("Enter an amount greater than zero.");
      return;
    }
    if (!fromAccount && type !== "income") {
      setError("Choose the account this comes out of.");
      return;
    }
    if (!toAccount && type !== "expense") {
      setError("Choose the account this lands in.");
      return;
    }
    setBusy(true);
    try {
      const payload = {
        type,
        amount,
        currency,
        from_account_id: type === "income" ? null : fromAccount,
        to_account_id: type === "expense" ? null : type === "income" ? fromAccount : toAccount,
        category_id: categoryId || null,
        frequency,
        next_run_at: new Date(`${nextRun}T12:00:00`).toISOString(),
        end_at: endAt ? new Date(`${endAt}T12:00:00`).toISOString() : null,
        notes,
      };
      if (editing && rule) {
        await updateRecurring(rule.id, payload);
        toast.push({ tone: "success", title: "Recurring rule updated" });
      } else {
        await createRecurring(payload);
        toast.push({
          tone: "success",
          title: "Recurring rule created",
          description: "Occurrences appear in your ledger as they come due.",
        });
      }
      navigate("/recurring");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't save that rule.");
    } finally {
      setBusy(false);
    }
  }

  function submit(event: FormEvent) {
    event.preventDefault();
    void save();
  }

  async function remove() {
    if (!recurringId) return;
    setBusy(true);
    try {
      await deleteRecurring(recurringId);
      toast.push({ tone: "success", title: "Recurring rule deleted" });
      navigate("/recurring");
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't delete rule",
        description: err instanceof Error ? err.message : undefined,
      });
    } finally {
      setBusy(false);
      setConfirmDelete(false);
    }
  }

  if (editing && !rule && ready) {
    return (
      <Overlay
        open
        onClose={() => navigate("/recurring")}
        title="Rule not found"
        variant="sheet"
        size="sm"
        footer={<Button variant="primary" onClick={() => navigate("/recurring")}>Back</Button>}
      >
        <p className="text-sm text-muted">It may have been deleted on another device.</p>
      </Overlay>
    );
  }

  return (
    <>
      <Overlay
        open
        onClose={() => navigate("/recurring")}
        title={editing ? "Edit recurring rule" : "New recurring rule"}
        description="Rent, subscriptions, salary — anything that repeats."
        variant="sheet"
        size="md"
        footer={
          <>
            {editing && <Button variant="danger" onClick={() => setConfirmDelete(true)}>Delete</Button>}
            <Button variant="ghost" onClick={() => navigate("/recurring")}>Cancel</Button>
            <Button variant="primary" loading={busy} onClick={() => void save()}>
              {editing ? "Save changes" : "Create rule"}
            </Button>
          </>
        }
      >
        <form onSubmit={submit} className="space-y-4" noValidate>
          {error && (
            <p role="alert" className="rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
              {error}
            </p>
          )}

          <Field label="Kind" required>
            <SegmentedControl
              options={[
                { id: "expense", label: "Expense", tone: "expense" },
                { id: "income", label: "Income", tone: "income" },
                { id: "transfer", label: "Transfer", tone: "transfer" },
              ]}
              value={type}
              onChange={(next) => {
                setType(next);
                setCategoryId("");
              }}
              ariaLabel="Recurring kind"
            />
          </Field>

          <Field label="Amount" htmlFor="rec-amount" required>
            <AmountInput
              id="rec-amount"
              value={amount}
              onChange={setAmount}
              currency={currency}
              tone={type === "income" ? "income" : "expense"}
              autoFocus={!editing}
            />
          </Field>

          <div className="grid gap-3 sm:grid-cols-2">
            <Select
              label={type === "income" ? "Deposit into" : "Pay from"}
              value={fromAccount}
              onChange={(event) => setFromAccount(event.target.value)}
              required={type !== "income"}
            >
              <option value="">Select account</option>
              {accounts.map((row) => (
                <option key={row.id} value={row.id}>
                  {row.name}
                </option>
              ))}
            </Select>
            {type !== "expense" && (
              <Select
                label={type === "transfer" ? "Transfer to" : "Destination"}
                value={toAccount}
                onChange={(event) => setToAccount(event.target.value)}
                required={type !== "expense"}
              >
                <option value="">Select account</option>
                {accounts
                  .filter((row) => row.id !== fromAccount)
                  .map((row) => (
                    <option key={row.id} value={row.id}>
                      {row.name}
                    </option>
                  ))}
              </Select>
            )}
            {type !== "transfer" && (
              <Select
                label="Category"
                value={categoryId}
                onChange={(event) => setCategoryId(event.target.value)}
              >
                <option value="">Uncategorised</option>
                {categories.map((row) => (
                  <option key={row.id} value={row.id}>
                    {row.name}
                  </option>
                ))}
              </Select>
            )}
            <Select label="Frequency" value={frequency} onChange={(event) => setFrequency(event.target.value as Frequency)}>
              {FREQUENCIES.map((option) => (
                <option key={option.id} value={option.id}>
                  {option.label}
                </option>
              ))}
            </Select>
          </div>

          <div className="grid gap-3 sm:grid-cols-2">
            <Input
              label="Next run"
              type="date"
              value={nextRun}
              onChange={(event) => setNextRun(event.target.value)}
              required
            />
            <Input
              label="Ends"
              type="date"
              value={endAt}
              onChange={(event) => setEndAt(event.target.value)}
              hint="Optional — leave empty to run indefinitely."
            />
          </div>

          <Textarea
            label="Notes"
            value={notes}
            onChange={(event) => setNotes(event.target.value)}
            placeholder="Netflix, salary, rent…"
            maxLength={200}
          />

          <button type="submit" className="sr-only">
            Save
          </button>
        </form>
      </Overlay>

      <ConfirmOverlay
        open={confirmDelete}
        busy={busy}
        tone="danger"
        onClose={() => setConfirmDelete(false)}
        onConfirm={() => void remove()}
        title="Delete this rule?"
        confirmLabel="Delete rule"
        message="Past occurrences already recorded in your ledger stay put — only the schedule stops."
      />
    </>
  );
}

/**
 * Recurring rules.
 *
 * The schedule that will produce future transactions: what repeats, how often,
 * and when it next runs. Each row is explicit about its status so a paused rule
 * can never be mistaken for one that is about to charge you (§21).
 */
import { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  ArrowDownRight,
  ArrowUpRight,
  CalendarClock,
  Pause,
  Play,
  Plus,
  Repeat,
} from "lucide-react";
import {
  Alert,
  Badge,
  Button,
  Card,
  EmptyState,
  LinkButton,
  PageHeader,
  SegmentedControl,
} from "../../components/ui";
import type { LocalRecurring } from "../../db/types";
import { formatMoney, formatRelativeDay } from "../../design/format";
import { categoryIcon } from "../../design/icons";
import { useLocalData } from "../analytics/useLocalData";
import { deleteRecurring, updateRecurring } from "../../db/repositories";

type Filter = "all" | "expense" | "income" | "paused";

const FREQUENCY_LABEL: Record<LocalRecurring["frequency"], string> = {
  daily: "Daily",
  weekly: "Weekly",
  monthly: "Monthly",
  yearly: "Yearly",
};

export function RecurringPage() {
  const { lookups, dataset, ready } = useLocalData();
  const navigate = useNavigate();
  const [filter, setFilter] = useState<Filter>("all");

  const rows = useMemo(() => {
    const ordered = [...dataset.recurring].sort((a, b) =>
      a.next_run_at.localeCompare(b.next_run_at),
    );
    if (filter === "all") return ordered;
    if (filter === "paused") return ordered.filter((row) => !row.enabled);
    return ordered.filter((row) => row.type === filter);
  }, [dataset.recurring, filter]);

  const activeCount = dataset.recurring.filter((row) => row.enabled).length;
  const pausedCount = dataset.recurring.length - activeCount;

  const monthlyOut = dataset.recurring
    .filter((row) => row.enabled && row.type === "expense" && row.frequency === "monthly")
    .reduce((sum, row) => sum + row.amount, 0);
  const monthlyIn = dataset.recurring
    .filter((row) => row.enabled && row.type === "income" && row.frequency === "monthly")
    .reduce((sum, row) => sum + row.amount, 0);

  const currency = lookups.dataset.baseCurrency;

  async function toggle(rule: LocalRecurring) {
    await updateRecurring(rule.id, { enabled: !rule.enabled });
  }

  return (
    <div className="space-y-4">
      <PageHeader
        title="Recurring"
        subtitle={`${activeCount} active${pausedCount > 0 ? ` · ${pausedCount} paused` : ""}`}
        actions={
          <Button
            variant="primary"
            size="sm"
            icon={<Plus className="h-4 w-4" />}
            onClick={() => navigate("/recurring/new")}
          >
            New rule
          </Button>
        }
        tabs={
          <div className="flex flex-wrap items-center gap-2">
            <SegmentedControl
              size="sm"
              options={[
                { id: "all", label: `All (${dataset.recurring.length})` },
                { id: "expense", label: "Bills", icon: <ArrowDownRight className="h-3.5 w-3.5" /> },
                { id: "income", label: "Income", icon: <ArrowUpRight className="h-3.5 w-3.5" /> },
                { id: "paused", label: `Paused (${pausedCount})` },
              ]}
              value={filter}
              onChange={setFilter}
              ariaLabel="Recurring filter"
            />
          </div>
        }
      />

      {dataset.recurring.length > 0 && (
        <Card>
          <div className="grid grid-cols-2 divide-x divide-line">
            <div className="px-4 py-3.5">
              <p className="text-xs font-medium tracking-wide text-muted uppercase">Monthly out</p>
              <p className="tabular mt-0.5 text-title font-semibold text-expense">
                {formatMoney(monthlyOut, currency)}
              </p>
            </div>
            <div className="px-4 py-3.5">
              <p className="text-xs font-medium tracking-wide text-muted uppercase">Monthly in</p>
              <p className="tabular mt-0.5 text-title font-semibold text-income">
                {formatMoney(monthlyIn, currency)}
              </p>
            </div>
          </div>
          <div className="border-t border-line px-4 py-2.5 text-xs text-muted">
            Recurring rules describe your schedule. Occurrences become transactions in your
            ledger as they come due, so nothing here inflates a report before it happens.
          </div>
        </Card>
      )}

      {ready && dataset.recurring.length === 0 ? (
        <Card>
          <EmptyState
            icon={<Repeat className="h-7 w-7" />}
            title="No recurring rules yet"
            description="Rent, subscriptions, salary — if it repeats, put it here and you'll always know what's committed before you spend. Entries land in your ledger as they come due."
            action={
              <Button variant="primary" icon={<Plus className="h-4 w-4" />} onClick={() => navigate("/recurring/new")}>
                Add a recurring rule
              </Button>
            }
            secondaryAction={<LinkButton to="/calendar">See the calendar</LinkButton>}
          />
        </Card>
      ) : rows.length === 0 ? (
        <Card>
          <EmptyState
            icon={<Repeat className="h-7 w-7" />}
            title="Nothing matches this filter"
            description="Switch to All to see every recurring rule you've set up."
            action={
              <Button variant="secondary" onClick={() => setFilter("all")}>
                Show all
              </Button>
            }
          />
        </Card>
      ) : (
        <div className="space-y-3">
          {rows.map((rule) => {
            const category = rule.category_id
              ? lookups.category.get(rule.category_id)
              : undefined;
            const Icon = categoryIcon(category?.icon ?? null, category?.name);
            const tone =
              rule.type === "income"
                ? "text-income"
                : rule.type === "expense"
                  ? "text-expense"
                  : "text-transfer";
            const sign = rule.type === "income" ? "+" : rule.type === "expense" ? "−" : "";
            const accountName = (id: string | null) =>
              id ? (lookups.account.get(id)?.name ?? "Unknown") : null;

            return (
              <Card key={rule.id} className={`p-4 ${rule.enabled ? "" : "opacity-70"}`}>
                <div className="flex items-start justify-between gap-3">
                  <button
                    type="button"
                    onClick={() => navigate(`/recurring/${rule.id}`)}
                    className="flex min-w-0 flex-1 items-center gap-3 text-left"
                  >
                    <span
                      aria-hidden="true"
                      className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                        rule.type === "income"
                          ? "bg-income-soft text-income"
                          : rule.type === "expense"
                            ? "bg-expense-soft text-expense"
                            : "bg-transfer-soft text-transfer"
                      }`}
                    >
                      <Icon className="h-4 w-4" />
                    </span>
                    <span className="min-w-0 flex-1">
                      <span className="flex items-center gap-1.5">
                        <span className="truncate text-sm font-semibold text-ink">
                          {rule.notes || category?.name || `${rule.type} rule`}
                        </span>
                        {!rule.enabled && <Badge tone="neutral">Paused</Badge>}
                      </span>
                      <span className="tabular block truncate text-xs text-muted">
                        {FREQUENCY_LABEL[rule.frequency]} ·{" "}
                        {rule.type === "transfer"
                          ? `${accountName(rule.from_account_id) ?? "?"} → ${accountName(rule.to_account_id) ?? "?"}`
                          : (accountName(rule.type === "income" ? rule.to_account_id : rule.from_account_id) ?? "No account")}
                        {rule.end_at && ` · until ${formatRelativeDay(rule.end_at)}`}
                      </span>
                    </span>
                  </button>

                  <span className="shrink-0 text-right">
                    <span className={`tabular block text-sm font-semibold ${tone}`}>
                      {sign}
                      {formatMoney(rule.amount, rule.currency)}
                    </span>
                    <span className="tabular block text-[11px] text-muted">
                      {formatRelativeDay(rule.next_run_at)}
                    </span>
                  </span>
                </div>

                <div className="mt-3 flex flex-wrap items-center justify-between gap-2 border-t border-line pt-3">
                  <span className="flex items-center gap-1.5 text-xs text-muted">
                    <CalendarClock aria-hidden="true" className="h-3.5 w-3.5" />
                    Next {formatRelativeDay(rule.next_run_at)}
                    {rule.last_run_at && ` · last ${formatRelativeDay(rule.last_run_at)}`}
                  </span>
                  <span className="flex items-center gap-1.5">
                    <Button
                      variant="ghost"
                      size="sm"
                      icon={rule.enabled ? <Pause className="h-3.5 w-3.5" /> : <Play className="h-3.5 w-3.5" />}
                      onClick={() => void toggle(rule)}
                    >
                      {rule.enabled ? "Pause" : "Resume"}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => navigate(`/recurring/${rule.id}/edit`)}
                    >
                      Edit
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => navigate(`/recurring/${rule.id}`)}
                    >
                      View
                    </Button>
                  </span>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      <Alert tone="info" title="How occurrence generation works">
        The backend generates entries from these rules on their due date and pushes them down on
        your next sync. Offline, the calendar still shows what's coming, and a rule you pause now
        stops before its next run.
      </Alert>
    </div>
  );
}

/** Kept for the delete path used by the detail screen. */
export { deleteRecurring };

