    try {
      await deleteBudget(budgetId);
      toast.push({ tone: "success", title: "Budget deleted" });
      navigate("/budgets");
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't delete budget",
        description: err instanceof Error ? err.message : undefined,
      });
    } finally {
      setBusy(false);
      setConfirmDelete(false);
    }
  }

