/**
 * Installment-plan editor.
 *
 * `/installments/new` and `/installments/:installmentId/edit`. The plan only
 * describes how a purchase is split; each part becomes a real transaction when
 * it is paid, so nothing is double-counted (§23).
 */
import { useEffect, useState, type FormEvent } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useLiveQuery } from "dexie-react-hooks";
import { db } from "../../db";
import {
  createInstallment,
  deleteInstallment,
  updateInstallment,
} from "../../db/repositories";
import type { LocalInstallment } from "../../db/types";
import {
  AmountInput,
  Button,
  ConfirmOverlay,
  Field,
  Input,
  Overlay,
  Select,
  Textarea,
  useToast,
} from "../../components/ui";
import { useLocalData } from "../analytics/useLocalData";

type Frequency = LocalInstallment["frequency"];

const FREQUENCIES: { id: Frequency; label: string }[] = [
  { id: "weekly", label: "Weekly" },
  { id: "monthly", label: "Monthly" },
  { id: "quarterly", label: "Quarterly" },
];

export function InstallmentEditor() {
  const navigate = useNavigate();
  const toast = useToast();
  const { installmentId } = useParams<{ installmentId: string }>();
  const editing = installmentId !== undefined;
  const { lookups, ready } = useLocalData();

  const plan = useLiveQuery(
    async () => (installmentId ? db.installments.get(installmentId) : undefined),
    [installmentId],
    undefined,
  );

  const [total, setTotal] = useState(0);
  const [parts, setParts] = useState(6);
  const [currency, setCurrency] = useState(lookups.dataset.baseCurrency);
  const [fromAccount, setFromAccount] = useState("");
  const [categoryId, setCategoryId] = useState("");
  const [startDate, setStartDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [frequency, setFrequency] = useState<Frequency>("monthly");
  const [notes, setNotes] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);

  useEffect(() => {
    if (!editing || !plan) return;
    setTotal(plan.total_amount);
    setParts(plan.parts_count);
    setCurrency(plan.currency);
    setFromAccount(plan.from_account_id ?? "");
    setCategoryId(plan.category_id ?? "");
    setStartDate(plan.start_date.slice(0, 10));
    setFrequency(plan.frequency);
    setNotes(plan.notes);
  }, [editing, plan]);

  const accounts = [...lookups.dataset.accounts]
    .filter((row) => !row.archived)
    .sort((a, b) => a.name.localeCompare(b.name));
  const categories = [...lookups.dataset.categories]
    .filter((row) => row.type === "expense")
    .sort((a, b) => a.name.localeCompare(b.name));

  const partAmount = parts > 0 && total > 0 ? Math.floor((total / parts) * 100) / 100 : 0;

  async function save() {
    setError(null);
    if (!total || total <= 0) {
      setError("Enter the full purchase amount.");
      return;
    }
    if (parts < 2 || parts > 60) {
      setError("Choose between 2 and 60 parts.");
      return;
    }
    if (!fromAccount) {
      setError("Choose the account making the payments.");
      return;
    }
    setBusy(true);
    try {
      const payload = {
        total_amount: total,
        parts_count: parts,
        currency,
        from_account_id: fromAccount,
        category_id: categoryId || null,
        start_date: startDate,
        frequency,
        notes,
      };
      if (editing && plan) {
        await updateInstallment(plan.id, payload);
        toast.push({ tone: "success", title: "Installment plan updated" });
      } else {
        await createInstallment(payload);
        toast.push({
          tone: "success",
          title: "Installment plan created",
          description: "Each due part appears in the calendar as it comes.",
        });
      }
      navigate("/installments");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't save that plan.");
    } finally {
      setBusy(false);
    }
  }

  function submit(event: FormEvent) {
    event.preventDefault();
    void save();
  }

  async function remove() {
    if (!installmentId) return;
    setBusy(true);
    try {
      await deleteInstallment(installmentId);
      toast.push({ tone: "success", title: "Installment plan deleted" });
      navigate("/installments");
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't delete plan",
        description: err instanceof Error ? err.message : undefined,
      });
    } finally {
      setBusy(false);
      setConfirmDelete(false);
    }
  }

  if (editing && !plan && ready) {
    return (
      <Overlay
        open
        onClose={() => navigate("/installments")}
        title="Plan not found"
        variant="sheet"
        size="sm"
        footer={<Button variant="primary" onClick={() => navigate("/installments")}>Back</Button>}
      >
        <p className="text-sm text-muted">It may have been deleted on another device.</p>
      </Overlay>
    );
  }

  return (
    <>
      <Overlay
        open
        onClose={() => navigate("/installments")}
        title={editing ? "Edit installment plan" : "New installment plan"}
        description="Split a purchase into equal parts across time."
        variant="sheet"
        size="md"
        footer={
          <>
            {editing && <Button variant="danger" onClick={() => setConfirmDelete(true)}>Delete</Button>}
            <Button variant="ghost" onClick={() => navigate("/installments")}>Cancel</Button>
            <Button variant="primary" loading={busy} onClick={() => void save()}>
              {editing ? "Save changes" : "Create plan"}
            </Button>
          </>
        }
      >
        <form onSubmit={submit} className="space-y-4" noValidate>
          {error && (
            <p role="alert" className="rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
              {error}
            </p>
          )}

          <Field label="Purchase amount" htmlFor="ins-total" required>
            <AmountInput
              id="ins-total"
              value={total}
              onChange={setTotal}
              currency={currency}
              tone="expense"
              autoFocus={!editing}
            />
          </Field>

          <div className="grid gap-3 sm:grid-cols-2">
            <Input
              label="Number of parts"
              type="number"
              min={2}
              max={60}
              value={parts}
              onChange={(event) => setParts(Number(event.target.value))}
              required
              hint={partAmount > 0 ? `${partAmount.toFixed(2)} ${currency} per part.` : undefined}
            />
            <Select label="Currency" value={currency} onChange={(event) => setCurrency(event.target.value)}>
              {[lookups.dataset.baseCurrency, "USD", "EUR", "GBP", "PHP"].filter(
                (code, index, all) => all.indexOf(code) === index,
              ).map((code) => (
                <option key={code} value={code}>
                  {code}
                </option>
              ))}
            </Select>
          </div>

          <Select
            label="Pay from"
            value={fromAccount}
            onChange={(event) => setFromAccount(event.target.value)}
            required
          >
            <option value="">Select account</option>
            {accounts.map((row) => (
              <option key={row.id} value={row.id}>
                {row.name}
              </option>
            ))}
          </Select>

          <Select label="Category" value={categoryId} onChange={(event) => setCategoryId(event.target.value)}>
            <option value="">Uncategorised</option>
            {categories.map((row) => (
              <option key={row.id} value={row.id}>
                {row.name}
              </option>
            ))}
          </Select>

          <div className="grid gap-3 sm:grid-cols-2">
            <Input
              label="First payment"
              type="date"
              value={startDate}
              onChange={(event) => setStartDate(event.target.value)}
              required
            />
            <Select label="Frequency" value={frequency} onChange={(event) => setFrequency(event.target.value as Frequency)}>
              {FREQUENCIES.map((option) => (
                <option key={option.id} value={option.id}>
                  {option.label}
                </option>
              ))}
            </Select>
          </div>

          <Textarea
            label="Notes"
            value={notes}
            onChange={(event) => setNotes(event.target.value)}
            placeholder="What this purchase was"
            maxLength={200}
          />

          <button type="submit" className="sr-only">
            Save
          </button>
        </form>
      </Overlay>

      <ConfirmOverlay
        open={confirmDelete}
        busy={busy}
        tone="danger"
        onClose={() => setConfirmDelete(false)}
        onConfirm={() => void remove()}
        title="Delete this plan?"
        confirmLabel="Delete plan"
        message="Payments already recorded stay in your ledger; only the schedule goes away."
      />
    </>
  );
}

/**
 * Installment plans.
 *
 * A plan shows what was bought, how many parts are left, and how much is still
 * to pay. The schedule and the paid markers both come from the ledger, so an
 * offline-recorded payment is reflected the moment it is entered (§23).
 */
import { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { CalendarClock, Layers, Plus, Receipt } from "lucide-react";
import {
  Alert,
  Button,
  Card,
  EmptyState,
  LinkButton,
  PageHeader,
  ProgressBar,
} from "../../components/ui";
import type { LocalInstallment } from "../../db/types";
import { formatMoney, formatPercent, formatRelativeDay } from "../../design/format";
import { useLocalData } from "../analytics/useLocalData";
import { installmentProgress, type InstallmentProgress } from "../analytics/engine";

export function InstallmentsPage() {
  const { lookups, dataset, ready } = useLocalData();
  const navigate = useNavigate();
  const [selected, setSelected] = useState<string | null>(null);

  const plans = useMemo(
    () => installmentProgress(dataset.installments, dataset.transactions, lookups),
    [dataset.installments, dataset.transactions, lookups],
  );

  const currency = lookups.dataset.baseCurrency;
  const totalRemaining = plans.reduce(
    (sum, item) => sum + Math.max(0, item.plan.total_amount - item.paidAmount),
    0,
  );
  const paidTotal = plans.reduce((sum, item) => sum + item.paidAmount, 0);
  const dueSoon = plans.filter(
    (item) => item.nextDueDate !== null && daysOut(item.nextDueDate) <= 7,
  ).length;

  return (
    <div className="space-y-4">
      <PageHeader
        title="Installments"
        subtitle={
          plans.length > 0
            ? `${plans.length} active plan${plans.length === 1 ? "" : "s"} · ${dueSoon} due within a week`
            : "Split a purchase across time"
        }
        actions={
          <Button
            variant="primary"
            size="sm"
            icon={<Plus className="h-4 w-4" />}
            onClick={() => navigate("/installments/new")}
          >
            New plan
          </Button>
        }
      />

      {plans.length > 0 && (
        <Card>
          <div className="flex flex-wrap items-end justify-between gap-4 px-4 py-4">
            <div>
              <p className="text-xs font-medium tracking-wide text-muted uppercase">
                Still to pay
              </p>
              <p className="tabular mt-0.5 text-display-sm font-semibold text-ink">
                {formatMoney(totalRemaining, currency)}
              </p>
              <p className="mt-1 text-xs text-muted">
                {formatMoney(paidTotal, currency)} already settled
              </p>
            </div>
            <div className="grid grid-cols-2 gap-x-8">
              <div>
                <p className="text-xs text-muted">Plans</p>
                <p className="tabular text-title font-semibold text-ink">{plans.length}</p>
              </div>
              <div>
                <p className="text-xs text-muted">Due soon</p>
                <p
                  className={`tabular text-title font-semibold ${dueSoon > 0 ? "text-warning" : "text-ink"}`}
                >
                  {dueSoon}
                </p>
              </div>
            </div>
          </div>
        </Card>
      )}

      {ready && dataset.installments.length === 0 ? (
        <Card>
          <EmptyState
            icon={<Layers className="h-7 w-7" />}
            title="No installment plans yet"
            description="Bought something on a payment plan? Record it once and FinTrack tracks every part — how many are left, what each costs, and when the next one is due — all computed from your own ledger."
            action={
              <Button
                variant="primary"
                icon={<Plus className="h-4 w-4" />}
                onClick={() => navigate("/installments/new")}
              >
                Create a plan
              </Button>
            }
            secondaryAction={<LinkButton to="/calendar">Open the calendar</LinkButton>}
          />
        </Card>
      ) : (
        <div className="space-y-3">
          {plans.map((item) => (
            <PlanCard
              key={item.plan.id}
              item={item}
              expanded={selected === item.plan.id}
              onToggle={() => setSelected(selected === item.plan.id ? null : item.plan.id)}
              onEdit={() => navigate(`/installments/${item.plan.id}/edit`)}
            />
          ))}
        </div>
      )}

      <Alert tone="info" title="Payments are ordinary transactions">
        Marking a part as paid happens by recording the transaction itself. That keeps spending
        reports, account balances and this schedule telling the same story — even when the payment
        was entered on a phone with no connection.
      </Alert>
    </div>
  );
}

function daysOut(date: Date): number {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return Math.round((date.getTime() - today.getTime()) / 86_400_000);
}

function PlanCard({
  item,
  expanded,
  onToggle,
  onEdit,
}: {
  item: InstallmentProgress;
  expanded: boolean;
  onToggle: () => void;
  onEdit: () => void;
}) {
  const { plan } = item;
  const remaining = Math.max(0, plan.total_amount - item.paidAmount);
  const done = item.remainingParts === 0;

  return (
    <Card className="p-4">
      <div className="flex items-start justify-between gap-3">
        <button type="button" onClick={onToggle} aria-expanded={expanded} className="min-w-0 flex-1 text-left">
          <p className="flex items-center gap-2 text-sm font-semibold text-ink">
            <Receipt aria-hidden="true" className="h-4 w-4 shrink-0 text-primary" />
            <span className="truncate">{plan.notes || "Installment plan"}</span>
          </p>
          <p className="tabular mt-0.5 text-xs text-muted">
            {plan.currency} · {item.paidParts} of {plan.parts_count} parts ·{" "}
            {formatMoney(item.partAmount, plan.currency)} each
          </p>
        </button>
        <button
          type="button"
          onClick={onEdit}
          className="shrink-0 text-xs font-medium text-primary hover:underline"
        >
          Edit
        </button>
      </div>

      <div className="mt-3 flex items-baseline justify-between gap-3">
        <span className="tabular text-title font-semibold text-ink">
          {formatMoney(remaining, plan.currency)}
        </span>
        <span className="tabular text-xs text-muted">
          {done ? "Fully paid" : `${formatPercent(item.percent)} settled`}
        </span>
      </div>

      <ProgressBar
        value={Math.min(100, item.percent)}
        size="sm"
        tone={done ? "income" : "primary"}
        className="mt-2"
        label={`${plan.notes || "Installment"} repayment progress`}
      />

      {!done && item.nextDueDate && (
        <p
          className={`mt-2 flex items-center gap-1.5 text-xs ${
            daysOut(item.nextDueDate) <= 7 ? "text-warning" : "text-muted"
          }`}
        >
          <CalendarClock aria-hidden="true" className="h-3.5 w-3.5" />
          Next part {formatRelativeDay(item.nextDueDate)}
        </p>
      )}

      {expanded && (
        <ul className="mt-3 grid gap-1 border-t border-line pt-3 sm:grid-cols-2">
          {item.schedule.map((part) => (
            <li
              key={part.index}
              className={`flex items-center justify-between gap-2 rounded-lg px-2 py-1.5 text-xs ${
                part.paid ? "bg-income-soft text-income" : "bg-surface-sunken text-muted"
              }`}
            >
              <span>
                Part {part.index + 1} · {formatRelativeDay(part.date)}
              </span>
              <span className="tabular font-medium">
                {formatMoney(part.amount, plan.currency)}
              </span>
            </li>
          ))}
        </ul>
      )}
    </Card>
  );
}

/**
 * Installment-plan detail — `/installments/:installmentId`.
 *
 * The full part-by-part schedule, derived from the plan plus the payments that
 * actually exist in the ledger, so it is correct offline.
 */
import { useMemo, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { ArrowLeft, CalendarClock, Layers, Pencil, Receipt, Trash2 } from "lucide-react";
import {
  Alert,
  Badge,
  Button,
  Card,
  CardHeader,
  ConfirmOverlay,
  DetailRow,
  Divider,
  EmptyState,
  IconButton,
