  const item = useMemo(
    () =>
      installmentProgress(
        dataset.installments.filter((row) => row.id === installmentId),
        dataset.transactions,
        lookups,
      )[0] ?? null,
    [dataset.installments, dataset.transactions, lookups, installmentId],
