/**
 * Settings shell.
 *
 * `/settings` is a section index; every sub-route renders inside this layout so
 * the navigation and the back path stay put while the panel changes. On narrow
 * screens the section list becomes a horizontal scroller above the content.
 */
import { NavLink, Outlet, useLocation } from "react-router-dom";
import {
  Bell,
  CircleDollarSign,
  Coins,
  Database,
  Info,
  Monitor,
  Palette,
  ScrollText,
  ShieldCheck,
  SlidersHorizontal,
  Smartphone,
  UserRound,
} from "lucide-react";
import { PageHeader } from "../../components/ui";

interface Section {
  to: string;
  label: string;
  hint: string;
  icon: typeof UserRound;
  end?: boolean;
}

const SECTIONS: Section[] = [
  { to: "/settings", label: "Overview", hint: "Where everything lives", icon: SlidersHorizontal, end: true },
  { to: "/settings/profile", label: "Profile", hint: "Name, email, currency", icon: UserRound },
  { to: "/settings/security", label: "Security", hint: "Password and two-factor", icon: ShieldCheck },
  { to: "/settings/appearance", label: "Appearance", hint: "Theme, density, motion", icon: Palette },
  { to: "/settings/notifications", label: "Notifications", hint: "What alerts you get", icon: Bell },
  { to: "/settings/currency", label: "Currency", hint: "Base currency and rates", icon: Coins },
  { to: "/settings/financial", label: "Financial", hint: "Month start, formatting", icon: CircleDollarSign },
  { to: "/settings/sync", label: "Sync", hint: "Queue, conflicts, status", icon: Monitor },
  { to: "/settings/data", label: "Data", hint: "Export, import, reset", icon: Database },
  { to: "/settings/devices", label: "Devices", hint: "Sessions on your account", icon: Smartphone },
  { to: "/settings/about", label: "About", hint: "Version and licences", icon: Info },
];

export function SettingsPage() {
  const { pathname } = useLocation();
  const current = SECTIONS.find((section) => section.to === pathname) ?? SECTIONS[0];

  return (
    <div className="space-y-4">
      <PageHeader
        title="Settings"
        subtitle={pathname === "/settings" ? "Everything you can change here" : current.hint}
      />

      <div className="grid gap-4 lg:grid-cols-[15rem_minmax(0,1fr)]">
        <nav
          aria-label="Settings sections"
          className="scroll-area -mx-1 flex gap-1 overflow-x-auto px-1 lg:mx-0 lg:flex-col lg:overflow-visible lg:px-0"
        >
          {SECTIONS.map((section) => (
            <NavLink
              key={section.to}
              to={section.to}
              end={section.end}
              className={({ isActive }) =>
                `flex shrink-0 items-center gap-2.5 rounded-xl px-3 py-2 text-sm font-medium transition-colors lg:w-full ${
                  isActive
                    ? "bg-primary-soft-bg text-primary"
                    : "text-ink-soft hover:bg-surface-sunken hover:text-ink"
                }`
              }
            >
              <section.icon aria-hidden="true" className="h-4 w-4 shrink-0" />
              <span className="whitespace-nowrap">{section.label}</span>
            </NavLink>
          ))}
        </nav>

        <div className="min-w-0">
          <Outlet />
        </div>
      </div>
    </div>
  );
}

/**
 * Small shared pieces for the settings panels: a titled card and a switch row.
 *
 * Keeping them here means every section reads the same and no panel invents its
 * own toggle markup (and therefore its own focus/keyboard behaviour).
 */
import type { ReactNode } from "react";

export function Panel({
  title,
  description,
  children,
  footer,
}: {
  title: string;
  description?: string;
  children: ReactNode;
  footer?: ReactNode;
}) {
  return (
    <section className="rounded-2xl border border-line bg-surface">
      <header className="border-b border-line px-4 py-3">
        <h2 className="text-sm font-semibold text-ink">{title}</h2>
        {description && <p className="mt-0.5 text-xs text-muted">{description}</p>}
      </header>
      <div className="px-4 py-3">{children}</div>
      {footer && (
        <footer className="flex flex-wrap items-center justify-end gap-2 border-t border-line px-4 py-3">
          {footer}
        </footer>
      )}
    </section>
  );
}

export function ToggleRow({
  label,
  description,
  checked,
  onChange,
  disabled,
  id,
}: {
  label: string;
  description?: string;
  checked: boolean;
  onChange: (next: boolean) => void;
  disabled?: boolean;
  id: string;
}) {
  return (
    <div className="flex items-start justify-between gap-4 py-2">
      <div className="min-w-0">
        <label htmlFor={id} className="block text-sm font-medium text-ink">
          {label}
        </label>
        {description && <p className="mt-0.5 text-xs text-muted">{description}</p>}
      </div>
      <button
        type="button"
        id={id}
        role="switch"
        aria-checked={checked}
        aria-label={label}
        disabled={disabled}
        onClick={() => onChange(!checked)}
        className={`relative mt-0.5 h-6 w-11 shrink-0 rounded-full transition-colors disabled:opacity-50 ${
          checked ? "bg-primary" : "bg-line-strong"
        }`}
      >
        <span
          aria-hidden="true"
          className={`absolute top-0.5 left-0.5 h-5 w-5 rounded-full bg-surface shadow transition-transform ${
            checked ? "translate-x-5" : ""
          }`}
        />
      </button>
    </div>
  );
}

/**
 * `/settings/profile` — name, email, preferred currency.
 *
 * Written straight to `PATCH /auth/profile/`; the local copy in AuthContext is
 * refreshed from the response so the header picks the new name up immediately.
 */
import { useEffect, useState, type FormEvent } from "react";
import { useNavigate } from "react-router-dom";
import { Save, Trash2 } from "lucide-react";
import { ApiError, apiFetch } from "../../api/client";
import { useAuth, type UserProfile } from "../../auth/AuthContext";
import { Button, ConfirmOverlay, Input, Select, useToast } from "../../components/ui";
import { CURRENCIES } from "../../design/format";
import { usePreferences } from "./preferences";
import { Panel } from "./Panel";

export function ProfileSection() {
  const { profile, refreshProfile, logout } = useAuth();
  const { preferences, update } = usePreferences();
  const toast = useToast();
  const navigate = useNavigate();

  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [currency, setCurrency] = useState(preferences.baseCurrency);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState(false);

  useEffect(() => {
    if (!profile) return;
    setFirstName(profile.first_name);
    setLastName(profile.last_name);
    setCurrency(profile.preferred_currency);
  }, [profile]);

  async function save(event: FormEvent) {
    event.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const updated = await apiFetch<UserProfile>("/auth/profile/", {
        method: "PATCH",
        body: JSON.stringify({
          first_name: firstName.trim(),
          last_name: lastName.trim(),
          preferred_currency: currency,
        }),
      });
      profile && (await refreshProfile());
      // Keep the local reporting currency in step with the server profile.
      if (currency !== preferences.baseCurrency) await update({ baseCurrency: currency });
      toast.push({
        tone: "success",
        title: "Profile updated",
        description: updated.email,
      });
    } catch (err) {
      setError(
        err instanceof ApiError ? err.message : "Couldn't save your profile right now.",
      );
    } finally {
      setBusy(false);
    }
  }

  async function deleteAccount() {
    setBusy(true);
    try {
      await apiFetch("/auth/profile/", { method: "DELETE" });
      await logout();
      navigate("/login", { replace: true });
      toast.push({ tone: "success", title: "Account deleted" });
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't delete account",
        description: err instanceof ApiError ? err.message : undefined,
      });
      setBusy(false);
      setConfirmDelete(false);
    }
  }

  return (
    <div className="space-y-4">
      <Panel
        title="Your details"
        description="Shown on this device and on every device you sign in from."
        footer={
          <Button variant="primary" size="sm" icon={<Save className="h-4 w-4" />} loading={busy} onClick={() => void save(new Event("submit") as unknown as FormEvent)}>
            Save
          </Button>
        }
      >
        <form onSubmit={save} className="space-y-3" noValidate>
          {error && (
            <p role="alert" className="rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
              {error}
            </p>
          )}
          <div className="grid gap-3 sm:grid-cols-2">
            <Input
              label="First name"
              value={firstName}
              onChange={(event) => setFirstName(event.target.value)}
              autoComplete="given-name"
              maxLength={60}
            />
            <Input
              label="Last name"
              value={lastName}
              onChange={(event) => setLastName(event.target.value)}
              autoComplete="family-name"
              maxLength={60}
            />
          </div>
          <Input
            label="Email"
            value={profile?.email ?? ""}
            readOnly
            hint="Email changes go through verification — contact support to change it."
          />
          <Select
            label="Preferred currency"
            value={currency}
            onChange={(event) => setCurrency(event.target.value)}
            hint="Used for your profile and as the starting point for this device's reports."
          >
            {CURRENCIES.map((code) => (
              <option key={code} value={code}>
                {code}
              </option>
            ))}
          </Select>
          <button type="submit" className="sr-only">
            Save profile
          </button>
        </form>
      </Panel>

      <Panel
        title="Danger zone"
        description="Deleting your account removes every transaction, account and goal from the server."
      >
        <Button
          variant="danger"
          size="sm"
          icon={<Trash2 className="h-4 w-4" />}
          onClick={() => setConfirmDelete(true)}
        >
          Delete account
        </Button>
      </Panel>

      <ConfirmOverlay
        open={confirmDelete}
        busy={busy}
        tone="danger"
        onClose={() => setConfirmDelete(false)}
        onConfirm={() => void deleteAccount()}
        title="Delete your FinTrack account?"
        confirmLabel="Delete everything"
        message="This erases all accounts, transactions, budgets and goals on the server. It cannot be undone."
      />
    </div>
  );
}

