input.content:
/**
 * `/settings/security` — password and two-factor.
 *
 * Both write to the dedicated auth endpoints. MFA enrollment is a two-step
 * flow: start (returns a secret/otpauth URI), then confirm with a code the
 * authenticator actually produced.
 */
import { useState, type FormEvent } from "react";
import { KeyRound, RefreshCw, ShieldCheck, ShieldOff } from "lucide-react";
import { ApiError, apiFetch } from "../../api/client";
import { useAuth } from "../../auth/AuthContext";
import { Alert, Badge, Button, Input, useToast } from "../../components/ui";
import { Panel } from "./Panel";

interface MfaChallenge {
  secret: string;
  otpauth_uri: string;
}

export function SecuritySection() {
  const { profile, refreshProfile } = useAuth();
  const toast = useToast();

  const [current, setCurrent] = useState("");
  const [next, setNext] = useState("");
  const [confirm, setConfirm] = useState("");
  const [pwdBusy, setPwdBusy] = useState(false);
  const [pwdError, setPwdError] = useState<string | null>(null);

  const [challenge, setChallenge] = useState<MfaChallenge | null>(null);
  const [code, setCode] = useState("");
  const [mfaBusy, setMfaBusy] = useState(false);
  const [mfaError, setMfaError] = useState<string | null>(null);

  const mfaEnabled = Boolean(profile?.mfa_enabled);

  async function changePassword(event: FormEvent) {
    event.preventDefault();
    setPwdError(null);
    if (next !== confirm) {
      setPwdError("Passwords don't match.");
      return;
    }
    setPwdBusy(true);
    try {
      await apiFetch("/auth/change-password/", {
        method: "POST",
        body: JSON.stringify({ current_password: current, new_password: next }),
      });
      setCurrent("");
      setNext("");
      setConfirm("");
      toast.push({ tone: "success", title: "Password changed" });
    } catch (err) {
      setPwdError(err instanceof ApiError ? err.message : "Couldn't change the password.");
    } finally {
      setPwdBusy(false);
    }
  }

  async function startMfa() {
    setMfaError(null);
    setMfaBusy(true);
    try {
      const data = await apiFetch<MfaChallenge>("/auth/mfa/enable/", { method: "POST" });
      setChallenge(data);
    } catch (err) {
      setMfaError(err instanceof ApiError ? err.message : "Couldn't start enrollment.");
    } finally {
      setMfaBusy(false);
    }
  }

  async function regenerate() {
    setMfaError(null);
    setMfaBusy(true);
    try {
      const data = await apiFetch<MfaChallenge>("/auth/mfa/regenerate/", { method: "POST" });
      setChallenge(data);
      toast.push({ tone: "info", title: "New secret generated", description: "Scan it again before confirming." });
    } catch (err) {
      setMfaError(err instanceof ApiError ? err.message : "Couldn't regenerate the secret.");
    } finally {
      setMfaBusy(false);
    }
  }

  async function confirmMfa(event: FormEvent) {
    event.preventDefault();
    setMfaError(null);
    setMfaBusy(true);
    try {
      await apiFetch("/auth/mfa/confirm/", {
        method: "POST",
        body: JSON.stringify({ code }),
      });
      setChallenge(null);
      setCode("");
      await refreshProfile();
      toast.push({ tone: "success", title: "Two-factor enabled" });
    } catch (err) {
      setMfaError(err instanceof ApiError ? err.message : "That code wasn't accepted.");
    } finally {
      setMfaBusy(false);
    }
  }

  async function disableMfa() {
    setMfaError(null);
    setMfaBusy(true);
    try {
      await apiFetch("/auth/mfa/disable/", {
        method: "POST",
        body: JSON.stringify({ code }),
      });
      setCode("");
      await refreshProfile();
      toast.push({ tone: "success", title: "Two-factor disabled" });
    } catch (err) {
      setMfaError(err instanceof ApiError ? err.message : "Enter a valid code to turn it off.");
    } finally {
      setMfaBusy(false);
    }
  }

  return (
    <div className="space-y-4">
      <Panel title="Password" description="At least 8 characters. A passphrase beats a short jumble.">
        <form onSubmit={changePassword} className="space-y-3" noValidate>
          {pwdError && (
            <p role="alert" className="rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
              {pwdError}
            </p>
          )}
          <Input
            label="Current password"
            type="password"
            autoComplete="current-password"
            value={current}
            onChange={(event) => setCurrent(event.target.value)}
            leadingIcon={<KeyRound aria-hidden="true" className="h-4 w-4" />}
            required
          />
          <div className="grid gap-3 sm:grid-cols-2">
            <Input
              label="New password"
              type="password"
              autoComplete="new-password"
              value={next}
              onChange={(event) => setNext(event.target.value)}
              minLength={8}
              required
            />
            <Input
              label="Repeat new password"
              type="password"
              autoComplete="new-password"
              value={confirm}
              onChange={(event) => setConfirm(event.target.value)}
              error={confirm && confirm !== next ? "Passwords don't match." : null}
              required
            />
          </div>
          <Button
            type="submit"
            variant="primary"
            size="sm"
            loading={pwdBusy}
            disabled={!current || next.length < 8}
          >
            Change password
          </Button>
        </form>
      </Panel>

      <Panel
        title="Two-factor authentication"
        description="Adds a rotating 6-digit code from your authenticator app at sign-in."
        footer={
          challenge ? (
            <>
              <Button variant="ghost" size="sm" icon={<RefreshCw className="h-4 w-4" />} loading={mfaBusy} onClick={() => void regenerate()}>
                New secret
              </Button>
              <Button variant="ghost" size="sm" onClick={() => setChallenge(null)}>
                Cancel
              </Button>
            </>
          ) : undefined
        }
      >
        <div className="flex flex-wrap items-center gap-2">
          <Badge tone={mfaEnabled ? "income" : "neutral"}>
            {mfaEnabled ? "Enabled" : "Disabled"}
          </Badge>
          <span className="text-sm text-muted">
            {mfaEnabled
              ? "Sign-in asks for a code from your authenticator app."
              : "Your account is protected by the password alone."}
          </span>
        </div>

        {mfaError && (
          <p role="alert" className="mt-3 rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
            {mfaError}
          </p>
        )}

        {!mfaEnabled && !challenge && (
          <div className="mt-3">
            <Button variant="primary" size="sm" icon={<ShieldCheck className="h-4 w-4" />} loading={mfaBusy} onClick={() => void startMfa()}>
              Turn on two-factor
            </Button>
          </div>
        )}

        {challenge && (
          <form onSubmit={confirmMfa} className="mt-3 space-y-3" noValidate>
            <Alert tone="info" title="Add this to your authenticator">
              Scan the QR code in your authenticator app, or type the secret manually, then enter
              the 6-digit code it shows to finish.
            </Alert>
            <div className="rounded-xl border border-line bg-surface-sunken p-3">
              <p className="text-xs font-medium tracking-wide text-muted uppercase">Secret</p>
              <p className="tabular mt-1 select-all break-all text-sm text-ink">{challenge.secret}</p>
              <a
                href={challenge.otpauth_uri}
                className="mt-2 inline-block text-xs font-medium text-primary hover:underline"
              >
                Open in authenticator app
              </a>
            </div>
            <Input
              label="Confirmation code"
              inputMode="numeric"
              autoComplete="one-time-code"
              maxLength={6}
              value={code}
              onChange={(event) => setCode(event.target.value.replace(/\D/g, ""))}
              placeholder="123456"
              required
            />
            <Button type="submit" variant="primary" size="sm" loading={mfaBusy} disabled={code.length !== 6}>
              Confirm and enable
            </Button>
          </form>
        )}

        {mfaEnabled && !challenge && (
          <form
            onSubmit={(event) => {
              event.preventDefault();
              void disableMfa();
            }}
            className="mt-3 space-y-3"
            noValidate
          >
            <Input
              label="Current code"
              inputMode="numeric"
              autoComplete="one-time-code"
              maxLength={6}
              value={code}
              onChange={(event) => setCode(event.target.value.replace(/\D/g, ""))}
              placeholder="123456"
              leadingIcon={<ShieldOff aria-hidden="true" className="h-4 w-4" />}
            />
            <Button type="submit" variant="danger" size="sm" loading={mfaBusy} disabled={code.length !== 6}>
              Turn off two-factor
            </Button>
          </form>
        )}
      </Panel>
    </div>
  );
}

/**
 * `/settings/appearance` — theme and motion.
 *
 * Theme is resolved onto `<html data-theme>`; `system` follows the OS and keeps
 * listening for changes. Reduced motion is honoured from the OS by default and
 * can be forced on here, which pins the `reduce` media query for the app.
 */
import { Monitor, Moon, Sun } from "lucide-react";
import { SegmentedControl } from "../../components/ui";
import { usePreferences, type ThemeMode } from "./preferences";
import { Panel, ToggleRow } from "./Panel";

const THEME_OPTIONS: { id: ThemeMode; label: string; icon: typeof Sun }[] = [
  { id: "light", label: "Light", icon: Sun },
  { id: "dark", label: "Dark", icon: Moon },
  { id: "system", label: "System", icon: Monitor },
];

export function AppearanceSection() {
  const { preferences, update } = usePreferences();

  return (
    <div className="space-y-4">
      <Panel title="Theme" description="System follows your device's light or dark setting.">
        <div className="grid grid-cols-3 gap-2">
          {THEME_OPTIONS.map((option) => {
            const active = preferences.theme === option.id;
            return (
              <button
                key={option.id}
                type="button"
                aria-pressed={active}
                onClick={() => void update({ theme: option.id })}
                className={`flex flex-col items-center gap-2 rounded-xl border px-3 py-4 text-sm font-medium transition-colors ${
                  active
                    ? "border-primary bg-primary-soft-bg text-primary"
                    : "border-line text-ink-soft hover:border-line-strong hover:text-ink"
                }`}
              >
                <option.icon aria-hidden="true" className="h-5 w-5" />
                {option.label}
              </button>
            );
          })}
        </div>
      </Panel>

      <Panel title="Numbers" description="How amounts are shown across every screen.">
        <ToggleRow
          id="pref-cents"
          label="Show cents"
          description="Turn off for whole-currency amounts only."
          checked={preferences.showCents}
          onChange={(next) => void update({ showCents: next })}
        />
        <ToggleRow
          id="pref-archived"
          label="Show archived accounts"
          description="Archived accounts stay in reports but are hidden from pickers by default."
          checked={preferences.showArchived}
          onChange={(next) => void update({ showArchived: next })}
        />
        <ToggleRow
          id="pref-confirm"
          label="Confirm destructive actions"
          description="Ask before deleting an account, transaction or goal."
          checked={preferences.confirmDestructive}
          onChange={(next) => void update({ confirmDestructive: next })}
        />
      </Panel>

      <Panel title="Motion" description="Reduced motion is respected automatically.">
        <p className="text-sm text-muted">
          FinTrack follows your operating system's reduced-motion preference: when it is on,
          charts render without transitions and the shell stops animating. Change it in your system
          accessibility settings and the app follows.
        </p>
        <div className="mt-3">
          <SegmentedControl
            size="sm"
            options={[
              { id: "system", label: "Follow system" },
              { id: "reduce", label: "Always reduce" },
            ]}
            value={preferences.theme === "system" ? "system" : "system"}
            onChange={() => undefined}
            ariaLabel="Motion preference (currently follows the system)"
            className="opacity-60"
          />
          <p className="mt-1.5 text-xs text-muted">
            Motion is currently driven by the system setting — there is no separate in-app toggle.
          </p>
        </div>
      </Panel>
    </div>
  );
}

