/**
 * `/settings/currency` — base currency and stored exchange rates.
 *
 * The base currency is what every report and net-worth figure is expressed in;
 * rates are cached locally so conversions still happen offline.
 */
import { useEffect, useMemo, useState } from "react";
import { Coins, RefreshCw, Trash2 } from "lucide-react";
import { useLiveQuery } from "dexie-react-hooks";
import { ApiError, apiFetch } from "../../api/client";
import { db } from "../../db";
import { deleteExchangeRate } from "../../db/repositories";
import { Alert, Badge, Button, Card, EmptyState, Select, useToast } from "../../components/ui";
import { CURRENCIES, formatDateTime } from "../../design/format";
import { useLocalData } from "../analytics/useLocalData";
import { usePreferences } from "./preferences";
import { Panel } from "./Panel";

interface RatePayload {
  base: string;
  rates: Record<string, number>;
}

export function CurrencySection() {
  const { preferences, update } = usePreferences();
  const { dataset } = useLocalData();
  const toast = useToast();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const rates = useLiveQuery(
    async () => (await db.exchange_rates.toArray()).sort((a, b) => a.code.localeCompare(b.code)),
    [],
    undefined,
  );

  const used = useMemo(() => {
    const codes = new Set<string>([preferences.baseCurrency]);
    for (const account of dataset.accounts) codes.add(account.currency);
    for (const tx of dataset.transactions) codes.add(tx.currency);
    return [...codes].sort();
  }, [dataset.accounts, dataset.transactions, preferences.baseCurrency]);

  const lastRate = useLiveQuery(async () => {
    const rows = await db.exchange_rates.toArray();
    return rows.reduce<string | null>(
      (latest, row) => (!latest || row.updated_at > latest ? row.updated_at : latest),
      null,
    );
  }, []);

  useEffect(() => {
    if (rates === undefined) return;
    if (rates.length > 0) return;
    void (async () => {
      try {
        await apiFetch<RatePayload>("/fx/rates/");
      } catch {
        // Offline: the empty state explains what to do when a connection returns.
      }
    })();
  }, [rates]);

  async function refreshRates() {
    setBusy(true);
    setError(null);
    try {
      await apiFetch<RatePayload>("/fx/rates/");
      toast.push({ tone: "success", title: "Exchange rates updated" });
    } catch (err) {
      setError(
        err instanceof ApiError
          ? err.message
          : "Couldn't fetch rates. Existing rates stay usable offline.",
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="space-y-4">
      <Panel
        title="Base currency"
        description="Every total, report and budget is expressed in this currency."
      >
        <Select
          label="Report in"
          value={preferences.baseCurrency}
          onChange={(event) => void update({ baseCurrency: event.target.value })}
          hint="Amounts in other currencies are converted for display only — the original value is never overwritten."
        >
          {CURRENCIES.map((code) => (
            <option key={code} value={code}>
              {code}
            </option>
          ))}
        </Select>
        <div className="mt-3 flex flex-wrap gap-1.5">
          <span className="text-xs text-muted">In use:</span>
          {used.map((code) => (
            <Badge key={code} tone={code === preferences.baseCurrency ? "primary" : "neutral"}>
              {code}
            </Badge>
          ))}
        </div>
      </Panel>

      <Panel
        title="Exchange rates"
        description="Cached on this device so conversions work with no connection."
        footer={
          <Button
            variant="secondary"
            size="sm"
            icon={<RefreshCw className={`h-4 w-4 ${busy ? "animate-spin" : ""}`} />}
            loading={busy}
            onClick={() => void refreshRates()}
          >
            Refresh rates
          </Button>
        }
      >
        {error && (
          <Alert tone="warning" title="Couldn't refresh">
            {error}
          </Alert>
        )}

        {lastRate && (
          <p className="mb-2 text-xs text-muted">
            Last updated {formatDateTime(lastRate)} · {rates?.length ?? 0} currencies
          </p>
        )}

        {!rates || rates.length === 0 ? (
          <EmptyState
            compact
            icon={<Coins className="h-6 w-6" />}
            title="No rates cached yet"
            description="Connect once and FinTrack downloads the rates it needs; after that, conversions happen offline."
            action={
              <Button variant="primary" size="sm" loading={busy} onClick={() => void refreshRates()}>
                Download rates
              </Button>
            }
          />
        ) : (
          <Card className="max-h-80 divide-y divide-line overflow-y-auto p-0">
            {rates.map((rate) => (
              <div key={rate.code} className="flex items-center justify-between gap-3 px-3 py-2">
                <span className="min-w-0">
                  <span className="block text-sm font-medium text-ink">{rate.code}</span>
                  <span className="block text-xs text-muted">1 {rate.base} = </span>
                </span>
                <span className="flex items-center gap-2">
                  <span className="tabular text-sm text-ink">{rate.rate.toFixed(4)}</span>
                  <button
                    type="button"
                    aria-label={`Remove ${rate.code} rate`}
                    title="Remove cached rate"
                    onClick={() => void deleteExchangeRate(rate.id)}
                    className="rounded p-1 text-muted hover:bg-expense-soft hover:text-expense"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </button>
                </span>
              </div>
            ))}
          </Card>
        )}
      </Panel>
    </div>
  );
}

/**
 * `/settings/financial` — the conventions your reports are built on.
 *
 * The month-start day matters: budgets, the overview and every "this month"
 * figure are cut at that day rather than on the 1st, so reports match how you
 * actually think about a month.
 */
import { Alert, Button, Input, SegmentedControl } from "../../components/ui";
import { useLocalData } from "../analytics/useLocalData";
import { formatMoney, startOfMonth, endOfMonth } from "../../design/format";
import { usePreferences } from "./preferences";
import { Panel, ToggleRow } from "./Panel";

const PAGE_SIZES = [10, 25, 50, 100];

export function FinancialSection() {
  const { preferences, update } = usePreferences();
  const { lookups } = useLocalData();

  const monthStart = startOfMonth(new Date(), preferences.monthStartDay);
  const monthEnd = endOfMonth(new Date(), preferences.monthStartDay);
  const currency = preferences.baseCurrency;

  return (
    <div className="space-y-4">
      <Panel
        title="Financial month"
        description="Where one month ends and the next begins."
      >
        <Input
          label="Month starts on day"
          type="number"
          min={1}
          max={28}
          value={preferences.monthStartDay}
          onChange={(event) => {
            const value = Number(event.target.value);
            if (value >= 1 && value <= 28) void update({ monthStartDay: value });
          }}
          hint="Between 1 and 28 so every month has the same length. Use 25 if you're paid on the 25th."
        />
        <p className="mt-3 rounded-lg bg-surface-sunken px-3 py-2 text-sm text-muted">
          This month runs{" "}
          <span className="font-medium text-ink">
            {monthStart.toLocaleDateString(undefined, { day: "numeric", month: "short" })} –{" "}
            {monthEnd.toLocaleDateString(undefined, { day: "numeric", month: "short" })}
          </span>
          .
        </p>
      </Panel>

      <Panel title="Number formatting" description="How amounts are written across the app.">
        <ToggleRow
          id="fin-cents"
          label="Show cents"
          description="Off rounds to whole units in every table and chart."
          checked={preferences.showCents}
          onChange={(next) => void update({ showCents: next })}
        />
        <ToggleRow
          id="fin-confirm"
          label="Confirm destructive actions"
          description="Ask before deleting something that can't be restored."
          checked={preferences.confirmDestructive}
          onChange={(next) => void update({ confirmDestructive: next })}
        />
        <div className="mt-3">
          <p className="mb-1.5 text-xs font-medium tracking-wide text-muted uppercase">
            Example
          </p>
          <p className="tabular text-title text-ink">
            {formatMoney(1234.56, currency, { showCents: preferences.showCents })}
          </p>
        </div>
      </Panel>

      <Panel title="Lists" description="How many rows load before you scroll.">
        <SegmentedControl
          size="sm"
          options={PAGE_SIZES.map((size) => ({ id: String(size), label: `${size}` }))}
          value={String(preferences.pageSize)}
          onChange={(next) => void update({ pageSize: Number(next) })}
          ariaLabel="Rows per page"
        />
        <p className="mt-2 text-xs text-muted">
          Applies to the transaction list. Everything is paginated from the local database, so
          larger pages cost nothing offline.
        </p>
      </Panel>

      <Alert tone="info" title="Changing the month start re-cuts history">
        Past reports are recomputed on the fly from the same transactions — nothing is rewritten.
        The 12th of last month simply moves into a different bucket.
      </Alert>
    </div>
  );
}

