/**
 * `/settings/notifications` — what reaches the notification centre.
 *
 * The filters are device-level: they decide which alerts are *shown* here.
 * The server keeps generating them either way, so turning something off on one
 * phone doesn't switch off alerting for your account.
 */
import { useState } from "react";
import { Link } from "react-router-dom";
import { BellRing, CalendarClock, CircleAlert, PiggyBank, RefreshCw, Target } from "lucide-react";
import { ApiError, apiFetch } from "../../api/client";
import { Alert, Button, useToast } from "../../components/ui";
import { usePreferences } from "./preferences";
import { Panel, ToggleRow } from "./Panel";

export function NotificationsSection() {
  const { preferences, update } = usePreferences();
  const toast = useToast();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function runChecks() {
    setBusy(true);
    setError(null);
    try {
      const result = await apiFetch<{ budgets: number; debts: number; goals: number }>(
        "/notifications/checks/",
        { method: "POST", body: JSON.stringify({}) },
      );
      const total = result.budgets + result.debts + result.goals;
      toast.push({
        tone: total > 0 ? "info" : "success",
        title: total > 0 ? `${total} new alert${total === 1 ? "" : "s"}` : "Nothing new",
        description: `${result.budgets} budget · ${result.debts} debt · ${result.goals} goal`,
      });
    } catch (err) {
      setError(
        err instanceof ApiError
          ? err.message
          : "Couldn't run the checks. They also run on a schedule while you're signed in.",
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="space-y-4">
      <Panel
        title="Alert checks"
        description="FinTrack watches budgets, debts and goals, then posts an alert when something needs attention."
        footer={
          <>
            <Link
              to="/notifications"
              className="rounded-lg px-2.5 py-1 text-xs font-medium text-primary hover:underline"
            >
              Open notifications
            </Link>
            <Button
              variant="primary"
              size="sm"
              icon={<RefreshCw className={`h-4 w-4 ${busy ? "animate-spin" : ""}`} />}
              loading={busy}
              onClick={() => void runChecks()}
            >
              Check now
            </Button>
          </>
        }
      >
        {error && (
          <Alert tone="warning" title="Couldn't run the checks">
            {error}
          </Alert>
        )}
        <ul className="space-y-2 text-sm text-muted">
          <li className="flex items-start gap-2">
            <PiggyBank aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-primary" />
            A budget crosses the alert threshold you set on it.
          </li>
          <li className="flex items-start gap-2">
            <CalendarClock aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-warning" />
            A debt falls due, or passes its due date.
          </li>
          <li className="flex items-start gap-2">
            <Target aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-income" />
            A savings goal drifts off the pace needed for its target date.
          </li>
        </ul>
      </Panel>

      <Panel
        title="Show on this device"
        description="Choose which kinds appear in the notification centre here."
      >
        <ToggleRow
          id="notify-budgets"
          label="Budget alerts"
          description="Threshold and over-limit warnings."
          checked={preferences.notifyBudgets}
          onChange={(next) => void update({ notifyBudgets: next })}
        />
        <ToggleRow
          id="notify-debts"
          label="Debt reminders"
          description="Due and overdue balances."
          checked={preferences.notifyDebts}
          onChange={(next) => void update({ notifyDebts: next })}
        />
        <ToggleRow
          id="notify-goals"
          label="Goal nudges"
          description="Pace warnings for savings targets."
          checked={preferences.notifyGoals}
          onChange={(next) => void update({ notifyGoals: next })}
        />
        <ToggleRow
          id="notify-other"
          label="Everything else"
          description="Sync problems, generated transactions and system messages."
          checked={preferences.notifyOther}
          onChange={(next) => void update({ notifyOther: next })}
        />
      </Panel>

      <Alert tone="info" title="Alerts never block a transaction">
        Crossing a threshold puts the fact in front of you. It never stops a save, and it never
        changes a number in your ledger.
      </Alert>

      <p className="flex items-center gap-1.5 text-xs text-muted">
        <BellRing aria-hidden="true" className="h-3.5 w-3.5" />
        Push notifications to your home screen are not configured yet — the notification centre is
        the supported surface.
      </p>
      <p className="flex items-center gap-1.5 text-xs text-muted">
        <CircleAlert aria-hidden="true" className="h-3.5 w-3.5" />
        These preferences apply to this device only.
      </p>
    </div>
  );
}

/**
 * `/settings/sync` — queue health and manual control.
 *
 * Everything shown here comes from the real outbox and conflict tables, so the
 * numbers are the ones the engine will act on next run.
 */
import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { AlertTriangle, CloudUpload, RefreshCw, WifiOff } from "lucide-react";
import { useLiveQuery } from "dexie-react-hooks";
import { Badge, Button, Card, DetailRow, Divider, LinkButton } from "../../components/ui";
import { formatDateTime, formatRelativeTime } from "../../design/format";
import { db } from "../../db";
import { pendingMutations } from "../../sync/outbox";
import { useSync } from "../../sync/SyncContext";
import type { OutboxEntry } from "../../db/types";
import { Panel } from "./Panel";

const STATUS_TONE = {
  idle: "income",
  syncing: "primary",
  offline: "warning",
  "signed-out": "neutral",
  error: "danger",
} as const;

export function SyncSection() {
  const { status, pendingCount, conflicts, lastSyncedAt, syncNow } = useSync();
  const [busy, setBusy] = useState(false);
  const [queue, setQueue] = useState<OutboxEntry[]>([]);

  const conflictRows = useLiveQuery(async () => db.conflicts.toArray(), [], undefined);

  useEffect(() => {
    let cancelled = false;
    void pendingMutations(20).then((rows) => {
      if (!cancelled) setQueue(rows);
    });
    return () => {
      cancelled = true;
    };
  }, [pendingCount, status]);

  async function run() {
    setBusy(true);
    try {
      await syncNow();
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="space-y-4">
      <Panel
        title="Connection"
        description="This device pushes local changes and pulls server changes on a 30-second cycle."
        footer={
          <>
            <LinkButton to="/sync/conflicts">
              Conflicts ({(conflictRows ?? conflicts).length})
            </LinkButton>
            <Button
              variant="primary"
              size="sm"
              icon={<RefreshCw className={`h-4 w-4 ${busy ? "animate-spin" : ""}`} />}
              loading={busy}
              onClick={() => void run()}
            >
              Sync now
            </Button>
          </>
        }
      >
        <div className="flex flex-wrap items-center gap-2">
          <Badge tone={STATUS_TONE[status] ?? "neutral"}>{status}</Badge>
          <span className="text-sm text-muted">
            {pendingCount} change{pendingCount === 1 ? "" : "s"} waiting to be pushed
          </span>
        </div>
        <Divider />
        <dl className="space-y-0.5">
          <DetailRow label="Last synced">
            {lastSyncedAt ? formatDateTime(lastSyncedAt) : "Never on this device"}
          </DetailRow>
          <DetailRow label="Last attempt">
            {lastSyncedAt ? formatRelativeTime(lastSyncedAt) : "—"}
          </DetailRow>
          <DetailRow label="Conflicts waiting">
            {(conflictRows ?? conflicts).length}
          </DetailRow>
        </dl>
        {status === "offline" && (
          <p className="mt-3 flex items-start gap-2 rounded-lg bg-warning-soft px-3 py-2 text-sm text-warning">
            <WifiOff aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0" />
            You're offline. Everything you enter is stored on this device and will sync
            automatically when the connection returns.
          </p>
        )}
        {status === "error" && (
          <p className="mt-3 flex items-start gap-2 rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
            <AlertTriangle aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0" />
            The last sync failed. Your changes are safe locally — try again, or open conflicts if
            the server rejected an edit.
          </p>
        )}
      </Panel>

      <Panel title="Outbox" description="Mutations waiting to be sent, newest first.">
        {queue.length === 0 ? (
          <p className="text-sm text-muted">
            Nothing pending — every local edit has been acknowledged by the server.
          </p>
        ) : (
          <ul className="divide-y divide-line">
            {queue.map((entry) => (
              <li key={entry.id} className="flex items-center justify-between gap-3 py-2">
                <span className="min-w-0">
                  <span className="block truncate text-sm text-ink">
                    {entry.op} · {entry.entity}
                  </span>
                  <span className="tabular block text-xs text-muted">
                    {entry.entity_id.slice(0, 8)} · {formatRelativeTime(entry.created_at)}
                  </span>
                </span>
                <span className="flex shrink-0 items-center gap-2">
                  <Badge
                    tone={
                      entry.status === "conflict"
                        ? "danger"
                        : entry.status === "failed"
                          ? "warning"
                          : "neutral"
                    }
                  >
                    {entry.status}
                  </Badge>
                  {entry.attempts > 0 && (
                    <span className="tabular text-xs text-muted">{entry.attempts} tries</span>
                  )}
                </span>
              </li>
            ))}
          </ul>
        )}
      </Panel>

      <Card className="flex items-start gap-3 p-4">
        <CloudUpload aria-hidden="true" className="mt-0.5 h-5 w-5 shrink-0 text-primary" />
        <div className="min-w-0">
          <p className="text-sm font-medium text-ink">How offline editing works</p>
          <p className="mt-0.5 text-xs text-muted">
            Writes land in IndexedDB first and queue a mutation. The engine pushes them in order,
            retries on failure, and surfaces disagreements as conflicts you resolve yourself —
            never by silently overwriting one side.
          </p>
          <Link to="/sync/conflicts" className="mt-1 inline-block text-xs font-medium text-primary hover:underline">
            Review conflicts
          </Link>
        </div>
      </Card>
    </div>
  );
}

/**
 * `/settings/data` — export, import, and clearing this device.
 *
 * CSV export/import go to the server (they need the full account, not just the
 * rows cached here); the JSON snapshot and the reset operate purely on the
 * local IndexedDB copy.
 */
import { useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Database, Download, FileDown, FileUp, Trash2, Upload } from "lucide-react";
import { ApiError, apiFetch } from "../../api/client";
import { Alert, Button, Card, ConfirmOverlay, useToast } from "../../components/ui";
import { formatBytes } from "../../design/format";
import { db, RESETTABLE_TABLES } from "../../db";
import { Panel } from "./Panel";

interface ImportResult {
  created?: number;
  updated?: number;
  skipped?: number;
  errors?: string[];
  dry_run?: boolean;
  [key: string]: unknown;
}

export function DataSection() {
  const toast = useToast();
  const navigate = useNavigate();
  const fileRef = useRef<HTMLInputElement>(null);

  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pendingCsv, setPendingCsv] = useState<string | null>(null);
  const [preview, setPreview] = useState<ImportResult | null>(null);
  const [confirmReset, setConfirmReset] = useState(false);
  const [localSize, setLocalSize] = useState<number | null>(null);

  async function measure() {
    if (navigator.storage?.estimate) {
      const estimate = await navigator.storage.estimate();
      setLocalSize(estimate.usage ?? null);
    }
  }

  async function exportCsv() {
    setBusy("export");
    setError(null);
    try {
      const res = await fetch(
        `${(await import("../../api/client")).API_BASE_URL}/transactions/export/`,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("fintrack_access") ?? ""}`,
          },
        },
      );
      if (!res.ok) throw new ApiError(res.status, "Export failed");
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `fintrack-transactions-${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
      URL.revokeObjectURL(url);
      toast.push({ tone: "success", title: "CSV exported" });
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Couldn't export right now.");
    } finally {
      setBusy(null);
    }
  }

  async function exportSnapshot() {
    setBusy("snapshot");
    try {
      const snapshot = {
        exported_at: new Date().toISOString(),
        accounts: await db.accounts.toArray(),
        categories: await db.categories.toArray(),
        tags: await db.tags.toArray(),
        transactions: await db.transactions.toArray(),
        budgets: await db.budgets.toArray(),
        recurring: await db.recurring.toArray(),
        installments: await db.installments.toArray(),
        debts: await db.debts.toArray(),
        savings_goals: await db.savings_goals.toArray(),
        exchange_rates: await db.exchange_rates.toArray(),
        notifications: await db.notifications.toArray(),
      };
      const blob = new Blob([JSON.stringify(snapshot, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `fintrack-snapshot-${new Date().toISOString().slice(0, 10)}.json`;
      link.click();
      URL.revokeObjectURL(url);
      toast.push({ tone: "success", title: "Snapshot saved" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't build the snapshot.");
    } finally {
      setBusy(null);
    }
  }

  async function readFile(file: File) {
    const text = await file.text();
    setPendingCsv(text);
    setPreview(null);
    setBusy("dry-run");
    setError(null);
    try {
      const result = await apiFetch<ImportResult>("/transactions/import_csv/", {
        method: "POST",
        body: JSON.stringify({ csv: text, dry_run: true }),
      });
      setPreview(result);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Couldn't read that file.");
      setPendingCsv(null);
    } finally {
      setBusy(null);
    }
  }

  async function commitImport() {
    if (!pendingCsv) return;
    setBusy("import");
    setError(null);
    try {
      const result = await apiFetch<ImportResult>("/transactions/import_csv/", {
        method: "POST",
        body: JSON.stringify({ csv: pendingCsv, dry_run: false }),
      });
      toast.push({
        tone: "success",
        title: "Import finished",
        description: `${result.created ?? 0} added · ${result.updated ?? 0} updated · ${result.skipped ?? 0} skipped`,
      });
      setPendingCsv(null);
      setPreview(null);
      if (fileRef.current) fileRef.current.value = "";
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Import failed.");
    } finally {
      setBusy(null);
    }
  }

  async function resetLocal() {
    setBusy("reset");
    try {
      for (const table of RESETTABLE_TABLES) await table.clear();
      toast.push({
        tone: "success",
        title: "Local data cleared",
        description: "Signing in again downloads a fresh copy from the server.",
      });
      navigate("/overview");
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't clear local data",
        description: err instanceof Error ? err.message : undefined,
      });
    } finally {
      setBusy(null);
      setConfirmReset(false);
    }
  }

  return (
    <div className="space-y-4">
      <Panel
        title="Export"
        description="Take your data with you — CSV for spreadsheets, JSON for a full local snapshot."
        footer={
          <>
            <Button
              variant="secondary"
              size="sm"
              icon={<FileDown className="h-4 w-4" />}
              loading={busy === "export"}
              onClick={() => void exportCsv()}
            >
              CSV
            </Button>
            <Button
              variant="secondary"
              size="sm"
              icon={<Download className="h-4 w-4" />}
              loading={busy === "snapshot"}
              onClick={() => void exportSnapshot()}
            >
              JSON snapshot
            </Button>
          </>
        }
      >
        <p className="text-sm text-muted">
          The CSV is produced by the server from your full transaction history. The JSON snapshot
          is whatever is cached on this device right now — useful as a backup before clearing it.
        </p>
        {error && (
          <p role="alert" className="mt-2 rounded-lg bg-expense-soft px-3 py-2 text-sm text-expense">
            {error}
          </p>
        )}
      </Panel>

      <Panel
        title="Import CSV"
        description="Preview first — nothing is written until you confirm."
        footer={
          preview ? (
            <>
              <Button variant="ghost" size="sm" onClick={() => { setPreview(null); setPendingCsv(null); }}>
                Cancel
              </Button>
              <Button variant="primary" size="sm" loading={busy === "import"} onClick={() => void commitImport()}>
                Import
              </Button>
            </>
          ) : undefined
        }
      >
        <input
          ref={fileRef}
          type="file"
          accept=".csv,text/csv"
          aria-label="CSV file to import"
          className="block w-full text-sm text-muted file:mr-3 file:rounded-lg file:border-0 file:bg-primary-soft-bg file:px-3 file:py-1.5 file:text-sm file:font-medium file:text-primary"
          onChange={(event) => {
            const file = event.target.files?.[0];
            if (file) void readFile(file);
          }}
        />

        {preview && (
          <Card className="mt-3 bg-surface-sunken p-3">
            <p className="text-sm font-medium text-ink">Dry run result</p>
            <ul className="mt-1 space-y-0.5 text-sm text-muted">
              <li>Would create: {preview.created ?? 0}</li>
              <li>Would update: {preview.updated ?? 0}</li>
              <li>Would skip: {preview.skipped ?? 0}</li>
            </ul>
            {Array.isArray(preview.errors) && preview.errors.length > 0 && (
              <ul className="mt-2 max-h-32 overflow-y-auto space-y-0.5 text-xs text-expense">
                {preview.errors.slice(0, 10).map((line) => (
                  <li key={line}>{line}</li>
                ))}
              </ul>
            )}
          </Card>
        )}
      </Panel>

      <Panel
        title="This device"
        description="Everything below acts on the local copy only — your server data is untouched."
        footer={
          <Button
            variant="danger"
            size="sm"
            icon={<Trash2 className="h-4 w-4" />}
            onClick={() => void measure().then(() => setConfirmReset(true))}
          >
            Clear local data
          </Button>
        }
      >
        <p className="flex items-center gap-2 text-sm text-muted">
          <Database aria-hidden="true" className="h-4 w-4 shrink-0" />
          {localSize !== null
            ? `Using ${formatBytes(localSize)} of storage on this device.`
            : "IndexedDB holds accounts, transactions, reports and the sync queue."}
        </p>
        <Alert tone="warning" title="Clearing requires a re-sync">
          Queued but unsent changes are discarded with the local copy, so sync first if you have
          a weak connection.
        </Alert>
      </Panel>

      <ConfirmOverlay
        open={confirmReset}
        busy={busy === "reset"}
        tone="danger"
        onClose={() => setConfirmReset(false)}
        onConfirm={() => void resetLocal()}
        title="Clear local data on this device?"
        confirmLabel="Clear everything"
        message="Anything not yet pushed to the server will be lost. Signed-in data on the server is not affected."
      />
    </div>
  );
}

