/**
 * `/settings/devices` — sessions issued to your account.
 *
 * Each row is an outstanding refresh token, which is what a "device" really is
 * here. Revoking one invalidates it immediately on the next request.
 */
import { useCallback, useEffect, useState } from "react";
import { LogOut, MonitorSmartphone, RefreshCw } from "lucide-react";
import { ApiError, apiFetch } from "../../api/client";
import { Alert, Badge, Button, Card, EmptyState, useToast } from "../../components/ui";
import { formatDateTime } from "../../design/format";
import { getAccessToken } from "../../api/client";
import { Panel } from "./Panel";

interface Session {
  id: string;
  created_at: string;
  expires_at: string;
}

export function DevicesSection() {
  const toast = useToast();
  const [sessions, setSessions] = useState<Session[] | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    try {
      const data = await apiFetch<Session[] | Session[]>("/auth/sessions/");
      setSessions(Array.isArray(data) ? data : []);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Couldn't load sessions.");
      setSessions((current) => current ?? []);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  async function revoke(id: string) {
    setBusy(true);
    try {
      await apiFetch("/auth/sessions/", {
        method: "DELETE",
        body: JSON.stringify({ id }),
      });
      setSessions((current) => (current ?? []).filter((row) => row.id !== id));
      toast.push({ tone: "success", title: "Session revoked" });
    } catch (err) {
      toast.push({
        tone: "error",
        title: "Couldn't revoke session",
        description: err instanceof ApiError ? err.message : undefined,
      });
    } finally {
      setBusy(false);
    }
  }

  const currentToken = getAccessToken();

  return (
    <div className="space-y-4">
      <Panel
        title="Active sessions"
        description="Every browser or phone that can refresh a token for your account."
        footer={
          <Button
            variant="secondary"
            size="sm"
            icon={<RefreshCw className={`h-4 w-4 ${busy ? "animate-spin" : ""}`} />}
            loading={busy}
            onClick={() => void load()}
          >
            Refresh
          </Button>
        }
      >
        {error && (
          <Alert tone="warning" title="Couldn't load sessions">
            {error}
          </Alert>
        )}

        {sessions === null ? (
          <p className="text-sm text-muted">Loading sessions…</p>
        ) : sessions.length === 0 ? (
          <EmptyState
            compact
            icon={<MonitorSmartphone className="h-6 w-6" />}
            title={error ? "Sessions unavailable" : "No other sessions"}
            description={
              error
                ? "You appear to be signed out on the server, or the request failed."
                : "Sign in on another device and it will appear here."
            }
            action={
              <Button variant="secondary" size="sm" onClick={() => void load()}>
                Try again
              </Button>
            }
          />
        ) : (
          <ul className="divide-y divide-line">
            {sessions.map((session) => (
              <li key={session.id} className="flex items-start justify-between gap-3 py-2.5">
                <div className="min-w-0">
                  <p className="flex items-center gap-2 text-sm font-medium text-ink">
                    <MonitorSmartphone aria-hidden="true" className="h-4 w-4 shrink-0 text-muted" />
                    <span className="tabular truncate">Session {session.id.slice(0, 8)}</span>
                  </p>
                  <p className="tabular mt-0.5 text-xs text-muted">
                    Started {formatDateTime(session.created_at)} · expires{" "}
                    {formatDateTime(session.expires_at)}
                  </p>
                </div>
                <div className="flex shrink-0 items-center gap-2">
                  {currentToken && session.id && (
                    <Badge tone="neutral">Active</Badge>
                  )}
                  <Button
                    variant="ghost"
                    size="sm"
                    icon={<LogOut className="h-3.5 w-3.5" />}
                    disabled={busy}
                    onClick={() => void revoke(session.id)}
                  >
                    Revoke
                  </Button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </Panel>

      <Card className="p-4">
        <p className="text-sm text-muted">
          Revoking a session blacklists its refresh token. The device is signed out the next time
          it tries to renew — this device included, if you revoke your own.
        </p>
      </Card>
    </div>
  );
}

/**
 * `/settings/about` — version, storage and what this build is made of.
 */
import { useEffect, useState } from "react";
import { ExternalLink, HardDrive, Info } from "lucide-react";
import { Badge, Card, DetailRow, Divider, LinkButton } from "../../components/ui";
import { formatBytes } from "../../design/format";
import { Panel } from "./Panel";

const TECH = [
  ["Frontend", "React + TypeScript + Vite"],
  ["Local database", "Dexie / IndexedDB"],
  ["Backend", "Django + Django REST Framework"],
  ["Database", "Neon PostgreSQL"],
  ["Icons", "Lucide React"],
  ["Charts", "Hand-rolled SVG on design tokens"],
];

export function AboutSection() {
  const [usage, setUsage] = useState<number | null>(null);
  const [quota, setQuota] = useState<number | null>(null);

  useEffect(() => {
    if (!navigator.storage?.estimate) return;
    void navigator.storage.estimate().then((estimate) => {
      setUsage(estimate.usage ?? null);
      setQuota(estimate.quota ?? null);
    });
  }, []);

  const version =
    (import.meta.env.VITE_APP_VERSION as string | undefined) ?? "development";

  return (
    <div className="space-y-4">
      <Panel title="FinTrack" description="Personal money manager — offline first.">
        <dl className="space-y-0.5">
          <DetailRow label="Version">{version}</DetailRow>
          <DetailRow label="Build">{import.meta.env.MODE}</DetailRow>
          <DetailRow label="Storage">
            {usage !== null ? `${formatBytes(usage)} used` : "Not reported"}
          </DetailRow>
          <DetailRow label="Quota">
            {quota !== null ? formatBytes(quota) : "Not reported"}
          </DetailRow>
        </dl>
        <Divider />
        <div className="flex flex-wrap gap-2">
          <LinkButton to="/settings/data">Manage data</LinkButton>
          <LinkButton to="/sync/conflicts">Sync conflicts</LinkButton>
        </div>
      </Panel>

      <Panel title="How it's built">
        <dl className="space-y-0.5">
          {TECH.map(([label, value]) => (
            <DetailRow key={label} label={label}>
              {value}
            </DetailRow>
          ))}
        </dl>
      </Panel>

      <Panel title="Offline behaviour">
        <p className="text-sm text-muted">
          Every screen reads from this device's database first. Reports, budgets, the calendar and
          search are computed locally, so they work with no connection at all. Changes you make
          offline queue up and are pushed the next time you're online — nothing is lost, and
          nothing is silently overwritten.
        </p>
      </Panel>

      <Card className="flex items-start gap-3 p-4">
        <Info aria-hidden="true" className="mt-0.5 h-5 w-5 shrink-0 text-primary" />
        <div className="min-w-0">
          <p className="text-sm font-medium text-ink">Your data stays yours</p>
          <p className="mt-0.5 text-xs text-muted">
            No analytics, no advertising identifiers, no third-party trackers. Export everything at
            any time from Data settings.
          </p>
          <a
            href="https://lucide.dev"
            target="_blank"
            rel="noreferrer noopener"
            className="mt-1 inline-flex items-center gap-1 text-xs font-medium text-primary hover:underline"
          >
            Icon set: Lucide <ExternalLink aria-hidden="true" className="h-3 w-3" />
          </a>
        </div>
      </Card>

      <p className="flex items-center gap-1.5 text-xs text-muted">
        <HardDrive aria-hidden="true" className="h-3.5 w-3.5" />
        Storage figures come from the browser's storage estimate and may be approximate.
        <Badge tone="neutral">{import.meta.env.MODE}</Badge>
      </p>
    </div>
  );
}

/**
 * `/mfa` — the two-factor challenge.
 *
 * Reached from the sign-in form when the server answers `mfa_required`. The
 * credentials being verified are held in sessionStorage for this step only and
 * cleared the moment the challenge succeeds or is abandoned, so a shared
 * machine never keeps a password lying around.
 */
import { useState, type FormEvent } from "react";
import { Link, useNavigate } from "react-router-dom";
import { ArrowRight, ShieldCheck } from "lucide-react";
import { ApiError } from "../../api/client";
import { useAuth } from "../../auth/AuthContext";
import { Button } from "../../components/ui/Button";
import { Input } from "../../components/ui/Input";
import { AuthLayout, FormError } from "./AuthLayout";

const PENDING_KEY = "fintrack_mfa_pending";

export interface MfaPending {
  email: string;
  password: string;
}

export function stashMfaCredentials(pending: MfaPending): void {
  sessionStorage.setItem(PENDING_KEY, JSON.stringify(pending));
}

export function readMfaCredentials(): MfaPending | null {
  try {
    const raw = sessionStorage.getItem(PENDING_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<MfaPending>;
    if (!parsed.email || !parsed.password) return null;
    return { email: parsed.email, password: parsed.password };
  } catch {
    return null;
  }
}

export function clearMfaCredentials(): void {
  sessionStorage.removeItem(PENDING_KEY);
}

export function MfaPage() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const pending = readMfaCredentials();

  const [otp, setOtp] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (!pending) return;
    setError(null);
    setBusy(true);
    try {
      const result = await login(pending.email, pending.password, otp.trim());
      clearMfaCredentials();
      if (result.mfaRequired) {
        setError("That code wasn't accepted. Try the current one from your app.");
        return;
      }
      navigate("/overview", { replace: true });
    } catch (err) {
      setError(
        err instanceof ApiError
          ? err.message || "That code wasn't accepted."
          : "Couldn't reach the server. Check your connection and try again.",
      );
    } finally {
      setBusy(false);
    }
  }

  // Opened directly (bookmark, refresh, shared link) with nothing to verify.
  if (!pending) {
    return (
      <AuthLayout
        title="Two-factor sign-in"
        subtitle="This step follows a sign-in attempt that needs a code."
        footer={
          <Link to="/login" className="font-medium text-primary hover:underline">
            Back to sign in
          </Link>
        }
      >
        <p className="rounded-xl bg-surface-sunken px-4 py-3 text-sm text-muted">
          Enter your email and password first and FinTrack will bring you straight here when your
          account has two-factor authentication enabled.
        </p>
        <Link to="/login" className="btn-primary mt-4 w-full">
          Sign in
        </Link>
      </AuthLayout>
    );
  }

  return (
    <AuthLayout
      title="Enter your code"
      subtitle={`Open your authenticator app for ${pending.email}.`}
      footer={
        <button
          type="button"
          onClick={() => {
            clearMfaCredentials();
            navigate("/login", { replace: true });
          }}
          className="font-medium text-primary hover:underline"
        >
          Use a different account
        </button>
      }
    >
      <form onSubmit={submit} className="space-y-4" noValidate>
        {error && <FormError message={error} />}
        <Input
          label="Two-factor code"
          inputMode="numeric"
          autoComplete="one-time-code"
          maxLength={6}
          required
          value={otp}
          onChange={(event) => setOtp(event.target.value.replace(/\D/g, ""))}
          leadingIcon={<ShieldCheck aria-hidden="true" className="h-4 w-4" />}
          placeholder="123456"
          fieldClassName="[&_input]:tracking-[0.4em]"
          autoFocus
        />
        <Button
          type="submit"
          variant="primary"
          size="lg"
          block
          loading={busy}
          disabled={otp.length !== 6}
          trailingIcon={<ArrowRight className="h-4 w-4" />}
        >
          Verify and sign in
        </Button>
      </form>
    </AuthLayout>
  );
}

