/**
 * Generates the PWA app icons from code, so the marks always match the theme
 * (Deep Emerald #0F766E, Mint accent #2DD4BF) and never depend on a binary
 * asset being committed by hand.
 *
 *   node scripts/generate-icons.mjs
 *
 * Outputs into `public/icons/`. Uses nothing but Node's built-in `zlib`.
 */
import { deflateSync } from "node:zlib";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT = join(HERE, "..", "public", "icons");

const PRIMARY = [15, 116, 110]; // #0F766E
const ACCENT = [45, 212, 191]; // #2DD4BF
const INK = [255, 255, 255];

/* --------------------------------------------------------------- rasterising */

/** Coverage of a rounded-rectangle spanning [x0,x1) x [y0,y1) at pixel (px,py). */
function roundedRectCoverage(px, py, x0, y0, x1, y1, r) {
  const cx = Math.min(Math.max(px, x0 + r), x1 - r);
  const cy = Math.min(Math.max(py, y0 + r), y1 - r);
  const dx = px - cx;
  const dy = py - cy;
  if (dx * dx + dy * dy <= r * r) return 1;
  return 0;
}

function circleCoverage(px, py, cx, cy, r) {
  const dx = px - cx;
  const dy = py - cy;
  return dx * dx + dy * dy <= r * r ? 1 : 0;
}

function blend(buffer, size, px, py, [r, g, b], alpha) {
  if (alpha <= 0) return;
  const i = (py * size + px) * 4;
  const a = alpha;
  buffer[i] = Math.round(r * a + buffer[i] * (1 - a));
  buffer[i + 1] = Math.round(g * a + buffer[i + 1] * (1 - a));
  buffer[i + 2] = Math.round(b * a + buffer[i + 2] * (1 - a));
  buffer[i + 3] = Math.round(255 * a + buffer[i + 3] * (1 - a));
}

function render(size, { maskable }) {
  const buffer = Buffer.alloc(size * size * 4);
  // Maskable art must survive a circular crop, so it is scaled into the middle
  // 66% of the canvas; regular icons fill the whole (rounded) square.
  const scale = maskable ? 0.66 : 0.86;
  const s = size;
  const t = (v) => s / 2 + (v - 0.5) * s * scale;

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const px = x + 0.5;
      const py = y + 0.5;

      // Background plate.
      const radius = maskable ? 0 : s * 0.2;
      if (radius === 0 || roundedRectCoverage(px, py, 0, 0, s, s, radius)) {
        blend(buffer, size, x, y, PRIMARY, 1);
      }

      // Three ascending bars — accounts, budgets, growth.
      const barW = s * 0.115 * scale;
      const gap = s * 0.055 * scale;
      const baseline = t(0.76);
      const heights = [0.2, 0.33, 0.47];
      const total = barW * 3 + gap * 2;
      const startX = s / 2 - total / 2;
      heights.forEach((h, index) => {
        const x0 = startX + index * (barW + gap);
        const x1 = x0 + barW;
        const y0 = baseline - h * s * scale;
        const y1 = baseline;
        if (roundedRectCoverage(px, py, x0, y0, x1, y1, barW / 2)) {
          blend(buffer, size, x, y, INK, 1);
        }
      });

      // Mint coin marking the balance point.
      if (circleCoverage(px, py, t(0.76), t(0.3), s * 0.085 * scale)) {
        blend(buffer, size, x, y, ACCENT, 1);
      }
    }
  }
  return buffer;
}

/* ------------------------------------------------------------------ png out */

function crc32(buf) {
  let c;
  const table = crc32.table ?? (crc32.table = buildTable());
  let crc = 0xffffffff;
  for (let n = 0; n < buf.length; n += 1) {
    c = (crc ^ buf[n]) & 0xff;
    crc = (crc >>> 8) ^ table[c];
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function buildTable() {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return table;
}

function chunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const typeBuf = Buffer.from(type, "ascii");
  const crcBuf = Buffer.alloc(4);
  crcBuf.writeUInt32BE(crc32(Buffer.concat([typeBuf, data])), 0);
  return Buffer.concat([length, typeBuf, data, crcBuf]);
}

function encodePng(rgba, size) {
  const raw = Buffer.alloc((size * 4 + 1) * size);
  for (let y = 0; y < size; y += 1) {
    raw[y * (size * 4 + 1)] = 0; // filter: none
    rgba.copy(raw, y * (size * 4 + 1) + 1, y * size * 4, (y + 1) * size * 4);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // truecolour + alpha
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

/* -------------------------------------------------------------------- main */

mkdirSync(OUT, { recursive: true });

const targets = [
  ["icon-192.png", 192, false],
  ["icon-512.png", 512, false],
  ["maskable-512.png", 512, true],
  ["apple-touch-icon.png", 180, false],
];

for (const [name, size, maskable] of targets) {
  writeFileSync(join(OUT, name), encodePng(render(size, { maskable }), size));
  process.stdout.write(`wrote public/icons/${name}\n`);
}

/* eslint-env serviceworker */
/**
 * FinTrack service worker.
 *
 * The ledger itself lives in IndexedDB, so the job here is narrower: keep the
 * *app shell* (HTML, JS, CSS, icons) available with no connection, and get out
 * of the way of the API. Third-party and API requests are never cached — data
 * freshness is handled by the sync engine, not by HTTP caching.
 *
 * Bump VERSION whenever the precached shell changes.
 */
const VERSION = "fintrack-shell-v1";
const SHELL_CACHE = `${VERSION}-shell`;
const RUNTIME_CACHE = `${VERSION}-runtime`;

const SHELL = [
  "/",
  "/index.html",
  "/manifest.webmanifest",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/maskable-512.png",
  "/icons/apple-touch-icon.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // `addAll` fails wholesale if any single request 404s, so add one by one.
      await Promise.all(
        SHELL.map((url) =>
          cache.add(new Request(url, { cache: "reload" })).catch(() => undefined),
        ),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key !== SHELL_CACHE && key !== RUNTIME_CACHE)
          .map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    })(),
  );
});

/** Navigations: prefer the network so a deploy lands immediately. */
async function handleNavigation(request) {
  try {
    const fresh = await fetch(request);
    const cache = await caches.open(SHELL_CACHE);
    void cache.put("/index.html", fresh.clone());
    return fresh;
  } catch {
    const cache = await caches.open(SHELL_CACHE);
    const cached = (await cache.match("/index.html")) || (await cache.match("/"));
    if (cached) return cached;
    return new Response("Offline", { status: 503, headers: { "Content-Type": "text/plain" } });
  }
}

/** Hashed assets: cache-first, refreshed in the background. */
async function handleAsset(request) {
  const cache = await caches.open(RUNTIME_CACHE);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response && response.ok) void cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);
  return cached || (await network) || Response.error();
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  // The API is cross-origin and must reach the network every time.
  if (url.origin !== self.location.origin) return;

  if (request.mode === "navigate") {
    event.respondWith(handleNavigation(request));
    return;
  }

  if (
    url.pathname.startsWith("/assets/") ||
    /\.(js|css|png|svg|webp|woff2?|json|webmanifest)$/.test(url.pathname)
  ) {
    event.respondWith(handleAsset(request));
  }
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") void self.skipWaiting();
});

/**
 * Service-worker registration, install and update handling.
 *
 * Registered in production only — in dev the Vite server is the source of truth
 * and a cached shell would only get in the way. Update availability is exposed
 * as a tiny observable so the banner can sit anywhere in the tree without
 * threading props through the router.
 */

export interface UpdateHandle {
  /** Activate the waiting worker and reload into the new version. */
  apply: () => void;
}

type Listener = (update: UpdateHandle | null) => void;

let pendingUpdate: UpdateHandle | null = null;
const listeners = new Set<Listener>();

function emit(update: UpdateHandle | null) {
  pendingUpdate = update;
  for (const listener of listeners) listener(update);
}

export function subscribeToUpdate(listener: Listener): () => void {
  listeners.add(listener);
  listener(pendingUpdate);
  return () => listeners.delete(listener);
}

export function getPendingUpdate(): UpdateHandle | null {
  return pendingUpdate;
}

export function registerServiceWorker(): void {
  if (!import.meta.env.PROD) return;
  if (typeof navigator === "undefined" || !("serviceWorker" in navigator)) return;

  window.addEventListener("load", () => {
    void navigator.serviceWorker
      .register("/sw.js", { scope: "/" })
      .then((registration) => {
        const announce = (worker: ServiceWorker | null) => {
          if (!worker) return;
          emit({
            apply: () => {
              worker.postMessage({ type: "SKIP_WAITING" });
            },
          });
        };

        // A previous visit already left a new worker waiting.
        if (registration.waiting && navigator.serviceWorker.controller) {
          announce(registration.waiting);
        }

        registration.addEventListener("updatefound", () => {
          const installing = registration.installing;
          if (!installing) return;
          installing.addEventListener("statechange", () => {
            if (installing.state !== "installed") return;
            if (navigator.serviceWorker.controller) announce(installing);
          });
        });

        let reloading = false;
        navigator.serviceWorker.addEventListener("controllerchange", () => {
          if (reloading) return;
          reloading = true;
          emit(null);
          window.location.reload();
        });
      })
      .catch(() => {
        /* Registration failing must never break the app. */
      });
  });
}

/**
 * Persistent connection + update banner.
 *
 * Fixed to the bottom of the viewport (above the mobile bottom nav) so it is
 * visible on every screen without pushing content around. Being offline is not
 * an error — it is a supported state — so the copy says what happens to the
 * work rather than apologising for the connection.
 */
import { useEffect, useState } from "react";
import { CloudUpload, RefreshCw, WifiOff } from "lucide-react";
import { subscribeToUpdate, type UpdateHandle } from "../../app/pwa";
import { useSync } from "../../sync/SyncContext";

export function NetworkBanner() {
  const [online, setOnline] = useState(() =>
    typeof navigator === "undefined" ? true : navigator.onLine,
  );
  const [update, setUpdate] = useState<UpdateHandle | null>(null);
  const { pendingCount } = useSync();

  useEffect(() => {
    const on = () => setOnline(true);
    const off = () => setOnline(false);
    window.addEventListener("online", on);
    window.addEventListener("offline", off);
    return () => {
      window.removeEventListener("online", on);
      window.removeEventListener("offline", off);
    };
  }, []);

  useEffect(() => subscribeToUpdate(setUpdate), []);

  if (update) {
    return (
      <div
        role="status"
        className="fixed inset-x-3 bottom-20 z-[45] flex items-center justify-between gap-3 rounded-xl border border-primary/40 bg-surface px-3 py-2.5 shadow-lg backdrop-blur sm:inset-x-auto sm:right-4 sm:bottom-4 sm:max-w-sm lg:bottom-4"
      >
        <span className="flex min-w-0 items-center gap-2 text-sm text-ink">
          <CloudUpload aria-hidden="true" className="h-4 w-4 shrink-0 text-primary" />
          <span className="min-w-0">A new version of FinTrack is ready.</span>
        </span>
        <button
          type="button"
          onClick={update.apply}
          className="inline-flex shrink-0 items-center gap-1.5 rounded-lg bg-primary px-2.5 py-1.5 text-xs font-medium text-primary-contrast transition-colors hover:bg-primary-hover"
        >
          <RefreshCw aria-hidden="true" className="h-3.5 w-3.5" />
          Update
        </button>
      </div>
    );
  }

  if (online) return null;

  return (
    <div
      role="status"
      aria-live="polite"
